function mergeDefaults(def,obj){
 if(Array.isArray(def)) return Array.isArray(obj)?obj:def;
 if(def&&typeof def==='object'){
   const out={}; Object.keys(def).forEach(k=>out[k]=mergeDefaults(def[k],obj&&obj[k]));
   if(obj&&typeof obj==='object') Object.keys(obj).forEach(k=>{if(!(k in out))out[k]=obj[k]});
   return out;
 }
 return obj===undefined||obj===null?def:obj;
}
function normalizeState(s){
 let n=mergeDefaults(DEFAULT,s||{});
 // v0.1 migration
 if(s&&s.build&&s.build.rank!==undefined)n.build.rank=s.build.rank;
 if(s&&s.skills)n.skills=[0,1,2,3].map(i=>mergeDefaults(baseSkill(),s.skills[i]||{}));
 n.charms=[0,1,2,3].map(i=>mergeDefaults(baseCharm(),(s&&s.charms||[])[i]||{}));
 n.pvp.skills=[0,1,2,3].map(i=>mergeDefaults(baseSkill(),(s&&s.pvp&&s.pvp.skills||[])[i]||{}));
 n.pvp.charms=[0,1,2,3].map(i=>mergeDefaults(baseCharm(),(s&&s.pvp&&s.pvp.charms||[])[i]||{}));
 n.fantomon=mergeDefaults(baseFantomon(),s&&s.fantomon||{});
 n.pveFantomon=mergeDefaults({useMyBuild:true,fantomon:baseFantomon()},s&&s.pveFantomon||{});
 n.pvp.enemyFantomon=mergeDefaults(baseFantomon(),s&&s.pvp&&s.pvp.enemyFantomon||{});
 return n;
}
