function fmt(v,d=0){if(!Number.isFinite(+v))return '—';return (+v).toLocaleString(undefined,{maximumFractionDigits:d,minimumFractionDigits:d})}
function pct(v,d=2){return (v>=0?'+':'')+(+v).toFixed(d)+'%'}
function clamp(x,a,b){return Math.max(a,Math.min(b,x))}
function esc(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function num(id){const v=parseFloat($(id)?.value);return Number.isFinite(v)?v:0}
function toast(t){const e=$('toast');e.textContent=t;e.hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>e.hidden=true,2200)}
function rankObj(name){return DM.ranks.find(r=>r.name===name)||DM.ranks[12]||DM.ranks[0]}
function skillRankNum(labelOrNum){
 if(String(labelOrNum).match(/^\d+$/))return clamp(parseInt(labelOrNum,10),1,34);
 const x=SKILL_RANK_OPTIONS.find(o=>o.label.toLowerCase()===String(labelOrNum).toLowerCase());return x?+x.value:22;
}
function optionObjs(xs){return xs.map(x=>typeof x==='string'?{label:x,value:x}:x)}

// ---------- custom free-type combobox with Tab-to-accept ----------
function attachCombo(input, optionsProvider, onSelect){
 if(!input||input.dataset.comboAttached)return;
 input.dataset.comboAttached='1';
 const wrap=document.createElement('div');wrap.className='combo-wrap';
 input.parentNode.insertBefore(wrap,input);wrap.appendChild(input);
 const btn=document.createElement('button');btn.type='button';btn.className='combo-button';btn.setAttribute('aria-label','Show suggestions');btn.textContent='⌄';wrap.appendChild(btn);
 const hint=document.createElement('div');hint.className='combo-suggest';wrap.appendChild(hint);
 const menu=document.createElement('div');menu.className='combo-menu';menu.hidden=true;wrap.appendChild(menu);
 let shown=[],active=0;
 const all=()=>optionObjs(typeof optionsProvider==='function'?optionsProvider():optionsProvider||[]);
 function filter(showAll=false){
   const q=input.value.trim().toLowerCase();
   const arr=all();
   shown=(showAll||!q?arr:arr.filter(o=>o.label.toLowerCase().includes(q))).slice(0,80);
   if(q)shown.sort((a,b)=>{const as=a.label.toLowerCase().startsWith(q)?0:1,bs=b.label.toLowerCase().startsWith(q)?0:1;return as-bs||a.label.localeCompare(b.label)});
   active=0;render();
 }
 function render(){
   menu.innerHTML=shown.slice(0,18).map((o,i)=>`<button type="button" class="combo-option ${i===active?'active':''}" data-i="${i}"><span>${esc(o.label)}</span>${o.sub?`<small>${esc(o.sub)}</small>`:''}</button>`).join('');
   menu.hidden=!shown.length;
   const top=shown[0]; hint.textContent=top&&top.label.toLowerCase()!==input.value.trim().toLowerCase()?`Tab to fill: ${top.label}`:'';
   menu.querySelectorAll('.combo-option').forEach(b=>b.addEventListener('mousedown',e=>{e.preventDefault();choose(shown[+b.dataset.i])}));
 }
 function choose(o){if(!o)return;input.value=o.label;menu.hidden=true;hint.textContent='';if(onSelect)onSelect(o);input.dispatchEvent(new Event('change',{bubbles:true}));}
 input.addEventListener('focus',()=>filter(false));
 input.addEventListener('input',()=>filter(false));
 input.addEventListener('blur',()=>setTimeout(()=>{menu.hidden=true;hint.textContent=''},120));
 input.addEventListener('keydown',e=>{
   if(e.key==='Tab'&&!menu.hidden&&shown[0]&&shown[0].label.toLowerCase()!==input.value.trim().toLowerCase()){e.preventDefault();choose(shown[0]);input.focus();return;}
   if(e.key==='ArrowDown'&&!menu.hidden){e.preventDefault();active=Math.min(active+1,Math.min(17,shown.length-1));render();}
   else if(e.key==='ArrowUp'&&!menu.hidden){e.preventDefault();active=Math.max(0,active-1);render();}
   else if(e.key==='Enter'&&!menu.hidden&&shown[active]){e.preventDefault();choose(shown[active]);}
   else if(e.key==='Escape'){menu.hidden=true;hint.textContent='';}
 });
 btn.addEventListener('click',()=>{input.focus();filter(true)});
 combos.push({input,filter});
}

