 box.appendChild(row);
 const keyInput=row.querySelector('.stat-key'); keyInput.dataset.key=key;
 attachCombo(keyInput,statOptions,o=>{keyInput.dataset.key=o.value;recalc()});
 keyInput.addEventListener('change',()=>{keyInput.dataset.key=STAT_KEY[keyInput.value.toLowerCase()]||keyInput.dataset.key||keyInput.value;recalc()});
