function readItem(side){
 const rows=[...$(side+'ItemStats').querySelectorAll('.stat-row')].map(r=>[r.querySelector('.stat-key').dataset.key||STAT_KEY[r.querySelector('.stat-key').value.toLowerCase()]||r.querySelector('.stat-key').value,numFrom(r.querySelector('.stat-value'))]);
 return {name:$(side+'ItemName').value||'Custom item',type:$(side+'ItemType').value,quality:$(side+'ItemQuality').value,secondary:$(side+'ItemSecondary').value,stats:rows,source:$(side+'Source').textContent==='Source'?'datamine':'custom',meta:$(side+'ItemMeta').textContent};
}
function numFrom(el){const v=parseFloat(el.value);return Number.isFinite(v)?v:0}
function gearMain(g){
 if(g.main)return [g.main.key,g.main.value];
 if(g.mainByLevel){const level=String(Math.round(num('myLevel')));if(g.mainByLevel[level]!=null)return [g.mainKey,g.mainByLevel[level]];}
 return null;
}
function applyGear(side,g){
 if(!g)return;
 $(side+'ItemName').value=g.name;$(side+'ItemType').value=g.type||'';$(side+'ItemQuality').value=g.quality||'';$(side+'Source').textContent='Source';$(side+'Source').className='source-badge exact';
 const main=gearMain(g);const rows=[];if(main)rows.push(main);
 const secInput=$(side+'ItemSecondary');let sec=g.secondaries?.find(x=>x.label===secInput.value)||g.secondaries?.[0];
 if(sec){secInput.value=sec.label;rows.push([sec.key,sec.value]);}else secInput.value='';
 renderItemRows(side,rows.length?rows:[['atk',0]]);
 const setTxt=(g.sets||[]).map(s=>`${s}${DM.setNotes[s]?` — ${DM.setNotes[s]}`:''}`).join(' · ');
 $(side+'ItemMeta').innerHTML=`<b>${esc(g.name)}</b> · ${esc(g.type)} · ${esc(g.quality)}${g.level>0?` · Lv ${g.level}`:''}<br>${main?`Base main: ${esc(STAT_LABEL[main[0]]||main[0])} ${fmt(main[1])}. `:'Base main not auto-filled at this level. '}${esc(g.valueNote||'')}${setTxt?`<br><b>Set:</b> ${esc(setTxt)}`:''}`;
 // refresh secondary combo options
 recalc();
}
function gearOptions(){return DM.gear.map(g=>({label:g.name,value:g.name,sub:[g.type,g.quality].filter(Boolean).join(' · ')}))}
function gearSecondaryOptions(side){const g=GEAR_BY_NAME.get($(side+'ItemName').value.trim().toLowerCase());return (g?.secondaries||[]).map(s=>({label:s.label,value:s.label,sub:fmt(s.value)}))}
function applySecondary(side,label){
 const g=GEAR_BY_NAME.get($(side+'ItemName').value.trim().toLowerCase());if(!g)return;const sec=g.secondaries?.find(s=>s.label===label);if(!sec)return;
 const main=gearMain(g);const rows=[];if(main)rows.push(main);rows.push([sec.key,sec.value]);renderItemRows(side,rows);recalc();
}

function skillOptions(kind,scope,index){
 const arr=kind==='Charm'?CHARMS:TECHNIQUES;let cls='';
 if(scope==='mine')cls=$('myClass')?.value||'';else if(scope==='pvpEnemy')cls=$('pvpEnemyClass')?.value||'';
 return arr.map(s=>({label:s.name,value:s.name,sub:`${s.cls}${s.element?` · ${s.element}`:''} · #${s.id}`,score:s.cls===cls?0:1})).sort((a,b)=>a.score-b.score||a.label.localeCompare(b.label));
}
function skillAtRank(sk,rankNum){return sk?.vals?.[String(rankNum)]||{}}
function directCoefs(row){return ['SkillAttack1','SkillAttack2','SkillAttack3','SkillAttack4'].map(k=>row[k]).filter(v=>Number.isFinite(+v)).map(Number)}
function estimateTotalCoef(sk,row){
 const cs=directCoefs(row);if(!cs.length)return {value:null,note:'No direct damage coefficient exposed for this rank.'};
 if(cs.length===1){const v=cs[0]*(sk.hits||1);return {value:v,note:sk.hits>1?`Autofill estimate: ${cs[0]}% × ${sk.hits} description-inferred hits.`:`Source coefficient: ${cs[0]}%.`};}
 return {value:cs.reduce((a,b)=>a+b,0),note:`Autofill estimate: sum of exposed coefficient fields (${cs.join('% + ')}%). Exact EC hit reuse can differ, so this field remains editable.`};
}
function skillCardHTML(i,scope='mine'){
 const p=scope==='mine'?'sk': 'pesk';
 return `<article class="card skill-card" data-i="${i}" data-scope="${scope}">
 <div class="skill-card-head"><div><h3 class="tech-slot-title">Technique ${i+1}</h3><input id="${p}On${i}" type="checkbox" hidden></div><span id="${p}Badge${i}" class="source-badge">Custom</span></div>
 <div class="form-grid three">
  <label>Technique ${i+1}<input id="${p}Name${i}" autocomplete="off" placeholder="Technique ${i+1}"></label>
  <label>Skill rank<input id="${p}Rank${i}" autocomplete="off"></label>
  <label>Slot level<input id="${p}Level${i}" type="number" min="1" max="500"></label>
  <label>Element<input id="${p}Element${i}" autocomplete="off"></label>
  <label>Total coefficient <span>%</span><input id="${p}Coef${i}" type="number" step="0.01"></label>
  <label>Flat damage<input id="${p}Flat${i}" type="number" step="100"></label>
  <label>Hits<input id="${p}Hits${i}" type="number" min="1" max="20"></label>
  <label>Cooldown <span>own turns</span><input id="${p}Cd${i}" type="number" min="0" step="1"></label>
  <label class="check field-check"><input id="${p}Ready${i}" type="checkbox"> Ready at battle start</label>
  ${scope==='mine'?`<label>Usage weight<input id="${p}Weight${i}" type="number" min="0" step="0.1"></label>`:''}
 </div><div id="${p}Meta${i}" class="meta-box small"></div></article>`;
}
