function updatePvpSummary(){if(!$('pvpYouSummary'))return;const b=collectBuild('my'),cc=[0,1,2,3].map(i=>readCharm('mine',i)).filter(x=>x.name).length,f=readFantomon('my');$('pvpYouSummary').innerHTML=`<b>${esc(b.className||'Custom')}</b> · ${esc(b.rank)} · Lv ${fmt(b.level)}<br>HP ${fmt(b.hp)} · ATK ${fmt(b.atk)} · DEF ${fmt(b.def)} · SPD ${fmt(b.spd)}<br>My Build Techniques + <b>${cc}/4 selected Charms</b> are used.<br>Fantomon: <b>${f.enabled&&f.name?esc(f.name):'None'}</b>.`;syncFantomonUI()}

// ---------- PvP Monte Carlo ----------
function pvpInterval(s){const r=rankObj(s.rank);return 100000/Math.sqrt(Math.max(1,s.spd)*(r.speedScale||1))}
function rollPvpHit(att,def,sk,coefPct,flat,opts={}){
 const ar=rankObj(att.rank),dr=rankObj(def.rank),atk=Math.max(1,att.atk),source=Math.max(1,opts.baseStat??atk),defTerm=atk/(atk+Math.max(0,def.def));const psdr=1+(dr.PlayerSkillDmgReduceScale||0)/10000,prosdr=1+(dr.ProSkillDmgReduceScale||0)/10000;let dmg=(source*(coefPct/100)/psdr+(flat||0))*defTerm/prosdr;
 const element=opts.element||sk.element||'Physical';if(element==='Physical'){dmg*=(1+(att.kfm||0)/Math.max(1,dr.BaseKongFuResistance))/(1+(def.pres||0)/Math.max(1,ar.BaseKongFuMaster));}else{const aff=att['aff'+element]||0,aeg=def['aegis'+element]||0;dmg*=(1+aff/Math.max(1,dr.BaseElementReduce)+(att.mast||0)/Math.max(1,dr.BaseElementResistance))/(1+aeg/Math.max(1,ar.BaseElementAdd)+(def.eres||0)/Math.max(1,ar.BaseElementMaster));}
 dmg*=(1+(att.boost||0)/100+(att.pvpadd||0)/100)/Math.max(.1,1+(def.dmgres||0)/100+(def.pvpres||0)/100);dmg*=opts.mult||1;
 const block=clamp((def.blockrate||0)/100-(att.acc||0)/Math.max(1,ar.BaseBlockAvoidPercentValue),0,1);if(!opts.unblockable&&Math.random()<block)return {damage:dmg/Math.max(DM.minBlock,1+(def.blockeff||0)/100),blocked:true,crit:false};
 const crit=clamp(.05+(att.cr||0)/100-(def.critres||0)/100,0,1);if(!opts.noCrit&&Math.random()<crit){dmg*=Math.max(DM.minCrit,1+(att.cd||0)/100-(def.critres||0)/100);return {damage:dmg,blocked:false,crit:true}}return {damage:dmg,blocked:false,crit:false};
}
function chooseSkill(load,turn,readyAt){for(let i=0;i<load.length;i++){const s=load[i];if(s.on&&s.coef>0&&turn>=readyAt[i])return {skill:s,index:i};}return {skill:{on:true,name:'Basic Attack',element:'Physical',coef:100,flat:0,hits:1,cd:0,ready:true},index:-1}}
function charmRow(c){const sk=SKILL_BY_NAME.get((c?.name||'').trim().toLowerCase());if(!sk)return {c,sk:null,row:{}};return {c,sk,row:(sk.vals||{})[String(skillRankNum(c.skillRank))]||{}}}
function charmCoef(cr){return +(cr.row.SkillAttack1||0)}
function compileCharms(list){return (list||[]).filter(c=>c&&c.name).map(charmRow)}
const CHARM_ACTIVE_IDS=new Set([10537,10562,10512,10560,10502,10577,10543,10503,10619,10624,10652,10676,10680,10574,10569,10544,10541,10638,10513,10539,10509]);
function charmCoverage(list){const cs=compileCharms(list),modeled=cs.filter(x=>CHARM_ACTIVE_IDS.has(x.sk?.id)).map(x=>x.sk.name),staticOnly=cs.filter(x=>!CHARM_ACTIVE_IDS.has(x.sk?.id)&&/^Increases the caster|^In battle, increases the caster/i.test(x.sk?.desc||'')).map(x=>x.sk.name),unsupported=cs.filter(x=>!CHARM_ACTIVE_IDS.has(x.sk?.id)&&!staticOnly.includes(x.sk?.name)).map(x=>x.sk.name);return {total:cs.length,modeled,staticOnly,unsupported}}
function oneDuel(A,B,loadA,loadB,charmsA,charmsB,cap){
 let hp=[A.hp,B.hp],shield=[0,0],times=[pvpInterval(A),pvpInterval(B)],turn=[0,0],loads=[loadA,loadB],sides=[A,B],charms=[compileCharms(charmsA),compileCharms(charmsB)],ready=loads.map(L=>L.map(s=>(s.ready||s.cd<=0)?1:(s.cd+1))),actions=0,first=null;
 const rt=[{mark:0,windHits:0,tide:0,nextBoost:0,lifesteal:0,pure:false,gale:false},{mark:0,windHits:0,tide:0,nextBoost:0,lifesteal:0,pure:false,gale:false}];
 // Before-battle shields that can be resolved from the bundled rank values.
 charms.forEach((cs,i)=>cs.forEach(cr=>{if(cr.sk?.id===10513&&cr.row['ST:ShieldByTargetHp'])shield[i]+=sides[i].hp*cr.row['ST:ShieldByTargetHp']/100}));
 function damageTo(target,amount){let broke=false;if(shield[target]>0){const take=Math.min(shield[target],amount);shield[target]-=take;amount-=take;if(shield[target]<=1e-9)broke=true;}if(amount>0)hp[target]-=amount;return broke}
 function charmStrike(who,foe,cr,opts={}){const coef=opts.coef??charmCoef(cr);if(!coef||hp[foe]<=0)return;const baseStat=opts.baseStat==='def'?sides[who].def:sides[who].atk;const r=rollPvpHit(sides[who],sides[foe],{element:opts.element||cr.sk?.element||'Physical'},coef,0,{baseStat,mult:opts.mult||1,element:opts.element||cr.sk?.element||'Physical'});const broke=damageTo(foe,r.damage);if(broke)onShieldBreak(foe,who);}
 function onShieldBreak(owner,enemy){charms[owner].forEach(cr=>{if(cr.sk?.id===10513&&!rt[owner].gale){rt[owner].gale=true;charmStrike(owner,enemy,cr,{element:'Wind'})}})}
 function maybePure(owner){if(hp[owner]>0&&hp[owner]<sides[owner].hp*.5&&!rt[owner].pure){const cr=charms[owner].find(x=>x.sk?.id===10539);if(cr&&cr.row['ST:ShieldByDefence']){rt[owner].pure=true;shield[owner]+=sides[owner].def*cr.row['ST:ShieldByDefence']/100}}}
 function onCast(who,foe,sk){charms[foe].forEach(cr=>{if(cr.sk?.id===10624&&Math.random()<.5)charmStrike(foe,who,cr,{element:'Light'})})}
 function onTechniqueHit(who,foe,sk,roll){
  charms[who].forEach(cr=>{const id=cr.sk?.id;
   if(id===10562&&Math.random()<.40)charmStrike(who,foe,cr,{element:'Wind'});
   else if(id===10512&&Math.random()<.25)charmStrike(who,foe,cr,{element:'Wind'});
   else if(id===10560&&sk.element==='Water'&&Math.random()<.50)charmStrike(who,foe,cr,{element:'Water'});
   else if(id===10502&&Math.random()<.30)charmStrike(who,foe,cr,{element:'Light'});
   else if(id===10577&&Math.random()<.50)charmStrike(who,foe,cr,{element:'Light'});
   else if(id===10543&&roll.crit)charmStrike(who,foe,cr,{element:'Fire'});
   else if(id===10503&&roll.crit&&sk.element==='Fire')charmStrike(who,foe,cr,{element:'Fire'});
   else if(id===10619&&roll.crit)charmStrike(who,foe,cr,{element:'Wind'});
   else if(id===10652&&Math.random()<.40){const lost=clamp(1-hp[foe]/Math.max(1,sides[foe].hp),0,1),mult=1+Math.floor(lost/.05)*.05;charmStrike(who,foe,cr,{element:'Physical',mult});}
   else if(id===10676&&sk.element==='Water'&&Math.random()<.50)charmStrike(who,foe,cr,{element:'Water'});
   else if(id===10680&&Math.random()<.50)charmStrike(who,foe,cr,{element:'Wind'});
   else if(id===10574){rt[who].mark++;if(rt[who].mark>=10){rt[who].mark-=10;charmStrike(who,foe,cr,{element:'Physical'})}}
   else if(id===10569&&sk.element==='Wind'){rt[who].windHits++;if(rt[who].windHits>=3){rt[who].windHits-=3;if(Math.random()<.30)charmStrike(who,foe,cr,{element:'Wind'})}}
   else if(id===10544&&cr.row['ST:SuckHpByDamage']){const cap=sides[who].hp*.5,heal=Math.min(cap-rt[who].lifesteal,roll.damage*cr.row['ST:SuckHpByDamage']/100);if(heal>0){hp[who]=Math.min(sides[who].hp,hp[who]+heal);rt[who].lifesteal+=heal}}
  });
  charms[foe].forEach(cr=>{const id=cr.sk?.id;if(id===10537&&Math.random()<.50)charmStrike(foe,who,cr,{element:'Physical'});else if(id===10541&&roll.blocked)charmStrike(foe,who,cr,{element:'Physical',baseStat:'def'});else if(id===10638){rt[foe].tide++;if(rt[foe].tide>=15){rt[foe].tide-=15;charmStrike(foe,who,cr,{element:'Water',baseStat:'def'})}}else if(id===10509&&cr.row['ST:StatusDmgAddPer'])rt[foe].nextBoost=Math.min(cr.row['ST:StatusDmgAddPer']*10,rt[foe].nextBoost+cr.row['ST:StatusDmgAddPer']);});
  maybePure(foe);
 }
 while(hp[0]>0&&hp[1]>0&&actions<cap){let who;if(Math.abs(times[0]-times[1])<1e-9)who=Math.random()<.5?0:1;else who=times[0]<times[1]?0:1;if(first===null)first=who;const foe=1-who;turn[who]++;const pick=chooseSkill(loads[who],turn[who],ready[who]);const sk=pick.skill,isTech=pick.index>=0;if(isTech)onCast(who,foe,sk);const hits=Math.max(1,sk.hits||1),per=(sk.coef||0)/hits,att=rt[who].nextBoost?{...sides[who],boost:(sides[who].boost||0)+rt[who].nextBoost}:sides[who];if(isTech)rt[who].nextBoost=0;for(let h=0;h<hits&&hp[foe]>0;h++){const roll=rollPvpHit(att,sides[foe],sk,per,h===0?(sk.flat||0):0);const broke=damageTo(foe,roll.damage);if(broke)onShieldBreak(foe,who);if(isTech&&hp[foe]>0)onTechniqueHit(who,foe,sk,roll);}if(pick.index>=0)ready[who][pick.index]=turn[who]+Math.max(1,sk.cd||1);times[who]+=pvpInterval(sides[who]);actions++;}
 let result=hp[0]<=0&&hp[1]<=0?0:hp[1]<=0?1:hp[0]<=0?-1:0;return {result,hp,shield,actions,first};
}
function runPvp(){
 const s=collect(),A=s.build,B=s.pvp.enemy,LA=s.skills.filter(x=>x.on),LB=s.pvp.skills.filter(x=>x.on),CA=s.charms,CB=s.pvp.charms,FA=s.fantomon,FB=s.pvp.enemyFantomon,runs=clamp(s.pvp.runs,1,10000),cap=clamp(s.pvp.actionCap,10,500);let w=0,l=0,d=0,remA=0,remB=0,acts=0,firstA=0;
 const t0=performance.now();for(let i=0;i<runs;i++){const x=oneDuelV1(A,B,LA,LB,CA,CB,FA,FB,cap);if(x.result>0)w++;else if(x.result<0)l++;else d++;remA+=Math.max(0,x.hp[0]);remB+=Math.max(0,x.hp[1]);acts+=x.actions;if(x.first===0)firstA++;}
 const covA=charmCoverage(CA),covB=charmCoverage(CB),covLine=(label,c)=>`<b>${label}:</b> ${c.total?`${c.modeled.length} active modeled, ${c.staticOnly.length} static-in-sheet, ${c.unsupported.length} unsupported active/conditional`:'no Charms selected'}${c.unsupported.length?`<br><small>Not yet modeled: ${esc(c.unsupported.join(', '))}</small>`:''}`;
 $('pvpResults').hidden=false;$('pvpWin').textContent=(w/runs*100).toFixed(1)+'%';$('pvpLoss').textContent=(l/runs*100).toFixed(1)+'%';$('pvpDraw').textContent=(d/runs*100).toFixed(1)+'%';$('pvpFirst').textContent=firstA===runs?'You':firstA===0?'Opponent':(firstA/runs*100).toFixed(1)+'% you';$('pvpDetail').innerHTML=`<h3>Simulation detail</h3><p><b>${fmt(runs)}</b> fights · average ${fmt(acts/runs,1)} actions · action cap ${cap}.</p><p>Average HP remaining: You <b>${fmt(remA/runs)}</b> · Opponent <b>${fmt(remB/runs)}</b>.</p><p>Your action interval: <b>${fmt(pvpInterval(A),1)}</b> · opponent: <b>${fmt(pvpInterval(B),1)}</b>. Smaller acts sooner.</p><p>${covLine('Your Charms',covA)}<br>${covLine('Opponent Charms',covB)}</p><p><b>Your Fantomon:</b> ${FA.enabled&&FA.name?esc(FA.name)+' · Lv '+fmt(FA.level)+' · '+esc(FA.phase):'none'}<br><b>Opponent Fantomon:</b> ${FB.enabled&&FB.name?esc(FB.name)+' · Lv '+fmt(FB.level)+' · '+esc(FB.phase):'none'}</p><p class="hint">Computed in ${fmt(performance.now()-t0,0)} ms. Static Charm bonuses are assumed to already be in the final sheets. Supported active Charm effects are simulated. Supported Fantomon effects are included; unsupported Fantomon coefficients/effects remain explicitly unmodeled.</p>`;state=s;saveOnly();
}

function stateToHash(s){const bytes=new TextEncoder().encode(JSON.stringify(s));let bin='';bytes.forEach(b=>bin+=String.fromCharCode(b));return btoa(bin).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}
function hashToState(h){let x=h.replace(/-/g,'+').replace(/_/g,'/');while(x.length%4)x+='=';const bin=atob(x),bytes=Uint8Array.from(bin,c=>c.charCodeAt(0));return JSON.parse(new TextDecoder().decode(bytes))}
function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function loadInitial(){
 let s=null,source='default',loadedKey=null,m=location.hash.match(/#s=([^&]+)/);
 if(m){try{s=hashToState(m[1]);source='share';toast('Loaded shared build')}catch(e){}}
 if(!s){
   try{
     const keys=[STORAGE_KEY,...LEGACY_STORAGE_KEYS];
     for(const k of keys){const raw=localStorage.getItem(k);if(raw){s=JSON.parse(raw);source='local';loadedKey=k;break;}}
   }catch(e){}
 }
 suppressAutoSave=true;fill(s||DEFAULT);suppressAutoSave=false;
 if(source==='local'){
   let ts=0;try{ts=Number(localStorage.getItem(STORAGE_META_KEY)||0)}catch(e){}
   setSaveStatus(ts?`Restored · saved ${savedClock(ts)}`:'Restored local inputs');
   if(loadedKey&&loadedKey!==STORAGE_KEY)writeLocalState(state,false);
 }else if(source==='share')setSaveStatus('Shared build · edit to autosave','pending');
 else setSaveStatus('Local autosave on · no saved inputs yet','pending');
}
function wire(){
 document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.tab-panel').forEach(p=>p.classList.toggle('active',p.id==='tab-'+b.dataset.tab))});
 document.body.addEventListener('input',e=>{if(e.target.matches('input')&&!e.target.closest('.combo-menu')&&e.target.id!=='importInput')recalc()});document.body.addEventListener('change',e=>{if(e.target.matches('input')&&!e.target.closest('.combo-menu')&&e.target.id!=='importInput')recalc()});
 document.querySelectorAll('.add-stat').forEach(b=>b.onclick=()=>{addItemRow(b.dataset.side,'atk',0);recalc()});
 $('runPvpBtn').onclick=runPvp;$('pveUseMyFantomon').onchange=()=>{syncFantomonUI();recalc()};if($('shareBtn'))$('shareBtn').onclick=async()=>{const url=location.href.split('#')[0]+'#s='+stateToHash(collect());try{await navigator.clipboard.writeText(url);toast('Share link copied')}catch(e){prompt('Copy this link:',url)}};if($('exportBtn'))$('exportBtn').onclick=()=>download('sxs-build-v10.json',JSON.stringify(collect(),null,2));if($('importInput'))$('importInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{fill(JSON.parse(await f.text()));toast('Build imported')}catch(err){toast('Could not import JSON')}e.target.value=''};$('copyResultBtn').onclick=async()=>{const t=$('copyResultBtn').dataset.text||'';try{await navigator.clipboard.writeText(t);toast('Recommendation copied')}catch(e){prompt('Copy recommendation:',t)}};$('resetBtn').onclick=()=>{if(!confirm('Clear all locally saved inputs for this app and reset to the example values?'))return;suppressAutoSave=true;clearLocalState();history.replaceState(null,'',location.pathname+location.search);fill(DEFAULT);suppressAutoSave=false;setSaveStatus('Saved inputs cleared · edit to autosave','pending');toast('Local saved data cleared')};
}


