function loadExtras(){try{const raw=localStorage.getItem(EXTRA_KEY)||localStorage.getItem(EXTRA_LEGACY_KEY);const x=JSON.parse(raw||'null');if(x&&typeof x==='object')extras={...extras,...x,setRules:Array.isArray(x.setRules)&&x.setRules.length?x.setRules:deep(DEFAULT_SET_RULES),inventory:Array.isArray(x.inventory)?x.inventory:[],profiles:Array.isArray(x.profiles)?x.profiles:[],friendProfiles:Array.isArray(x.friendProfiles)?x.friendProfiles:[],snapshots:Array.isArray(x.snapshots)?x.snapshots:[],npcPresets:Array.isArray(x.npcPresets)&&x.npcPresets.length?x.npcPresets:deep(BUILTIN_PRESETS)};}catch(e){} try{const c=JSON.parse(localStorage.getItem(CATALOG_KEY)||localStorage.getItem(CATALOG_LEGACY_KEY)||'null');if(c?.gear?.length)installCatalog(c.gear,c.npcs||[],false);}catch(e){}}
