function renderSupport(){if(!$('supportDashboard'))return;const s=collect();let heal=0,control=0,buff=0,known=0;s.skills.filter(x=>x.on).forEach(x=>{const sk=SKILL_BY_NAME.get(x.name.toLowerCase()),d=(sk?.desc||'').toLowerCase(),row=sk?skillAtRank(sk,skillRankNum(x.skillRank)):{};if(/heal|restore/.test(d)){known++;heal+=1;}if(/chance|taunt|stun|airborne|reduce|debuff|dispel/.test(d)){known++;control+=1;}if(/increase|grant|buff|shield/.test(d)){known++;buff+=1;}if(row.SkillCureByHp||row.SkillFixedCure)heal+=1;});const actions=actionInfo(s.build,s).actions;$('supportDashboard').innerHTML=`<div class="mini-grid"><div><span class="muted">Healing signals</span><div class="big-stat">${heal}</div></div><div><span class="muted">Control/debuff</span><div class="big-stat">${control}</div></div><div><span class="muted">Buff/shield</span><div class="big-stat">${buff}</div></div><div><span class="muted">Actions</span><div class="big-stat">${actions}</div></div></div><p class="hint">Support classification uses source text/rank properties. Exact healing throughput is shown only when its coefficient is exposed; otherwise the calculator reports support opportunity rather than inventing a heal number.</p>`;}
