function analyticalPvpScore(A,B,skills){const fake={enemy:{...B,pveres:B.pvpres||0,skillred:0},turns:15,skills};const d=damagePerAction(A,fake),r=Math.sqrt(A.spd*rankObj(A.rank).speedScale/(Math.max(1,B.spd)*rankObj(B.rank).speedScale));const tKill=B.hp/Math.max(1,d*r),enemyFake={enemy:{...A,pveres:A.pvpres||0,skillred:0},turns:15,skills:[]};return 1/Math.max(.01,tKill);}
