function renderProfiles(){if(!$('profilesList'))return;$('profilesList').innerHTML=extras.profiles.map((p,i)=>`<div class="saved-row"><div><strong>${esc(p.name)}</strong><small>${new Date(p.at).toLocaleString()}</small></div><div class="inline-actions"><button class="btn small prof-load" data-i="${i}">Load</button><button class="btn small danger prof-del" data-i="${i}">Delete</button></div></div>`).join('')||'<p class="hint">No saved profiles yet.</p>';$('snapshotsList').innerHTML=extras.snapshots.map((p,i)=>`<div class="saved-row"><div><strong>${esc(p.name)}</strong><small>ATK ${fmt(p.summary?.atk)} · SPD ${fmt(p.summary?.spd)} · PvE ${fmt(p.summary?.pveTotal)}</small></div><div class="inline-actions"><button class="btn small snap-load" data-i="${i}">Load</button><button class="btn small danger snap-del" data-i="${i}">Delete</button></div></div>`).join('')||'<p class="hint">No snapshots yet.</p>';document.querySelectorAll('.prof-load').forEach(b=>b.onclick=()=>fill(extras.profiles[+b.dataset.i].state));document.querySelectorAll('.prof-del').forEach(b=>b.onclick=()=>{extras.profiles.splice(+b.dataset.i,1);saveExtras();renderProfiles()});document.querySelectorAll('.snap-load').forEach(b=>b.onclick=()=>fill(extras.snapshots[+b.dataset.i].state));document.querySelectorAll('.snap-del').forEach(b=>b.onclick=()=>{extras.snapshots.splice(+b.dataset.i,1);saveExtras();renderProfiles()});const opts=extras.snapshots.map(x=>x.name);['snapshotA','snapshotB'].forEach(id=>{if($(id)&&!$(id).dataset.comboAttached)attachCombo($(id),opts)});}
