function skillMetaV11(s){const sk=SKILL_BY_NAME.get(String(s?.name||'').toLowerCase());if(!sk)return {sk:null,row:{},desc:'',duration:2};const rank=skillRankNum(s.skillRank||22),row=(sk.vals||{})[String(rank)]||{};return {sk,row,desc:sk.desc||'',duration:durationV11(sk.desc,2),rank};}
function compileTechniqueV11(s){const key=[s?.name,s?.skillRank,s?.coef,s?.hits,s?.cd].join('|');if(V11_TECH_CACHE.has(key))return V11_TECH_CACHE.get(key);const m=skillMetaV11(s),d=m.desc,row=m.row,e={...m,buffs:[],debuffs:[],shieldDef:0,shieldHp:0,healHp:0,nextBoost:0,prebattle:/before battle starts/i.test(d)};if(row['ST:ShieldByDefence'])e.shieldDef=+row['ST:ShieldByDefence'];if(row['ST:ShieldByTargetHp'])e.shieldHp=+row['ST:ShieldByTargetHp'];if(row['ST:StatusDmgAddPer']){/next damaging Technique/i.test(d)?e.nextBoost=+row['ST:StatusDmgAddPer']:/target|Hex Mark|enemy/i.test(d)&&/increased DMG|DMG boost/i.test(d)?e.debuffs.push({key:'vuln',value:+row['ST:StatusDmgAddPer'],duration:e.duration,polarity:'debuff'}):e.buffs.push({key:'boost',value:+row['ST:StatusDmgAddPer'],duration:e.duration,polarity:'buff'})}if(row['ST:StatusDmgReducePer'])e.buffs.push({key:'dmgres',value:+row['ST:StatusDmgReducePer'],duration:e.duration,polarity:'buff'});if(row['ST:CritRatePercent'])e.buffs.push({key:'cr',value:+row['ST:CritRatePercent'],duration:e.duration,polarity:'buff'});if(row['ST:BlockPercent'])e.buffs.push({key:'blockrate',value:+row['ST:BlockPercent'],duration:e.duration,polarity:'buff'});if(row['ST:BlockAvoidPercent'])e.buffs.push({key:'accuracyPct',value:+row['ST:BlockAvoidPercent'],duration:e.duration,polarity:'buff'});if(row['ST:StatusAdd1']){if(m.sk?.id===10060)e.buffs.push({key:'hpScale',value:+row['ST:StatusAdd1'],duration:e.duration,polarity:'buff'});if(m.sk?.id===10086)e.buffs.push({key:'spdScale',value:+row['ST:StatusAdd1'],duration:e.duration,polarity:'buff'});if(m.sk?.id===10092)e.buffs.push({key:'atkScale',value:+row['ST:StatusAdd1'],duration:e.duration,polarity:'buff'});}const heal=d.match(/(?:performs?\s+a\s+|heals?[^.]*?)(\d+(?:\.\d+)?)%\s+(?:healing|of[^.]*?HP)/i);if(heal)e.healHp=+heal[1];const deb=d.match(/(\d+(?:\.\d+)?)%\s+base chance[^.]*?reduce(?:s| their| the target's)?\s*(ATK|DEF|DMG|SPD)[^\d]*(\d+(?:\.\d+)?)%[^.]*?for\s+(\d+)\s+turn/i);if(deb){const map={ATK:'atkScale',DEF:'defScale',DMG:'dmgres',SPD:'spdScale'};e.debuffs.push({key:map[deb[2].toUpperCase()],value:-Math.abs(+deb[3]),duration:+deb[4],chance:+deb[1],polarity:'debuff'});}V11_TECH_CACHE.set(key,e);return e;}
function mkRtV11(base,load,charms,fant,items=[]){return {base:deep(base),hp:+base.hp,maxHp:+base.hp,turn:0,time:0,statuses:[],shields:[],load:(load||[]).filter(x=>x&&x.on).map(deep),ready:[],charms:compileCharms(charms),fant:fant||baseFantomon(),items:items||[],c:{tech:0,blazing:0,fireCrit:0,sacred:0,mark:0,windHits:0,tide:0,lifesteal:0,pure:false,voidBubble:false,shadow:false,shadowUntil:0,boaroLoss:0,boaroTriggers:0,armopi:0,cabbage:0,prism:0,nyxWindow:[],zeiWindow:[],lastTurnLoss:0,nextBoost:0},totals:{damage:0,healing:0,shield:0,proc:0,dot:0},events:[]};}
function addStatusV11(rt,key,value,duration=1,source='',polarity='buff',stacks=1,maxStacks=99){if(!value)return;let x=rt.statuses.find(z=>z.key===key&&z.source===source&&z.expires>=rt.turn);if(x){x.stacks=Math.min(maxStacks,(x.stacks||1)+stacks);x.expires=Math.max(x.expires,rt.turn+duration);x.value=value;}else rt.statuses.push({key,value,source,polarity,stacks:Math.min(maxStacks,stacks),expires:duration>=9000?999999:rt.turn+duration});}
function expireV11(rt){rt.statuses=rt.statuses.filter(x=>x.expires>=rt.turn);const keep=[];for(const s of rt.shields){if(s.expires>=rt.turn)keep.push(s);else if(s.returnHp&&s.amount>0)healV11(rt,s.amount,false);}rt.shields=keep;}
