function effV11(rt,foe){const e={...rt.base};e._accuracyPct=0;e._ignoreDef=0;e._vuln=0;e._healRecv=0;e._shieldBoost=0;for(const s of rt.statuses){if(s.expires<rt.turn)continue;const v=s.value*(s.stacks||1);if(s.key==='atkScale')e.atk*=1+v/100;else if(s.key==='defScale')e.def*=1+v/100;else if(s.key==='spdScale')e.spd*=1+v/100;else if(s.key==='hpScale'){e.hp*=1+v/100;}else if(s.key==='boost')e.boost=(e.boost||0)+v;else if(s.key==='dmgres')e.dmgres=(e.dmgres||0)+v;else if(s.key==='cr')e.cr=(e.cr||0)+v;else if(s.key==='cd')e.cd=(e.cd||0)+v;else if(s.key==='blockrate')e.blockrate=(e.blockrate||0)+v;else if(s.key==='accuracyPct')e._accuracyPct+=v;else if(s.key==='ignoreDef')e._ignoreDef+=v;else if(s.key==='vuln')e._vuln+=v;else if(s.key==='healRecv')e._healRecv+=v;else if(s.key==='shieldBoost')e._shieldBoost+=v;}
 const lost=clamp(1-rt.hp/Math.max(1,rt.maxHp),0,1),foeLost=foe?clamp(1-foe.hp/Math.max(1,foe.maxHp),0,1):0;let cr=charmRecV11(rt,10547);if(cr)e.boost=(e.boost||0)+(+cr.row['ST:StatusDmgAddPer']||0)*Math.min(5,Math.floor(lost/.15));cr=charmRecV11(rt,10582);if(cr)e.dmgres=(e.dmgres||0)+(+cr.row['ST:StatusDmgReducePer']||0)*Math.min(5,Math.floor(lost/.15));cr=charmRecV11(rt,10594);if(cr)e.boost=(e.boost||0)+(+cr.row['ST:StatusDmgAddPer']||0)*Math.min(5,Math.floor(foeLost/.15));cr=charmRecV11(rt,10589);if(cr)e._healRecv+=(+cr.row['ST:BeCureAddPercent']||0)*Math.min(5,Math.floor(lost/.15));cr=charmRecV11(rt,10540);if(cr&&totalShieldV11(rt)>0)e.atk*=1+(+cr.row['ST:AttackScale']||0)/100;cr=charmRecV11(rt,10609);if(cr)e.boost=(e.boost||0)+(+cr.row['ST:StatusDmgAddPer']||0);cr=charmRecV11(rt,10579);if(cr&&foe&&negativeCountV11(foe)>0)e.dmgres=(e.dmgres||0)+(+cr.row['ST:StatusDmgReducePer']||0);cr=charmRecV11(rt,10568);if(cr)e._ignoreDef+=(+cr.row['ST:StatusIgnoreDefence']||0)+10*Math.min(3,positiveCountV11(rt));cr=charmRecV11(rt,10593);if(cr)e._shieldBoost+=(+cr.row['ST:StatusShieldAddPercent']||0);if(rt.fant?.enabled){if(rt.fant.name==='Pandarial'&&rt.fant.dmgBoostPct)e.boost=(e.boost||0)+rt.fant.dmgBoostPct;if(rt.fant.name==='Luminarch Steed'&&rt.fant.blockPct)e.blockrate=(e.blockrate||0)+rt.fant.blockPct;}return e;}
function addShieldV11(rt,amount,duration=9999,source='',returnHp=false){const e=effV11(rt,null);amount=Math.max(0,amount)*(1+(e._shieldBoost||0)/100);if(!amount)return 0;rt.shields.push({amount,expires:duration>=9000?999999:rt.turn+duration,source,returnHp});rt.totals.shield+=amount;return amount;}
function healV11(rt,amount,count=true){const e=effV11(rt,null),rec=charmRecV11(rt,10613);amount=Math.max(0,amount)*(1+(e._healRecv||0)/100)*(1+(e._healingBoostV4||0)/100);if(rec){amount*=1+(+rec.row['ST:BeCureAddPercent']||0)/100;addShieldV11(rt,amount,2,'Healing Shift',true);return amount;}const old=rt.hp;rt.hp=Math.min(rt.maxHp,rt.hp+amount);if(count)rt.totals.healing+=rt.hp-old;return rt.hp-old;}
function consumeShieldV11(rt,amount){let left=amount,had=totalShieldV11(rt)>0;rt.shields.sort((a,b)=>a.expires-b.expires);for(const s of rt.shields){if(left<=0)break;const q=Math.min(s.amount,left);s.amount-=q;left-=q;}rt.shields=rt.shields.filter(s=>s.amount>1e-9);return {left,had,broke:had&&totalShieldV11(rt)<=1e-9};}
function rollHitV11(attRt,defRt,sk,coefPct,flat,mode='pvp',random=true,opts={}){const att=effV11(attRt,defRt),def=effV11(defRt,attRt),ar=rankObj(att.rank),dr=rankObj(def.rank),atk=Math.max(1,att.atk),defUsed=Math.max(0,def.def*(1-clamp((att._ignoreDef||0)/100,0,.9))),defTerm=atk/(atk+defUsed);let dmg=(Math.max(1,opts.baseStat??atk)*(coefPct/100)+(flat||0))*defTerm;const element=opts.element||sk.element||'Physical';if(mode==='pvp')dmg/=(1+(dr.PlayerSkillDmgReduceScale||0)/10000)*(1+(dr.ProSkillDmgReduceScale||0)/10000);if(element==='Physical')dmg*=(1+(att.kfm||0)/Math.max(1,dr.BaseKongFuResistance))/(1+(def.pres||0)/Math.max(1,ar.BaseKongFuMaster));else{const aff=att['aff'+element]||0,aeg=def['aegis'+element]||0;dmg*=(1+aff/Math.max(1,dr.BaseElementReduce)+(att.mast||0)/Math.max(1,dr.BaseElementResistance))/(1+aeg/Math.max(1,ar.BaseElementAdd)+(def.eres||0)/Math.max(1,ar.BaseElementMaster));}const add=mode==='pve'?(att.pve||0):(att.pvpadd||0),res=mode==='pve'?(def.pveres||0):(def.pvpres||0);dmg*=(1+(att.boost||0)/100+add/100+(def._vuln||0)/100)/Math.max(.1,1+(def.dmgres||0)/100+res/100);if(mode==='pve')dmg/=1+(def.skillred||0)/100;dmg*=opts.mult||1;if(mode==='pve')dmg*=levelMult((att.level||0)-(def.level||0));const block=clamp((def.blockrate||0)/100-(att.acc||0)/Math.max(1,ar.BaseBlockAvoidPercentValue)-(att._accuracyPct||0)/100,0,1),crit=clamp(.05+(att.cr||0)/100-(def.critres||0)/100,0,1),cm=Math.max(DM.minCrit,1+(att.cd||0)/100-(def.critres||0)/100),bd=Math.max(DM.minBlock,1+(def.blockeff||0)/100);if(!random)return {damage:dmg*((1-block)*((1-crit)+crit*cm)+block/bd),crit:false,blocked:false};if(Math.random()<block)return {damage:dmg/bd,blocked:true,crit:false};if(Math.random()<crit)return {damage:dmg*cm,blocked:false,crit:true};return {damage:dmg,blocked:false,crit:false};}
function statusApplyV11(rt,spec,att,def){let ok=true;if(spec.chance!=null)ok=Math.random()<effectChance(spec.chance,effV11(att,def),effV11(def,att),'AbnormalDebuff');if(ok)addStatusV11(rt,spec.key,spec.value,spec.duration||1,spec.source||'Technique',spec.polarity||'debuff',1,spec.maxStacks||99);return ok;}
function customSetRulesV11(rt,trigger){const counts=setCounts(rt.items||[]);return extras.setRules.filter(r=>(counts[r.set]||0)>=(+r.pieces||1)&&r.trigger===trigger&&!['flat','percent','special'].includes(r.mode));}
function procSetV11(rt,other,trigger,mode='pvp',random=true){for(const r of customSetRulesV11(rt,trigger)){if((+r.chance||0)<100&&random&&Math.random()>(+r.chance||0)/100)continue;const v=+r.value||0;if(!v)continue;if(r.mode==='proc-damage'){const roll=rollHitV11(rt,other,{element:r.stat||'Physical'},v,0,mode,random,{element:r.stat||'Physical'});dealV11(other,roll.damage,rt,{technique:false,proc:true,mode});rt.totals.proc+=roll.damage;}else if(r.mode==='heal-hp')healV11(rt,rt.maxHp*v/100);else if(r.mode==='shield-hp')addShieldV11(rt,rt.maxHp*v/100,2,r.set);else if(r.mode==='shield-def')addShieldV11(rt,effV11(rt,other).def*v/100,2,r.set);else if(r.mode==='dmg-boost')addStatusV11(rt,'boost',v,2,r.set);else if(r.mode==='dmg-reduce')addStatusV11(rt,'dmgres',v,2,r.set);}}
function dealV11(defRt,amount,attRt,meta={}){if(amount<=0)return 0;const before=defRt.hp,sh=consumeShieldV11(defRt,amount);if(sh.left>0){let lethal=sh.left>=defRt.hp;if(lethal&&hasCharmV11(defRt,10586)&&!defRt.c.shadow){defRt.c.shadow=true;defRt.c.shadowUntil=defRt.turn+1;defRt.hp=1;addStatusV11(defRt,'boost',+charmRecV11(defRt,10586).row['ST:StatusDmgAddPer']||0,1,'Shadow Vengeance');}else defRt.hp-=sh.left;}const lost=Math.max(0,before-defRt.hp);defRt.c.lastTurnLoss+=lost;defRt.c.boaroLoss+=lost;const vb=charmRecV11(defRt,10556);if(vb&&!defRt.c.voidBubble&&defRt.hp>0&&defRt.hp<defRt.maxHp*.5){defRt.c.voidBubble=true;addShieldV11(defRt,defRt.maxHp*(+vb.row['ST:ShieldByTargetHp']||0)/100,2,'Void Bubble');}const pp=charmRecV11(defRt,10539);if(pp&&!defRt.c.pure&&defRt.hp>0&&defRt.hp<defRt.maxHp*.5){defRt.c.pure=true;addShieldV11(defRt,effV11(defRt,attRt).def*(+pp.row['ST:ShieldByDefence']||0)/100,2,'Pure Protection');}const op=charmRecV11(defRt,10573);if(op&&lost>=defRt.maxHp*.15)addShieldV11(defRt,defRt.maxHp*(+op.row['ST:ShieldByTargetHp']||0)/100,2,'Overload Protection');if(defRt.fant?.enabled&&defRt.fant.name==='Boaro'&&defRt.fant.shieldDefPct>0){while(defRt.c.boaroTriggers<5&&defRt.c.boaroLoss>=defRt.maxHp*.15){defRt.c.boaroLoss-=defRt.maxHp*.15;defRt.c.boaroTriggers++;addShieldV11(defRt,effV11(defRt,attRt).def*defRt.fant.shieldDefPct/100,2,'Boaro');}}if(meta.technique){const ss=charmRecV11(defRt,10542);if(ss)addStatusV11(defRt,'dmgres',+ss.row['ST:StatusDmgReducePer']||0,1,'Stone Skin','buff',1,9);const ref=charmRecV11(defRt,10567);if(ref&&sh.had&&attRt&&attRt.hp>0){const refl=lost*(+ref.row['ST:DamageByDamage']||0)/100;const rr=rollHitV11(defRt,attRt,{element:'Light'},100,0,meta.mode||'pvp',meta.mode!=='pve',{baseStat:refl,element:'Light'});const ss2=consumeShieldV11(attRt,rr.damage);attRt.hp-=ss2.left;}}return lost;}
