function fantTechV11(att,def,sk,mode,random){if(!att.fant?.enabled)return;const f=att.fant,n=f.name,hit=(coef,el)=>{if(coef>0){const r=rollHitV11(att,def,{element:el},coef,0,mode,random,{element:el});dealV11(def,r.damage,att,{proc:true,mode});att.totals.proc+=r.damage;}};if(n==='Falko')hit(f.attackCoef,'Physical');else if(n==='Zeioletus'){const window=att.c.zeiWindow.filter(t=>att.turn-t<2);att.c.zeiWindow=window;if(window.length<2){hit(f.attackCoef,'Light');att.c.zeiWindow.push(att.turn)}}else if(n==='Terragon'){hit(f.attackCoef,'Physical');if(!random||Math.random()<.5)addStatusV11(def,'atkScale',-(f.phase==='Adult'?18:25),1,'Terragon','debuff');}else if(n==='Kels'){hit(f.attackCoef,'Water');const buffs=def.statuses.filter(x=>x.polarity==='buff');if(buffs.length)def.statuses.splice(def.statuses.indexOf(buffs[0]),1);}else if(n==='Nyxarchon'){const window=att.c.nyxWindow.filter(t=>att.turn-t<2);att.c.nyxWindow=window;if(window.length<2){hit(f.attackCoef,'Dark');addStatusV11(def,'defScale',-10,2,'Nyxarchon','debuff',1,3);att.c.nyxWindow.push(att.turn)}}else if(n==='Chomusuke'){hit(f.attackCoef,'Physical');if(!random||Math.random()<.5)addStatusV11(def,'defScale',-15,1,'Chomusuke','debuff');}}
function prebattleV11(rt,foe,mode,random){const sf=charmRecV11(rt,10590);if(sf){rt.hp*=.5;addStatusV11(rt,'dmgres',+sf.row['ST:StatusDmgReducePer']||0,9999,'Soulfire Protection');}const gs=charmRecV11(rt,10513);if(gs)addShieldV11(rt,rt.maxHp*(+gs.row['ST:ShieldByTargetHp']||0)/100,9999,'Gale Shield');if(rt.fant?.enabled&&rt.fant.name==='Luminarch Steed'){if(rt.fant.dmgReducePct)addStatusV11(rt,'dmgres',rt.fant.dmgReducePct,3,'Yearward Cloud');if(rt.fant.blockPct)addStatusV11(rt,'blockrate',rt.fant.blockPct,9999,'Yearward Cloud');}procSetV11(rt,foe,'beforeBattle',mode,random);rt.ready=rt.load.map(s=>(s.ready||s.cd<=0)?1:(s.cd+1));rt.load.forEach((s,i)=>{const e=compileTechniqueV11(s);if(e.prebattle){applyTechEffectsV11(rt,foe,s,e,mode,random);rt.ready[i]=Math.max(rt.ready[i],1+Math.max(1,s.cd||1));}})}
function startTurnV11(rt,foe,mode,random){rt.turn++;expireV11(rt);rt.c.lastTurnLoss=0;if(rt.c.shadow&&rt.turn>rt.c.shadowUntil){rt.hp=0;return;}let cr=charmRecV11(rt,10617);if(cr&&rt.turn>=3)addStatusV11(rt,'boost',+cr.row['ST:StatusDmgAddPer']||0,9999,'Sacred Rhythm','buff',1,3);cr=charmRecV11(rt,10610);if(cr)addStatusV11(rt,'boost',+cr.row['ST:StatusDmgAddPer']||0,1,'Mantra of Blessings');cr=charmRecV11(rt,10611);if(cr){const opts=[['atkScale',+cr.row['ST:AttackScale']||0],['spdScale',+cr.row['ST:SpeedScale']||0],['hpScale',+cr.row['ST:MaxHpScale']||0]].filter(x=>x[1]);const pick=random?opts[Math.floor(Math.random()*opts.length)]:opts[0];if(pick)addStatusV11(rt,pick[0],pick[1],1,'Falling Dark Star');}if(rt.fant?.enabled&&rt.fant.name==='Herbote'&&rt.hp<rt.maxHp*.8){if(rt.fant.healPct)healV11(rt,rt.maxHp*rt.fant.healPct/100);if((!random||Math.random()<.5)){const neg=rt.statuses.find(x=>x.polarity==='debuff');if(neg)rt.statuses.splice(rt.statuses.indexOf(neg),1);}}if(rt.fant?.enabled&&rt.fant.name==='Aegiswing'&&rt.turn===4){healV11(rt,(rt.maxHp-rt.hp)*.5);if(rt.fant.dmgBoostPct)addStatusV11(rt,'boost',rt.fant.dmgBoostPct,9999,'Power Unsealed');}procSetV11(rt,foe,'turnStart',mode,random);}
function endTurnV11(rt,foe,mode,random){if(rt.fant?.enabled&&rt.fant.name==='Sylvaerie'){if(rt.fant.atkBuffPct)addStatusV11(rt,'atkScale',rt.fant.atkBuffPct,1,'Wind Embrace');if(rt.fant.spdBuffPct)addStatusV11(rt,'spdScale',rt.fant.spdBuffPct,1,'Wind Embrace');}if(rt.fant?.enabled&&rt.fant.name==='Armopi'){rt.c.armopi++;if(rt.c.armopi>=3){rt.c.armopi=0;if(rt.fant.shieldDefPct)addShieldV11(rt,effV11(rt,foe).def*rt.fant.shieldDefPct/100,2,'Armor Protection');}}if(rt.fant?.enabled&&rt.fant.name==='Cabbage Dog'){rt.c.cabbage++;if(rt.c.cabbage>=7){rt.c.cabbage=0;if(rt.fant.dmgReducePct)addStatusV11(rt,'dmgres',rt.fant.dmgReducePct,9999,'Pava');if(rt.fant.blockPct)addStatusV11(rt,'blockrate',rt.fant.blockPct,9999,'Pava');}}procSetV11(rt,foe,'turnEnd',mode,random);}
function applyTechEffectsV11(att,def,sk,e,mode,random){if(e.shieldDef)addShieldV11(att,effV11(att,def).def*e.shieldDef/100,e.duration,sk.name);if(e.shieldHp)addShieldV11(att,att.maxHp*e.shieldHp/100,e.duration,sk.name);if(e.healHp)healV11(att,att.maxHp*e.healHp/100);for(const b of e.buffs)addStatusV11(att,b.key,b.value,b.duration,sk.name,b.polarity);for(const d of e.debuffs){d.source=sk.name;if(d.chance==null||!random||Math.random()<effectChance(d.chance,effV11(att,def),effV11(def,att),'AbnormalDebuff'))addStatusV11(def,d.key,d.value,d.duration,sk.name,d.polarity||'debuff',1,d.maxStacks||99);}if(e.nextBoost)att.c.nextBoost=Math.max(att.c.nextBoost,e.nextBoost);}
function performActionV11(att,def,sk,mode='pvp',random=true){const e=compileTechniqueV11(sk),isTech=sk.name!=='Basic Attack';if(isTech){att.c.tech++;if(hasCharmV11(att,10564)&&att.c.tech%4===0)addStatusV11(att,'boost',+charmRecV11(att,10564).row['ST:StatusDmgAddPer']||0,9999,'Blazing Clash','buff',1,3);if(sk.element==='Fire'&&hasCharmV11(att,10599))addStatusV11(att,'cr',+charmRecV11(att,10599).row['ST:CritRatePercent']||0,2,'Explosive Spirit','buff',1,8);applyTechEffectsV11(att,def,sk,e,mode,random);}let total=0;if((sk.coef||0)>0){const hits=Math.max(1,sk.hits||1),per=(sk.coef||0)/hits;let next=att.c.nextBoost;for(let h=0;h<hits&&def.hp>0;h++){if(next){addStatusV11(att,'boost',next,0,'Next technique');att.c.nextBoost=0;}const roll=rollHitV11(att,def,sk,per,h===0?(sk.flat||0):0,mode,random);const lost=dealV11(def,roll.damage,att,{technique:isTech,mode});total+=roll.damage;att.totals.damage+=roll.damage;if(isTech)charmHitV11(att,def,sk,roll,mode,random);att.statuses=att.statuses.filter(x=>x.source!=='Next technique');}if(isTech&&def.hp>0){fantTechV11(att,def,sk,mode,random);procSetV11(att,def,'onTechniqueHit',mode,random);procSetV11(def,att,'whenHitByTechnique',mode,random);}}else if(isTech&&/heal|buff|shield|increase|grant/i.test(e.desc)&&att.fant?.enabled&&att.fant.name==='Mandragora'&&att.fant.healPct)healV11(att,att.maxHp*att.fant.healPct/100);if(isTech&&att.fant?.enabled&&att.fant.name==='Prismora'&&/heal|buff|shield|increase|grant/i.test(e.desc)){att.c.prism++;if(att.c.prism>=4){att.c.prism=0;if(att.fant.dmgBoostPct)addStatusV11(att,'boost',att.fant.dmgBoostPct,9999,'Clear Heart');}}return total;}
function chooseSkillV11(rt){for(let i=0;i<rt.load.length;i++)if(rt.turn>=rt.ready[i])return {skill:rt.load[i],index:i};return {skill:{on:true,name:'Basic Attack',element:'Physical',coef:100,flat:0,hits:1,cd:0,ready:true},index:-1};}
function cooldownV11(rt,sk){let red=rt.fant?.enabled&&rt.fant.name==='Pandarial'?1:0;if(rt.c.shadow)red+=2;return Math.max(1,(sk.cd||1)-red);}
function oneDuelV1(A,B,loadA,loadB,charmsA,charmsB,fantA,fantB,cap){const itemsA=equippedGearV59(),a=mkRtV11(A,loadA,charmsA,fantA,itemsA),b=mkRtV11(B,loadB,charmsB,fantB,[]),r=[a,b];prebattleV11(a,b,'pvp',true);prebattleV11(b,a,'pvp',true);let times=[pvpInterval(effV11(a,b)),pvpInterval(effV11(b,a))],actions=0,first=null;while(a.hp>0&&b.hp>0&&actions<cap){let w=Math.abs(times[0]-times[1])<1e-9?(Math.random()<.5?0:1):(times[0]<times[1]?0:1),f=1-w;if(first===null)first=w;const rt=r[w],foe=r[f];startTurnV11(rt,foe,'pvp',true);if(rt.hp<=0)break;const pick=chooseSkillV11(rt),sk=pick.skill;performActionV11(rt,foe,sk,'pvp',true);if(pick.index>=0)rt.ready[pick.index]=rt.turn+cooldownV11(rt,sk);endTurnV11(rt,foe,'pvp',true);times[w]+=100000/Math.sqrt(Math.max(1,effV11(rt,foe).spd)*Math.max(1,rankObj(rt.base.rank).speedScale));actions++;}return {result:a.hp<=0&&b.hp<=0?0:b.hp<=0?1:a.hp<=0?-1:0,hp:[a.hp,b.hp],shield:[totalShieldV11(a),totalShieldV11(b)],actions,first,detail:{a:a.totals,b:b.totals}};}
function pveRotation(sheet,s,skills=s.skills,fantomon=effectivePveFantomon(),items=[]){const ai=actionInfo(sheet,s),enemyBase={...s.enemy,atk:s.enemy.atk||0,rank:s.enemy.rank||sheet.rank,level:s.enemy.level||sheet.level,boost:0,pvpadd:0,pvpres:0,acc:0,cr:0,cd:50,mast:0,kfm:0,affFire:0,affWater:0,affWind:0,affLight:0,affDark:0},a=mkRtV11(sheet,skills,s.charms||[],fantomon,items),b=mkRtV11(enemyBase,[],[],baseFantomon(),[]);prebattleV11(a,b,'pve',false);const seq=[];for(let k=0;k<ai.actions&&a.hp>0&&b.hp>0;k++){startTurnV11(a,b,'pve',false);const pick=chooseSkillV11(a),sk=pick.skill,before=b.hp,sh0=totalShieldV11(a),h0=a.hp,dmg=performActionV11(a,b,sk,'pve',false);if(pick.index>=0)a.ready[pick.index]=a.turn+cooldownV11(a,sk);endTurnV11(a,b,'pve',false);seq.push({turn:a.turn,name:sk.name,damage:dmg,enemyDef:effV11(b,a).def,healing:Math.max(0,a.hp-h0),shield:Math.max(0,totalShieldV11(a)-sh0),enemyHp:b.hp});}return {...ai,total:a.totals.damage+a.totals.proc+a.totals.dot,dpa:ai.actions?(a.totals.damage+a.totals.proc+a.totals.dot)/ai.actions:0,sequence:seq,healing:a.totals.healing,shield:a.totals.shield,proc:a.totals.proc,fantomonNotes:fantomonCoverage(fantomon)};}
function fantomonCoverage(f){if(!f?.enabled||!f.name)return {level:'exact',text:'No Fantomon selected.'};const exact=[] ,missing=[];if(f.name==='Pandarial')exact.push('Technique CD -1');if(f.name==='Aegiswing')exact.push('Guardian Angel lost-HP restoration');if(f.name==='Terragon')exact.push('50% ATK-reduction trigger');if(f.name==='Nyxarchon')exact.push('stacking 10% DEF Reduction');if(f.name==='Chomusuke')exact.push('50% DEF-reduction trigger');const req={Falko:['attackCoef'],Boaro:['shieldDefPct'],Mandragora:['healPct'],Zeioletus:['attackCoef'],Terragon:['attackCoef'],Sylvaerie:['atkBuffPct','spdBuffPct'],Kels:['attackCoef'],Armopi:['shieldDefPct'],Herbote:['healPct'],Nyxarchon:['attackCoef'],Aegiswing:['dmgBoostPct'],Pandarial:['dmgBoostPct'],Chomusuke:['attackCoef'],'Cabbage Dog':['dmgReducePct','blockPct'],Prismora:['dmgBoostPct'],'Luminarch Steed':['dmgReducePct','blockPct']}[f.name]||[];req.forEach(k=>{if(!(f[k]>0))missing.push(k)});const over=req.filter(k=>f[k]>0);return {level:missing.length?'partial':'derived',text:[exact.length?'Exact: '+exact.join(', ')+'.':'',over.length?'User-supplied overrides active: '+over.join(', ')+'.':'',missing.length?'Still missing optional magnitude(s): '+missing.join(', ')+'.':''].filter(Boolean).join(' ')};}
