function renderCoverage(){if(!$('coverageDashboard'))return;const s=collect(),cc=charmCoverage(s.charms),fc=fantomonCoverage(s.fantomon),setActive=extras.setRules.filter(r=>!['flat','percent','special'].includes(r.mode)&&(+r.value||0)>0).length,rows=[['Damage formula','EXACT','Source-backed damage/crit/block/mastery structure.'],['SPD timeline','EXACT','Square-root action clock and dynamic SPD buffs are evaluated each action.'],['Technique coefficients','EXACT',`${s.skills.filter(x=>x.on&&x.id).length}/${s.skills.filter(x=>x.on).length||0} selected Techniques matched to source records.`],['Timed statuses','DERIVED','ATK/DEF/SPD/DMG/Crit/Block buffs and debuffs use own-turn durations in the unified engine.'],['Healing & shields','DERIVED','Known numeric shield/heal magnitudes are applied, including conversion and threshold shields.'],['Charms',cc.unsupported.length?'PARTIAL':'EXACT',`${cc.modeled.length} selected active/dynamic effects modeled; ${cc.unsupported.length} remain unsupported.`],['Fantomon',fc.level==='partial'?'PARTIAL':'DERIVED',fc.text],['Set procs',setActive?'DERIVED':'PARTIAL',setActive?`${setActive} non-static set proc rule(s) have numeric values and are active.`:'Static bonuses and Chanting Prelude CD work; missing proc coefficients stay unvalued until supplied.'],['Movement / grid AI','NOT MODELED','Server movement, AoE target counts and full target-selection AI are not reproduced.']];const cls=x=>x==='EXACT'?'cov-exact':x==='DERIVED'?'cov-derived':x==='PARTIAL'?'cov-partial':'cov-missing';$('coverageDashboard').innerHTML=rows.map(r=>`<div class="coverage-row"><b>${r[0]}</b><span class="${cls(r[1])}">${r[1]}</span><span class="hint">${esc(r[2])}</span></div>`).join('');}

