function fullPvpRateV2(c,s,runs,seed){let w=0,d=0;withSeedV2(seed,()=>{for(let i=0;i<runs;i++){const x=oneDuelLoadoutV2(c.sheet,s.pvp.enemy,c.skills,s.pvp.skills,c.charms,s.pvp.charms,c.fant,s.pvp.enemyFantomon,c.gear,[],s.pvp.actionCap);if(x.result>0)w++;else if(x.result===0)d++}});return(w+.5*d)/runs}
function scoreFullV2(c,s,obj,quick=true,seed='v2'){if(obj==='PvP win rate')return fullPvpRateV2(c,s,quick?24:clamp(num('fullPvpRuns')||400,50,5000),seed);const sx={...s,skills:c.skills,charms:c.charms};if(obj==='Survivability')return survivabilityMetrics(c.sheet,s.pvp.enemy).effectiveHp;if(obj==='Support / healing')return supportMetricsV2(c.sheet,sx,c.skills,c.fant,c.gear).utility;const r=pveRotation(c.sheet,sx,c.skills,c.fant,c.gear);if(obj==='Balanced')return Math.sqrt(Math.max(1,r.total)*Math.max(1,survivabilityMetrics(c.sheet,s.pvp.enemy).effectiveHp));return r.total}
function gearCombosV2(s,cap){const pool=extras.inventory,by={};for(const x of pool)(by[x.slot||'Custom']??=[]).push(x);const groups=Object.values(by);return groups.length?cartesian(groups,cap):[equippedGearV59()]}
function techPoolV2(s){let names=$('techPool').value.split(/\n+/).map(x=>x.trim()).filter(Boolean);if(!names.length)names=TECHNIQUES.filter(x=>legalSkillClassV4(x.cls,s.build.className)).slice(0,10).map(x=>x.name);const rnk=skillRankNum(s.skills.find(x=>x.on)?.skillRank||22),lvl=s.skills.find(x=>x.on)?.skillLevel||s.build.level;return names.slice(0,10).map(n=>skillFromName(n,rnk,lvl)).filter(Boolean)}
function charmPoolV2(s){let names=$('charmPool').value.split(/\n+/).map(x=>x.trim()).filter(Boolean);if(!names.length)names=CHARMS.filter(x=>legalSkillClassV4(x.cls,s.build.className)).slice(0,8).map(x=>x.name);return names.slice(0,8).map(n=>{const sk=SKILL_BY_NAME.get(n.toLowerCase());return sk?{name:sk.name,id:sk.id,skillRank:s.charms.find(c=>c.name)?.skillRank||'22',skillLevel:s.build.level}:null}).filter(Boolean)}
function fantPoolV2(s){let names=$('fantPool').value.split(/\n+/).map(x=>x.trim()).filter(Boolean);if(!names.length)names=fantomonCatalogV5().map(x=>x.name);return names.map(n=>{const m=FANTOMON_BY_NAME.get(n.toLowerCase());return m?mergeFantV2({...baseFantomon(),enabled:true,name:m.name,id:m.id,level:s.fantomon.level||100,phase:s.fantomon.phase||'Adult',skillRank:s.fantomon.skillRank||'Mythic'}):null}).filter(Boolean)}
function trimBeamV2(arr,w){arr.sort((a,b)=>b.score-a.score);return arr.slice(0,w)}
function runFullOptimizerV2(){const s=collect(),obj=$('fullObjective').value,w=clamp(num('fullBeamWidth')||12,3,50),status=$('fullSearchStatus'),useG=$('fullUseGear').checked,useT=$('fullUseTech').checked,useC=$('fullUseCharm').checked,useF=$('fullUseFant').checked;status.textContent='Building candidate pools…';let beam=[{sheet:deep(s.build),gear:equippedGearV59(),skills:deep(s.skills),charms:deep(s.charms),fant:mergeFantV2(s.fantomon),score:0}];const seed=$('pvpSeed')?.value||'SXS-v2';
 if(useG){const gs=gearCombosV2(s,clamp(num('fullGearCap')||5000,50,100000));let next=[];for(const g of gs){const c={...beam[0],gear:g,sheet:inventorySheetFor(g,s)};c.score=scoreFullV2(c,s,obj,true,seed+'|g|'+g.map(x=>x.name).join(','));next.push(c)}beam=trimBeamV2(next,w);status.textContent=`Gear stage: ${gs.length} combinations → ${beam.length} finalists.`}
 if(useT){const pool=techPoolV2(s),sets=pool.length>=4?combinations(pool,4,1200):[s.skills];let next=[];for(const base of beam)for(const skills of sets){const c={...base,skills};c.score=scoreFullV2(c,s,obj,true,seed+'|t|'+skills.map(x=>x.name).join(','));next.push(c);if(next.length>w*250)next=trimBeamV2(next,w*3)}beam=trimBeamV2(next,w);status.textContent+=` Technique stage: ${sets.length} loadouts.`}
 if(useC){const pool=charmPoolV2(s),sets=pool.length>=4?combinations(pool,4,100):[s.charms];let next=[];for(const base of beam)for(const charms of sets){const c={...base,charms};c.score=scoreFullV2(c,s,obj,true,seed+'|c|'+charms.map(x=>x.name).join(','));next.push(c);if(next.length>w*160)next=trimBeamV2(next,w*3)}beam=trimBeamV2(next,w);status.textContent+=` Charm stage: ${sets.length} loadouts.`}
 if(useF){const pool=fantPoolV2(s);let next=[];for(const base of beam)for(const fant of pool){const c={...base,fant};c.score=scoreFullV2(c,s,obj,true,seed+'|f|'+fant.name);next.push(c)}beam=trimBeamV2(next,w);status.textContent+=` Fantomon stage: ${pool.length} options.`}
 for(const c of beam)c.score=scoreFullV2(c,s,obj,false,seed+'|final|'+c.gear.map(x=>x.name).join(',')+c.skills.map(x=>x.name).join(',')+c.charms.map(x=>x.name).join(',')+(c.fant?.name||''));beam=trimBeamV2(beam,5);lastFullBuildV2=beam[0]||null;$('applyFullOptimizerBtn').disabled=!lastFullBuildV2;$('fullOptimizerResult').innerHTML=beam.map((c,i)=>`<div class="v2-result ${i===0?'best':''}"><h4>${i===0?'Recommended complete build':'#'+(i+1)} · ${obj==='PvP win rate'?(c.score*100).toFixed(1)+'%':fmt(c.score)}</h4><div class="optimizer-dimension"><b>Gear</b><span>${c.gear.map(x=>esc(x.name)).join(' · ')||'current'}</span></div><div class="optimizer-dimension"><b>Techniques</b><span>${c.skills.filter(x=>x.on).map(x=>esc(x.name)).join(' · ')}</span></div><div class="optimizer-dimension"><b>Charms</b><span>${c.charms.filter(x=>x.name).map(x=>esc(x.name)).join(' · ')||'none'}</span></div><div class="optimizer-dimension"><b>Fantomon</b><span>${esc(c.fant?.name||'None')}</span></div><div class="v2-chips" style="margin-top:8px"><span class="v2-chip">ATK ${fmt(c.sheet.atk)}</span><span class="v2-chip">SPD ${fmt(c.sheet.spd)}</span><span class="v2-chip">HP ${fmt(c.sheet.hp)}</span></div></div>`).join('');status.textContent+=' Finalists re-evaluated with the full objective.';}
function applyFullBuildV2(){if(!lastFullBuildV2)return;const c=lastFullBuildV2;fillBuild('my',c.sheet);[0,1,2,3].forEach(i=>fillSkill('mine',i,c.skills[i]||baseSkill()));[0,1,2,3].forEach(i=>fillCharm('mine',i,c.charms[i]||baseCharm()));fillFantomon('my',c.fant||baseFantomon());const map=ensureV59().equippedGearIdsV59;Object.keys(map).forEach(k=>delete map[k]);for(const it of c.gear||[])if(it?.slot)map[it.slot]=it.id;for(const it of extras.inventory){it.equipped=false;it.use=true}saveExtras();renderInventory();renderCurrentGearLoadoutV59();renderCurrentLoadoutSummaryV59();recalc();updateV1Dashboards();toast('Applied optimized complete build')}
function runFantOptimizerV2(){const s=collect(),obj=$('fantObjective').value,runs=clamp(num('fantPvpRuns')||300,50,5000),seed=$('pvpSeed')?.value||'SXS-v2',rows=[];for(const fant of fantPoolV2(s)){const c={sheet:s.build,gear:equippedGearV59(),skills:s.skills,charms:s.charms,fant};const score=obj==='PvP win rate'?fullPvpRateV2(c,s,runs,seed+'|fant|'+fant.name):obj==='Support / healing'?supportMetricsV2(s.build,{...s,charms:s.charms},s.skills,fant,c.gear).utility:pveRotation(s.build,{...s,charms:s.charms},s.skills,fant,c.gear).total;rows.push({fant,score,cov:fantomonCoverage(fant)})}rows.sort((a,b)=>b.score-a.score);lastFantBuildV2=rows[0];$('fantOptimizerResult').innerHTML=rows.slice(0,10).map((x,i)=>`<div class="v2-result ${i===0?'best':''}"><b>${i===0?'Best':'#'+(i+1)} ${esc(x.fant.name)}</b> · ${obj==='PvP win rate'?(x.score*100).toFixed(1)+'%':fmt(x.score)}<br><small>${esc(x.cov.text)}</small></div>`).join('')}
function renderEnhV2(){const name=$('enhGearName').value.trim(),g=runtimeGear.find(x=>x.name.toLowerCase()===name.toLowerCase())||GEAR_BY_NAME.get(name.toLowerCase());if(!g){$('enhResult').innerHTML='Select a known gear item.';return null}const sec=(g.secondaries||[]).find(x=>x.label===$('enhSecondary').value)||(g.secondaries||[])[0],m=gearMain(g),up=num('enhUpgrade'),season=num('enhSeason'),mr=m?enhancementV2(m[1],up,season):null,sr=sec?enhancementV2(sec.value,up,season):null,exact=(mr?.exact!==false)&&(sr?.exact!==false);$('enhResult').innerHTML=`<b>${esc(g.name)}</b><br>${m?`${STAT_LABEL[m[0]]||m[0]} <b>${fmt(mr.value)}</b>`:''}${sr?` · ${esc(sec.label)} <b>${fmt(sr.value)}</b>`:''}<br><small>${exact?'Exact at displayed source factor anchors':'Derived interpolation between displayed source factor anchors'} · multiplier ${mr?mr.mult.toFixed(3):'—'}×</small>`;return{g,sec,stats:[m&&[m[0],mr.value],sr&&[sec.key,sr.value]].filter(Boolean),exact,up,season}}
function addEnhancedInventoryV2(){const x=renderEnhV2();if(!x)return;addInventoryItem({name:x.g.name,slot:canonicalSlot(x.g),secondary:x.sec?.label||'',set:(x.g.sets||[])[0]||'',stats:x.stats,source:x.exact?'datamine enhancement anchors':'derived enhancement interpolation',upgrade:x.up,seasonEnh:x.season})}
function costUpgradeV2(){runUpgradeNext();const s=collect(),base=pveRotation(s.build,s,s.skills,s.fantomon,equippedGearV59()).total,rows=[],cost={stat:Math.max(.0001,num('costStat')||1),skill:Math.max(.0001,num('costTechnique')||1),gear:Math.max(.0001,num('costGear')||1),fant:Math.max(.0001,num('costFant')||1)};[['ATK','atk',1000],['Elemental Mastery','mast',1000],['Physical Mastery','kfm',1000],['SPD','spd',1000],['Crit Rate','cr',1],['Crit DMG','cd',1],['DMG Boost','boost',1]].forEach(([label,k,v])=>{const b=deep(s.build);b[k]=(b[k]||0)+v;const val=pveRotation(b,s,s.skills,s.fantomon,[]).total,g=deltaPct(base,val);rows.push({name:`+${v} ${label}`,gain:g,cost:cost.stat,kind:'stat'})});s.skills.forEach((sk,i)=>{if(!sk.on)return;const obj=SKILL_BY_NAME.get(sk.name.toLowerCase()),n=skillRankNum(sk.skillRank);if(obj&&n<34){const row=skillAtRank(obj,n+1),est=estimateTotalCoef(obj,row);if(est.value!=null){const ss=deep(s.skills);ss[i].coef=est.value;ss[i].skillRank=String(n+1);const val=pveRotation(s.build,s,ss,s.fantomon,[]).total;rows.push({name:`${sk.name}: ${DM.rankLabels[n]} → ${DM.rankLabels[n+1]}`,gain:deltaPct(base,val),cost:cost.skill,kind:'Technique'})}}});for(const f of fantPoolV2(s)){const val=pveRotation(s.build,s,s.skills,f,[]).total,g=deltaPct(base,val);if(g>0)rows.push({name:`Switch / upgrade Fantomon → ${f.name}`,gain:g,cost:cost.fant,kind:'Fantomon'})}const equipped=equippedGearV59();for(const it of extras.inventory.filter(x=>!equipped.some(e=>e.id===x.id))){const old=equipped.find(x=>x.slot===it.slot);if(!old)continue;const combo=equipped.filter(x=>x!==old).concat(it),sheet=inventorySheetFor(combo,s),val=pveRotation(sheet,s,s.skills,s.fantomon,combo).total;rows.push({name:`${it.slot}: ${old.name} → ${it.name}`,gain:deltaPct(base,val),cost:cost.gear,kind:'Gear'})}rows.forEach(r=>r.eff=r.gain/r.cost);rows.sort((a,b)=>b.eff-a.eff);$('costUpgradeResult').innerHTML='<div class="table-wrap"><table class="v2-table"><thead><tr><th>Upgrade</th><th>Gain</th><th>Cost</th><th>Gain / cost</th></tr></thead><tbody>'+rows.slice(0,15).map(r=>`<tr><td>${esc(r.name)}</td><td>${pct(r.gain)}</td><td>${fmt(r.cost,2)}</td><td><b>${r.eff.toFixed(3)}</b></td></tr>`).join('')+'</tbody></table></div>'}
function runPvp(){const s=collect(),A=foodAdjustedBuildV4(s.build,'Arena'),B=s.pvp.enemy,LA=s.skills.filter(x=>x.on),LB=s.pvp.skills.filter(x=>x.on),CA=s.charms,CB=s.pvp.charms,FA=s.fantomon,FB=s.pvp.enemyFantomon,runs=clamp(s.pvp.runs,1,10000),cap=clamp(s.pvp.actionCap,10,500),seed=$('pvpSeed')?.value||'SXS-v2',use=$('pvpUseSeed')?.checked!==false;let w=0,l=0,d=0,remA=0,remB=0,acts=0,firstA=0;const exec=()=>{for(let i=0;i<runs;i++){const x=oneDuelLoadoutV2(A,B,LA,LB,CA,CB,FA,FB,equippedGearV59(),[],cap);if(x.result>0)w++;else if(x.result<0)l++;else d++;remA+=Math.max(0,x.hp[0]);remB+=Math.max(0,x.hp[1]);acts+=x.actions;if(x.first===0)firstA++}};use?withSeedV2(seed,exec):exec();const eq=w+.5*d,[lo,hi]=wilsonV2(eq,runs);$('pvpResults').hidden=false;$('pvpWin').textContent=(eq/runs*100).toFixed(1)+'%';$('pvpLoss').textContent=(l/runs*100).toFixed(1)+'%';$('pvpDraw').textContent=(d/runs*100).toFixed(1)+'%';$('pvpFirst').textContent=firstA===runs?'You':firstA===0?'Opponent':(firstA/runs*100).toFixed(1)+'% you';if($('pvpCI'))$('pvpCI').textContent=`95% CI ${(lo*100).toFixed(1)}–${(hi*100).toFixed(1)}%`;$('pvpDetail').innerHTML=`<h3>Simulation detail</h3><p><b>${fmt(runs)}</b> fights · average ${fmt(acts/runs,1)} actions · action cap ${cap}.</p><p>Average HP remaining: You <b>${fmt(remA/runs)}</b> · Opponent <b>${fmt(remB/runs)}</b>.</p><p><span class="seed-badge">${use?'seed '+esc(seed):'unseeded'}</span> Draws count as half a win in the headline probability.</p><p>Your Fantomon: <b>${esc(FA.enabled?FA.name:'None')}</b> · Opponent: <b>${esc(FB.enabled?FB.name:'None')}</b></p>`;}
function runBatchPvpV2(){const s=collect(),runs=clamp(num('batchPvpRuns')||300,50,5000),seed=$('pvpSeed')?.value||'SXS-v2',targets=[{name:'Current PvP opponent',build:deep(s.pvp.enemy),skills:deep(s.pvp.skills),charms:deep(s.pvp.charms),fant:deep(s.pvp.enemyFantomon)}];for(const p of runtimeNpcs.filter(x=>x.kind==='PvP'))targets.push({name:p.name,build:{...s.pvp.enemy,...p},skills:s.pvp.skills,charms:s.pvp.charms,fant:s.pvp.enemyFantomon});if($('batchIncludeProfiles').checked)for(const p of extras.profiles){const st=p.state||{};if(st.build)targets.push({name:'Profile: '+p.name,build:st.build,skills:st.skills||s.pvp.skills,charms:st.charms||[],fant:st.fantomon||baseFantomon()})}const c={sheet:s.build,gear:equippedGearV59(),skills:s.skills,charms:s.charms,fant:s.fantomon},rows=targets.slice(0,30).map(t=>{let w=0,d=0;withSeedV2(seed+'|batch|'+t.name,()=>{for(let i=0;i<runs;i++){const x=oneDuelLoadoutV2(c.sheet,t.build,c.skills,t.skills,c.charms,t.charms,c.fant,t.fant,c.gear,[],s.pvp.actionCap);if(x.result>0)w++;else if(x.result===0)d++}});const rate=(w+.5*d)/runs,[lo,hi]=wilsonV2(w+.5*d,runs);return{name:t.name,rate,lo,hi}}).sort((a,b)=>b.rate-a.rate);$('batchPvpResult').innerHTML='<div class="table-wrap"><table><thead><tr><th>Opponent</th><th>Win chance</th><th>95% CI</th></tr></thead><tbody>'+rows.map(r=>`<tr><td>${esc(r.name)}</td><td><b>${(r.rate*100).toFixed(1)}%</b></td><td>${(r.lo*100).toFixed(1)}–${(r.hi*100).toFixed(1)}%</td></tr>`).join('')+'</tbody></table></div>'}
function renderSupport(){if(!$('supportDashboard'))return;const s=collect(),m=supportMetricsV2(s.build,s,s.skills,effectivePveFantomon(),equippedGearV59());$('supportDashboard').innerHTML=`<div class="mini-grid"><div><span class="muted">Healing / action</span><div class="big-stat">${fmt(m.hpa)}</div></div><div><span class="muted">Shield / action</span><div class="big-stat">${fmt(m.spa)}</div></div><div><span class="muted">Control-turn value</span><div class="big-stat">${fmt(m.control,1)}</div></div><div><span class="muted">Cleanse / dispel</span><div class="big-stat">${fmt(m.cleanse+m.dispel,1)}</div></div></div><p class="hint">Modeled totals: ${fmt(m.healing)} healing · ${fmt(m.shield)} shields · buff uptime score ${m.buffUptime.toFixed(2)} · debuff uptime score ${m.debuffUptime.toFixed(2)}. Unknown coefficients remain unvalued.</p>`}
