function renderMechanicsCoverageV2(){if(!$('mechanicsCoverage'))return;const s=collect(),cc=charmCoverage(s.charms),sets=runtimeSetDefsV2.length?`${runtimeSetDefsV2.length} imported set definitions`:`${new Set(extras.setRules.map(x=>x.set)).size} local set names`;$('mechanicsCoverage').innerHTML=`<p><b>Charms:</b> ${cc.modeled.length} explicit models · ${cc.staticOnly.length} static-in-sheet · ${cc.unsupported.length} generic/unknown.</p>${cc.unsupported.length?`<p class="hint">Generic parser attempts row-based effects for: ${esc(cc.unsupported.join(', '))}</p>`:''}<p><b>Sets:</b> ${sets}. Numeric trigger text is converted to rules automatically after equipment.html import/sync.</p>`}
function renderCoverage(){if(!$('coverageDashboard'))return;const s=collect(),cc=charmCoverage(s.charms),fc=fantomonCoverage(mergeFantV2(s.fantomon)),cached=runtimeGear.length>DM.gear.length,rows=[['Damage / Crit / Block','EXACT','Source-backed formula structure.'],['SPD timeline','EXACT','Square-root action clock; seeded PvP is reproducible.'],['Technique coefficients','EXACT',`${s.skills.filter(x=>x.on&&x.id).length}/${s.skills.filter(x=>x.on).length||0} selected Techniques matched.`],['Statuses / control','DERIVED','Numeric buff/debuff text, Stun/Frozen, dispel, cleanse, action-delay and repeat-cast patterns are modeled where stated.'],['Healing / shields','DERIVED','Known numeric coefficients flow through the shared runtime.'],['Charms',cc.unsupported.length?'PARTIAL':'EXACT',`${cc.modeled.length} explicit models; generic row parser covers additional unsupported effects when their row exposes a magnitude.`],['Fantomon',fc.level==='partial'?'PARTIAL':'DERIVED',fc.text],['Set procs',runtimeSetDefsV2.length?'DERIVED':'PARTIAL',runtimeSetDefsV2.length?`${runtimeSetDefsV2.length} set descriptions imported; numeric text is compiled automatically.`:'Import/sync equipment.html for the complete set-text catalog.'],['Equipment catalog',cached?'EXACT':'PARTIAL',cached?`${runtimeGear.length} cached gear variants available offline in this browser/workspace.`:`Bundled seed catalog has ${DM.gear.length} items; full generated catalog can be imported and cached.`],['AoE target count','DERIVED','Technique card geometry is reduced to an average targets-hit input; exact grid positions remain outside this 1D simulator.'],['Server movement / AI','NOT MODELED','4v4 pathfinding is modeled on the client grid; server-default target-scoring weights remain unavailable.']];const cls=x=>x==='EXACT'?'cov-exact':x==='DERIVED'?'cov-derived':x==='PARTIAL'?'cov-partial':'cov-missing';$('coverageDashboard').innerHTML=rows.map(r=>`<div class="coverage-row"><b>${r[0]}</b><span class="${cls(r[1])}">${r[1]}</span><span class="hint">${esc(r[2])}</span></div>`).join('');renderMechanicsCoverageV2();renderAoeV2()}
