function ensureV3(){ensureV2();extras.v3=extras.v3||{};const v=extras.v3;v.team=v.team||{A:['current','profile:0','profile:1','profile:2'],B:['pvp','preset:Typical PvP','preset:PvP Tank','preset:PvP Glass Cannon'],pos:deep(TEAM_START_V3)};v.team.pos=v.team.pos||deep(TEAM_START_V3);v.ec=v.ec||{skills:{},rules:[],source:'Bundled card text only'};v.petTree=v.petTree||{nodes:[],source:'No exact pet ability rows imported'};v.fantFormation=v.fantFormation||FANTOMONS.slice(0,4).map(x=>x.name);v.account=v.account||{sources:['current','profile:0','profile:1','profile:2']};}
function profileSourcesV3(){const out=[['current','Current My Build'],['pvp','Current PvP opponent']];extras.profiles.forEach((p,i)=>out.push([`profile:${i}`,`Profile: ${p.name}`]));runtimeNpcs.filter(x=>x.kind==='PvP').forEach(p=>out.push([`preset:${p.name}`,p.name]));return out;}
