function renderTeamSlotsV3(){ensureV3();for(const side of ['A','B']){const root=$(`team${side}Slots`);if(!root)continue;root.innerHTML='';for(let i=0;i<4;i++){const key=extras.v3.team[side][i]||'current',src=sourceStateV3(key),d=document.createElement('div');d.className='team-slot'+(teamSelectedV3.side===side&&teamSelectedV3.idx===i?' active':'');const opts=profileSourcesV3().map(([v,n])=>`<option value="${esc(v)}" ${v===key?'selected':''}>${esc(n)}</option>`).join('');d.innerHTML=`<h4>${side}${i+1} · ${esc(src.name)}</h4><select data-side="${side}" data-idx="${i}">${opts}</select><div class="hint" style="margin-top:5px">${esc(src.state.build?.className||'')} · HP ${fmt(src.state.build?.hp||0)} · SPD ${fmt(src.state.build?.spd||0)}</div>`;d.onclick=e=>{if(e.target.tagName!=='SELECT'){teamSelectedV3={side,idx:i};renderTeamSlotsV3();renderTeamBoardV3()}};d.querySelector('select').onchange=e=>{extras.v3.team[side][i]=e.target.value;saveExtras();renderTeamSlotsV3();renderTeamBoardV3()};root.appendChild(d)}}}
