function renderTeamBoardV3(units=null,hazards=activeHazardsV3){ensureV3();const root=$('teamBoard');if(!root)return;root.innerHTML='';const tokens=new Map(),hz=new Set((hazards||[]).map(h=>posKeyV3(h.x,h.y)));if(units){units.forEach(u=>tokens.set(posKeyV3(u.x,u.y),u))}else{for(const side of ['A','B'])for(let i=0;i<4;i++){const p=extras.v3.team.pos[side][i];tokens.set(posKeyV3(p[0],p[1]),{side,idx:i,name:`${side}${i+1}`,alive:true,hp:1,maxHp:1})}}for(let yy=TEAM_H_V3-1;yy>=0;yy--)for(let x=0;x<TEAM_W_V3;x++){const cell=document.createElement('div');const blocked=TEAM_BLOCKED_V3.has(posKeyV3(x,yy)),hazard=hz.has(posKeyV3(x,yy));cell.className='grid-cell'+(inZoneV3('A',x,yy)?' zone-a':'')+(inZoneV3('B',x,yy)?' zone-b':'')+(blocked?' blocked':'')+(hazard?' hazard':'');cell.dataset.x=x;cell.dataset.y=yy;const u=tokens.get(posKeyV3(x,yy));if(u){const t=document.createElement('span');t.className=`grid-token ${String(u.side).toLowerCase()} ${u.alive===false?'dead':''}`;t.textContent=`${u.side}${u.idx+1}`;t.title=`${u.name||''}${u.maxHp?` · ${Math.max(0,u.hp/u.maxHp*100).toFixed(0)}% HP`:''}`;cell.appendChild(t)}if(!units&&!blocked&&teamSelectedV3&&inZoneV3(teamSelectedV3.side,x,yy))cell.onclick=()=>placeTeamUnitV3(x,yy);root.appendChild(cell)}}
function placeTeamUnitV3(x,y){const {side,idx}=teamSelectedV3;if(!inZoneV3(side,x,y)||TEAM_BLOCKED_V3.has(posKeyV3(x,y)))return;const other=extras.v3.team.pos[side].findIndex((p,j)=>j!==idx&&p[0]===x&&p[1]===y);if(other>=0){const old=extras.v3.team.pos[side][idx];extras.v3.team.pos[side][other]=old}extras.v3.team.pos[side][idx]=[x,y];saveExtras();renderTeamBoardV3()}
