function recursivePairsV3(obj,path='',out=[]){if(!obj||typeof obj!=='object')return out;if(Array.isArray(obj)){if(obj.length&&obj.every(x=>Array.isArray(x)&&x.length>=2&&Number.isFinite(+x[0])&&Number.isFinite(+x[1])))out.push({path,pairs:obj.map(x=>[+x[0],+x[1]])});obj.forEach((x,i)=>recursivePairsV3(x,path+'/'+i,out));return out}for(const [k,v] of Object.entries(obj))recursivePairsV3(v,path+'/'+k,out);return out}
