function reduceEcSkillV3(s){const raw=s.ec||s.EC||s.prefab||s;const pairsets=recursivePairsV3(raw),ranges=pairsets.filter(x=>/range/i.test(x.path)),scopes=pairsets.filter(x=>/scope|scop/i.test(x.path));const choose=a=>a.sort((x,y)=>y.pairs.length-x.pairs.length)[0]?.pairs||[];const r=choose(ranges),sc=choose(scopes);const child=[...new Set(recursiveValuesV3(raw,/child.*skill|skill.*child/i).map(Number).filter(Number.isFinite))];return{id:+s.id||+s.Id||0,name:s.name||s.Name||'',range:r,scope:sc,child,rawHint:!!(r.length||sc.length||child.length)}}
function installEcBundleV3(data,name='Imported EC JSON'){ensureV3();let skills=[],rules=[];if(Array.isArray(data))skills=data;else if(Array.isArray(data.skills))skills=data.skills;else if(Array.isArray(data.Skills))skills=data.Skills;if(Array.isArray(data.rules))rules=data.rules;if(Array.isArray(data.sxsRules))rules=data.sxsRules;const reduced={};for(const s of skills){const r=reduceEcSkillV3(s);if(r.id)reduced[r.id]=r}extras.v3.ec={skills:reduced,rules:rules.slice(0,5000),source:name,importedAt:Date.now()};saveExtras();renderEcStatusV3();renderTeamBoardV3();toast(`EC cache: ${Object.keys(reduced).length} skills · ${rules.length} compact rules`)}
