function parseSkillGeomV3(sk){ensureV3();const id=+sk.id||0,ec=extras.v3.ec.skills?.[id];if(ec?.range?.length||ec?.scope?.length){const range=Math.max(1,...(ec.range||[]).map(p=>Math.abs(p[0])+Math.abs(p[1])));return{source:'EC',range,rangeCoords:ec.range||[],scopeCoords:ec.scope||[],area:Math.max(1,(ec.scope||[]).length),self:/caster|self/i.test(SKILL_BY_NAME.get(String(sk.name).toLowerCase())?.desc||'')}}const desc=(SKILL_BY_NAME.get(String(sk.name).toLowerCase())?.desc||sk.desc||'').replace(/×/g,'x');let range=1,m=desc.match(/within\s+(\d+)\s*-?\s*grid/i)||desc.match(/reaches?\s+(\d+)/i);if(m)range=+m[1];m=desc.match(/(\d+)\s*x\s*(\d+)\s*grid/i);let area=m?+m[1]*+m[2]:1;if(/all enemies within/i.test(desc)){const rr=(desc.match(/within\s+(\d+)/i)||[])[1];if(rr)area=1+2*+rr*(+rr+1)}if(/square area/i.test(desc)){const rr=(desc.match(/(\d+)\s*-?grid square/i)||[])[1];if(rr)area=(2*+rr+1)**2}const self=/around the caster|of the caster|within .* caster/i.test(desc)&&/all enemies/i.test(desc);const front=/in front of the caster/i.test(desc)&&m?{w:+m[1],d:+m[2]}:null;if(front)range=Math.max(front.w,front.d);return{source:'CARD',range,area,self,front,rangeCoords:[],scopeCoords:[]}}
function manV3(a,b){return Math.abs(a.x-b.x)+Math.abs(a.y-b.y)}
function occupiedV3(units,ignore=null){const s=new Set();for(const u of units)if(u!==ignore&&(u.alive||u.corpse))s.add(posKeyV3(u.x,u.y));return s}
function bfsV3(unit,units,maxDist){const occ=occupiedV3(units,unit),q=[[unit.x,unit.y,0]],seen=new Set([posKeyV3(unit.x,unit.y)]),out=[{x:unit.x,y:unit.y,d:0}];while(q.length){const [x,y,d]=q.shift();if(d>=maxDist)continue;for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,ny=y+dy,k=posKeyV3(nx,ny);if(nx<0||ny<0||nx>=TEAM_W_V3||ny>=TEAM_H_V3||TEAM_BLOCKED_V3.has(k)||seen.has(k)||occ.has(k))continue;seen.add(k);q.push([nx,ny,d+1]);out.push({x:nx,y:ny,d:d+1})}}return out}
function rotateRelV3(p,from,to){const dx=to.x-from.x,dy=to.y-from.y;let dir=Math.abs(dx)>Math.abs(dy)?(dx>=0?'R':'L'):(dy>=0?'U':'D');const [x,y]=p;if(dir==='U')return[x,y];if(dir==='D')return[-x,-y];if(dir==='R')return[y,-x];return[-y,x]}
function targetsFromV3(unit,move,sk,enemies){const g=parseSkillGeomV3(sk),primary=enemies.slice().sort((a,b)=>manV3(move,a)-manV3(move,b)||a.hp-b.hp)[0];if(!primary)return[];if(g.front){const dx=primary.x-move.x,dy=primary.y-move.y,vert=Math.abs(dy)>=Math.abs(dx),sgn=vert?Math.sign(dy||1):Math.sign(dx||1),hits=enemies.filter(e=>{const f=vert?(e.y-move.y)*sgn:(e.x-move.x)*sgn,side=vert?Math.abs(e.x-move.x):Math.abs(e.y-move.y);return f>=1&&f<=g.front.d&&side<=Math.floor((g.front.w-1)/2)});return hits}if(g.self){return enemies.filter(e=>manV3(move,e)<=g.range).slice(0,g.area)}if(g.rangeCoords.length){const allowed=new Set(g.rangeCoords.map(p=>{const q=rotateRelV3(p,move,primary);return posKeyV3(move.x+q[0],move.y+q[1])}));if(!allowed.has(posKeyV3(primary.x,primary.y)))return[]}
 else if(manV3(move,primary)>g.range)return[];if(g.scopeCoords.length){const cells=new Set(g.scopeCoords.map(p=>{const q=rotateRelV3(p,move,primary);return posKeyV3(primary.x+q[0],primary.y+q[1])}));cells.add(posKeyV3(primary.x,primary.y));return enemies.filter(e=>cells.has(posKeyV3(e.x,e.y)))}return enemies.filter(e=>manV3(e,primary)<=Math.max(0,Math.floor((g.area-1)/4))).slice(0,g.area)}
function readySkillsV3(u){return u.skills.map((sk,i)=>({sk,i})).filter(x=>x.sk?.on&&u.rt.turn>=u.rt.ready[x.i])}
function chooseTeamActionV3(u,units,moveDist){const enemies=units.filter(x=>x.side!==u.side&&x.alive),allies=units.filter(x=>x.side===u.side&&x.alive),moves=bfsV3(u,units,moveDist);let best=null;for(const {sk,i} of readySkillsV3(u)){const desc=SKILL_BY_NAME.get(String(sk.name).toLowerCase())?.desc||'',support=(sk.coef||0)<=0&&/heal|restore|shield|ally|buff|increase|grant/i.test(desc),pool=support?allies:enemies;for(const m of moves){const t=targetsFromV3(u,m,sk,pool);if(!t.length)continue;const score=t.length*10000-m.d*100-(t[0]?.hp/(t[0]?.maxHp||1));if(!best||score>best.score)best={sk,i,move:m,targets:t,score}}if(best)return best}if(!enemies.length)return null;const nearest=enemies.slice().sort((a,b)=>manV3(u,a)-manV3(u,b))[0],moves2=moves.slice().sort((a,b)=>manV3(a,nearest)-manV3(b,nearest)||b.d-a.d);return{pass:true,move:moves2[0],targets:[],score:0}}
function secondaryHitV3(att,def,sk){if(!sk.coef)return 0;let total=0,hits=Math.max(1,sk.hits||1),per=(sk.coef||0)/hits;for(let h=0;h<hits&&def.rt.hp>0;h++){const roll=rollHitV11(att.rt,def.rt,sk,per,h===0?(sk.flat||0):0,'pvp',true);dealV11(def.rt,roll.damage,att.rt,{technique:true,mode:'pvp'});att.rt.totals.damage+=roll.damage;total+=roll.damage}return total}
function teamPushV3(target,source,dist,units){let dx=Math.sign(target.x-source.x),dy=Math.sign(target.y-source.y);if(Math.abs(target.x-source.x)>=Math.abs(target.y-source.y))dy=0;else dx=0;const occ=occupiedV3(units,target);for(let i=0;i<dist;i++){const nx=target.x+dx,ny=target.y+dy;if(nx<0||ny<0||nx>=TEAM_W_V3||ny>=TEAM_H_V3||TEAM_BLOCKED_V3.has(posKeyV3(nx,ny))||occ.has(posKeyV3(nx,ny)))break;target.x=nx;target.y=ny}}
function compactRulesV3(owner,event){ensureV3();return(extras.v3.ec.rules||[]).filter(r=>(!r.ownerId||+r.ownerId===+owner.id||String(r.ownerName||'').toLowerCase()===String(owner.name||'').toLowerCase())&&String(r.event||'').toLowerCase()===String(event).toLowerCase())}
let activeHazardsV3=[];
function addGridHazardV3(src,tgt,a,r){const radius=Math.max(0,Math.floor(+a.radius||0)),shape=String(a.shape||'diamond').toLowerCase(),dur=Math.max(1,Math.floor(+a.duration||3));for(let dx=-radius;dx<=radius;dx++)for(let dy=-radius;dy<=radius;dy++){if(shape!=='square'&&Math.abs(dx)+Math.abs(dy)>radius)continue;const x=tgt.x+dx,y=tgt.y+dy;if(x<0||y<0||x>=TEAM_W_V3||y>=TEAM_H_V3||TEAM_BLOCKED_V3.has(posKeyV3(x,y)))continue;activeHazardsV3.push({x,y,source:src,sourceKey:src?`${src.side}:${src.idx}`:'',coef:+a.coef||0,flat:+a.flat||0,hits:Math.max(1,+a.hits||1),element:a.element||'Fire',turns:dur,name:a.name||r?.name||'Grid hazard',tryAtStart:a.tryAtStart!==false,tryAtEnter:a.tryAtEnter!==false,tryAtRound:a.tryAtRound!==false})}}
function fireHazardV3(h,u){if(!h||!u?.alive||!h.source?.alive||u.side===h.source.side)return 0;return secondaryHitV3(h.source,u,{on:true,name:h.name||'Grid hazard',element:h.element||'Fire',coef:+h.coef||0,flat:+h.flat||0,hits:+h.hits||1})}
