const SKILL_BY_ID_V3=new Map(DM.skills.map(x=>[+x.id,x]));
function executeTeamSkillV3(att,targets,sk,units,depth=0){if(depth>=4||!targets.length)return 0;dispatchRulesV3(sk,'beforeCast',{att,target:targets[0],units},depth);let total=performActionV2(att.rt,targets[0].rt,sk,'pvp',true);for(const t of targets.slice(1))total+=secondaryHitV3(att,t,sk);const desc=SKILL_BY_NAME.get(String(sk.name).toLowerCase())?.desc||'';const kb=(desc.match(/knock(?:s|ing)? (?:them |the target )?(?:back|away).*?(\d+)\s*grid/i)||[])[1];if(kb)targets.forEach(t=>teamPushV3(t,att,+kb,units));dispatchRulesV3(sk,'afterHit',{att,target:targets[0],def:targets[0],units},depth);dispatchUnitRulesV3(att,'afterHit',{att,target:targets[0],def:targets[0],units},depth);for(const t of targets)dispatchUnitRulesV3(t,'damaged',{att:t,target:att,def:att,units},depth);const ec=extras.v3.ec.skills?.[+sk.id];for(const cid of ec?.child||[]){const c=SKILL_BY_ID_V3.get(+cid);if(c)executeTeamSkillV3(att,targets,c,units,depth+1)}return total}
function makeTeamUnitV3(side,idx,key,pos){const src=sourceStateV3(key),st=src.state,b=deep(st.build),skills=(st.skills||[]).filter(x=>x.on),charms=st.charms||[],fant=mergeFantV2(st.fantomon||baseFantomon()),items=Array.isArray(st._v3Gear)?st._v3Gear:(key==='current'?equippedGearV59():[]),rt=mkRtV11(b,skills,charms,fant,items);return{side,idx,key,name:src.name,build:b,skills,charms,fant,rt,x:pos[0],y:pos[1],alive:true,corpse:false,maxHp:rt.maxHp,hp:rt.hp,next:100000/Math.sqrt(Math.max(1,b.spd)*Math.max(1,rankObj(b.rank).speedScale)),actions:0}}
function syncUnitHpV3(u){u.hp=u.rt.hp;u.alive=u.rt.hp>0;if(!u.alive)u.corpse=true}
function prebattleTeamV3(units){for(const u of units){const foe=units.find(x=>x.side!==u.side);if(!foe)continue;prebattleV11(u.rt,foe.rt,'pvp',true);genericCharmTriggerV2(u.rt,foe.rt,'beforeBattle','pvp',true);dispatchUnitRulesV3(u,'beforeBattle',{att:u,target:foe,units});for(const sk of u.skills)dispatchRulesV3(sk,'beforeBattle',{att:u,target:foe,units});syncUnitHpV3(u)}}
function simulateTeamOnceV3(seed='team',wantLog=false){ensureV3();activeHazardsV3=[];const units=[];for(const side of ['A','B'])for(let i=0;i<4;i++)units.push(makeTeamUnitV3(side,i,extras.v3.team[side][i],extras.v3.team.pos[side][i]));const log=[],cap=clamp(+$('teamActionCap').value||240,20,1000),moveDist=clamp(+$('teamMoveDist').value||4,1,10);const run=()=>{prebattleTeamV3(units);let actions=0;while(actions<cap&&units.some(u=>u.side==='A'&&u.alive)&&units.some(u=>u.side==='B'&&u.alive)){const alive=units.filter(u=>u.alive).sort((a,b)=>a.next-b.next||a.side.localeCompare(b.side)||a.idx-b.idx),u=alive[0],foe=units.find(x=>x.side!==u.side&&x.alive);if(!u||!foe)break;startTurnV11(u.rt,foe.rt,'pvp',true);genericCharmTriggerV2(u.rt,foe.rt,'turnStart','pvp',true);dispatchUnitRulesV3(u,'turnStart',{att:u,target:foe,units});fireHazardsAtV3(u,'round');syncUnitHpV3(u);if(!u.alive)continue;const blocked=u.rt.statuses.some(x=>['stun','frozen','skip'].includes(String(x.key).toLowerCase())&&x.expires>=u.rt.turn),act=blocked?null:chooseTeamActionV3(u,units,moveDist);let text='';if(blocked)text=`${u.side}${u.idx+1} is controlled and cannot act.`;else if(act?.pass){const ox=u.x,oy=u.y;u.x=act.move.x;u.y=act.move.y;if(u.x!==ox||u.y!==oy)fireHazardsAtV3(u,'enter');text=`${u.side}${u.idx+1} moves to ${u.x},${u.y} and passes.`}else if(act){const ox=u.x,oy=u.y;u.x=act.move.x;u.y=act.move.y;if(u.x!==ox||u.y!==oy)fireHazardsAtV3(u,'enter');const before=act.targets.map(t=>t.rt.hp),dmg=executeTeamSkillV3(u,act.targets,act.sk,units);u.rt.ready[act.i]=u.rt.turn+cooldownV11(u.rt,act.sk);act.targets.forEach(syncUnitHpV3);text=`${u.side}${u.idx+1} ${u.name} casts ${act.sk.name} on ${act.targets.map(t=>t.side+(t.idx+1)).join(', ')} · ${fmt(dmg)} damage.`}else text=`${u.side}${u.idx+1} passes.`;endTurnV11(u.rt,foe.rt,'pvp',true);genericCharmTriggerV2(u.rt,foe.rt,'turnEnd','pvp',true);dispatchUnitRulesV3(u,'turnEnd',{att:u,target:foe,units});ageHazardsV3(u);syncUnitHpV3(u);for(const x of units)syncUnitHpV3(x);u.actions++;u.next+=100000/Math.sqrt(Math.max(1,effV11(u.rt,foe.rt).spd)*Math.max(1,rankObj(u.build.rank).speedScale));actions++;if(wantLog)log.push({t:actions,text,units:units.map(x=>({side:x.side,idx:x.idx,x:x.x,y:x.y,hp:x.hp,maxHp:x.maxHp,alive:x.alive,name:x.name})),hazards:activeHazardsV3.map(h=>({x:h.x,y:h.y,turns:h.turns,name:h.name}))})}const hpA=units.filter(x=>x.side==='A').reduce((z,x)=>z+Math.max(0,x.hp),0),hpB=units.filter(x=>x.side==='B').reduce((z,x)=>z+Math.max(0,x.hp),0);return{winner:hpA===hpB?'Draw':hpA>hpB?'A':'B',hpA,hpB,actions,units,log,hazards:activeHazardsV3.map(h=>({x:h.x,y:h.y,turns:h.turns,name:h.name}))}};let result;withSeedV2(seed,()=>{result=run()});return result}
function renderTeamReplayV3(r){lastTeamReplayV3=r;renderTeamBoardV3(r.units,r.hazards||[]);$('teamBattleLog').innerHTML=r.log.slice(-120).map(x=>`<div class="battle-log-row"><span class="t">#${x.t}</span><span>${esc(x.text)}</span></div>`).join('')||'<div class="battle-log-row"><span></span><span>No actions logged.</span></div>'}
function runTeamOnceV3(){const r=simulateTeamOnceV3($('teamSeed').value||'team',true);renderTeamReplayV3(r);$('teamResult').innerHTML=`<div class="v3-kpis"><div class="v3-kpi"><span>Winner</span><strong>Team ${r.winner}</strong></div><div class="v3-kpi"><span>Team A HP</span><strong>${fmt(r.hpA)}</strong></div><div class="v3-kpi"><span>Team B HP</span><strong>${fmt(r.hpB)}</strong></div><div class="v3-kpi"><span>Actions</span><strong>${r.actions}</strong></div></div>`}
function runTeamMonteCarloV3(){const runs=clamp(+$('teamRuns').value||200,1,2000),seed=$('teamSeed').value||'team';let a=0,b=0,d=0,hpa=0,hpb=0;for(let i=0;i<runs;i++){const r=simulateTeamOnceV3(seed+'|'+i,false);if(r.winner==='A')a++;else if(r.winner==='B')b++;else d++;hpa+=r.hpA;hpb+=r.hpB}const eq=a+.5*d,[lo,hi]=wilsonV2(eq,runs);$('teamResult').innerHTML=`<div class="v3-kpis"><div class="v3-kpi"><span>Team A win</span><strong>${(eq/runs*100).toFixed(1)}%</strong><small>95% CI ${(lo*100).toFixed(1)}–${(hi*100).toFixed(1)}%</small></div><div class="v3-kpi"><span>Team B win</span><strong>${((b+.5*d)/runs*100).toFixed(1)}%</strong></div><div class="v3-kpi"><span>Avg A HP</span><strong>${fmt(hpa/runs)}</strong></div><div class="v3-kpi"><span>Avg B HP</span><strong>${fmt(hpb/runs)}</strong></div></div><p class="hint">${fmt(runs)} seeded battles. Draws count as half a win. Exact EC geometry is used where imported; card-text geometry covers the remainder.</p>`;const replay=simulateTeamOnceV3(seed+'|replay',true);renderTeamReplayV3(replay)}

function parseBattleBaseV3(f){const vals={hp:100,atk:100,def:100,spd:100};String(f.battleBase||'').replace(/(HP|ATK|DEF|SPD)\s*(\d+(?:\.\d+)?)%/gi,(_,k,v)=>{vals[k.toLowerCase()]=+v});return vals}
function fantPowerV3(name,obj='Combat rating'){const f=FANTOMON_BY_NAME.get(String(name).toLowerCase());if(!f)return 0;const p=parseBattleBaseV3(f);if(obj==='Team damage')return p.atk*2.5+p.spd*3.125+(f.role==='DPS'?180:0);if(obj==='Survivability')return p.hp*.5+p.def*2.5+(f.role==='Tank'?180:0);if(obj==='Support')return p.spd*3.125+(f.role==='Support'?300:0);return p.atk*2.5+p.hp*.5+p.def*2.5+p.spd*3.125}
function renderFantFormationV3(){ensureV3();const root=$('fantFormation');if(!root)return;root.innerHTML='';for(let i=0;i<4;i++){const name=extras.v3.fantFormation[i]||FANTOMONS[i].name,f=FANTOMON_BY_NAME.get(name.toLowerCase())||FANTOMONS[i],d=document.createElement('div');d.className='fant-slot '+(i===0?'main':'');d.innerHTML=`<div class="fant-factor">${Math.round(TEAM_SLOT_FACTORS_V3[i]*100)}%</div><b>${i===0?'Main Fantomon':`Formation ${i+1}`}</b><select>${fantomonCatalogV5().map(x=>`<option ${x.name===f.name?'selected':''}>${esc(x.name)}</option>`).join('')}</select><p class="hint" style="margin-top:7px">${esc(f.role)} · ${esc(f.support)}<br>${esc(f.battleBase||'No explicit pet_battle scaler in bundled snapshot')}</p>`;d.querySelector('select').onchange=e=>{extras.v3.fantFormation[i]=e.target.value;saveExtras();renderFantFormationV3()};root.appendChild(d)}}
function optimizeFantFormationV3(){ensureV3();const names=[...new Set(extras.v3.fantFormation)].slice(0,4);if(names.length<4){$('fantFormationResult').innerHTML='<div class="v2-warn">Choose four different Fantomons to optimize formation.</div>';return}const obj=$('fantFormationObjective').value,perms=[];function perm(a,l=[]){if(!a.length){perms.push(l);return}a.forEach((x,i)=>perm(a.slice(0,i).concat(a.slice(i+1)),l.concat(x)))}perm(names);const rows=perms.map(p=>({p,score:p.reduce((z,n,i)=>z+fantPowerV3(n,obj)*TEAM_SLOT_FACTORS_V3[i],0)})).sort((a,b)=>b.score-a.score),best=rows[0];extras.v3.fantFormation=best.p;saveExtras();renderFantFormationV3();$('fantFormationResult').innerHTML=`<div class="v2-result best"><h4>Recommended formation · score ${fmt(best.score,1)}</h4>${best.p.map((n,i)=>`<div class="optimizer-dimension"><b>${i===0?'Main':`Slot ${i+1}`} · ${Math.round(TEAM_SLOT_FACTORS_V3[i]*100)}%</b><span>${esc(n)}</span></div>`).join('')}<p class="hint" style="margin-top:8px">Formation score uses the client-exposed slot factors and bundled pet_battle percentages where available. Missing pet battle scalers remain neutral rather than invented.</p></div>`}
function normalizeTreeImportV3(data){let nodes=[];if(Array.isArray(data))nodes=data;else if(Array.isArray(data.nodes))nodes=data.nodes;else if(Array.isArray(data.trees))for(const t of data.trees||[])for(const n of t.nodes||[])nodes.push({...n,role:n.role||t.role,tree:n.tree||t.id});return nodes.map((n,i)=>({id:String(n.id??n.nodeId??`node-${i+1}`),role:n.role||'Any',page:+n.page||1,level:+n.level||1,stat:n.stat||n.prop||'Attack',value:+n.value||0,cost:+n.cost||+n.materialCost||0,requires:Array.isArray(n.requires)?n.requires.map(String):String(n.requires||'').split(',').map(x=>x.trim()).filter(Boolean),percent:!!n.percent||/^System/i.test(n.stat||n.prop||''),owned:!!n.owned})).filter(n=>n.id)}
function renderTreeRowsV3(){ensureV3();const root=$('petTreeRows'),nodes=extras.v3.petTree.nodes||[];if(!root)return;root.innerHTML='<div class="tree-node-row header"><span>Page</span><span>Node / role</span><span>Stat</span><span>Value</span><span>Cost</span><span>Owned</span></div>'+nodes.map((n,i)=>`<div class="tree-node-row" data-i="${i}"><input data-k="page" type="number" value="${n.page}"><span><input data-k="id" value="${esc(n.id)}"><small>${esc(n.role)}</small></span><input data-k="stat" value="${esc(n.stat)}"><input data-k="value" type="number" value="${n.value}"><input data-k="cost" type="number" value="${n.cost}"><label class="check"><input data-k="owned" type="checkbox" ${n.owned?'checked':''}> owned</label></div>`).join('');root.querySelectorAll('.tree-node-row[data-i]').forEach(row=>row.querySelectorAll('input').forEach(inp=>inp.onchange=()=>{const n=extras.v3.petTree.nodes[+row.dataset.i],k=inp.dataset.k;n[k]=k==='owned'?inp.checked:(['page','value','cost'].includes(k)?+inp.value:inp.value);saveExtras()}));$('petTreeStatus').innerHTML=`<b>${esc(extras.v3.petTree.source)}</b> · ${fmt(nodes.length)} nodes loaded.`}
function treeNodePowerV3(n,level){const stat=String(n.stat).toLowerCase(),score=stat.includes('attack')||stat==='atk'?2.5:stat.includes('def')?2.5:stat.includes('speed')||stat==='spd'?3.125:stat.includes('hp')?0.5:stat.includes('crit')||stat.includes('dmg')?2:1;let v=n.value;if(n.percent){const ref=stat.includes('attack')?level*100:stat.includes('def')?level*80:stat.includes('speed')?level*50:level*500;v=ref*n.value/100}return v*score}
function runTreeOptimizerV3(){ensureV3();let budget=Math.max(0,+$('petTreeBudget').value||0),level=Math.max(1,+$('petTreeLevel').value||150),owned=new Set(extras.v3.petTree.nodes.filter(n=>n.owned).map(n=>n.id)),chosen=[],spent=0;for(let guard=0;guard<1000;guard++){const candidates=extras.v3.petTree.nodes.filter(n=>!owned.has(n.id)&&(n.requires||[]).every(r=>owned.has(r))&&n.cost>0).map(n=>({...n,power:treeNodePowerV3(n,level),eff:treeNodePowerV3(n,level)/n.cost})).filter(n=>n.cost<=budget-spent).sort((a,b)=>b.eff-a.eff);if(!candidates.length)break;const n=candidates[0];owned.add(n.id);chosen.push(n);spent+=n.cost}const power=chosen.reduce((z,n)=>z+n.power,0);$('petTreeResult').innerHTML=chosen.length?`<div class="v2-result best"><h4>Recommended spend · ${fmt(spent)} material-equivalent · +${fmt(power,1)} modeled power</h4>${chosen.map((n,i)=>`<div class="optimizer-dimension"><b>#${i+1} · Page ${n.page}</b><span>${esc(n.id)} · ${esc(n.stat)} ${fmt(n.value,2)} · cost ${fmt(n.cost)} · return ${n.eff.toFixed(3)}/mat</span></div>`).join('')}<p class="hint">Prerequisites are honored. Percent-node power is only exact when imported data includes the Fantomon's own base stat; otherwise v3 labels it as a level-scaled estimate.</p></div>`:'<div class="v2-warn">No affordable unlocked nodes. Import exact pet ability rows or add nodes manually.</div>'}

