function quickCharScoreV3(c,obj,s){if(obj==='Survivability')return survivabilityMetrics(c.sheet,s.pvp.enemy).effectiveHp;if(obj==='Support')return supportMetricsV2(c.sheet,{...s,skills:c.skills,charms:c.charms},c.skills,c.fant,c.gear).utility;const p=pveRotation(c.sheet,{...s,skills:c.skills,charms:c.charms},c.skills,c.fant,c.gear).total;if(obj==='Balanced')return Math.sqrt(Math.max(1,p)*Math.max(1,survivabilityMetrics(c.sheet,s.pvp.enemy).effectiveHp));return p}
function topSkillsForCharV3(st,limit=8){const current=(st.skills||[]).filter(x=>x.on),cls=st.build.className,rnk=skillRankNum(current[0]?.skillRank||22),lvl=st.build.level,pool=TECHNIQUES.filter(x=>legalSkillClassV4(x.cls,cls)).map(x=>skillFromName(x.name,rnk,lvl)).filter(Boolean);pool.sort((a,b)=>(b.coef||0)/(1+(b.cd||0))-(a.coef||0)/(1+(a.cd||0)));return[...current,...pool.slice(0,limit)].filter((x,i,a)=>a.findIndex(y=>y.name===x.name)===i)}
function charCandidatesV3(st,obj,cap){const s=collect(),baseFant=mergeFantV2(st.fantomon||baseFantomon()),baseRes=[];if(baseFant?.enabled&&baseFant.name)baseRes.push('fant:'+baseFant.name);let beam=[{sheet:deep(st.build),skills:deep(st.skills||[]),charms:deep(st.charms||[]),fant:baseFant,gear:[],resources:baseRes,score:0}];const scoreAll=a=>{for(const c of a)c.score=quickCharScoreV3(c,obj,s);a.sort((x,y)=>y.score-x.score);return a.slice(0,Math.max(cap,8))};beam=scoreAll(beam);
 if($('accountUseTech').checked){const pool=topSkillsForCharV3(st,7),sets=pool.length>=4?combinations(pool,4,24):[];let next=[];for(const b of beam){next.push(b);for(const skills of sets){const res=b.resources.filter(x=>!x.startsWith('tech:')).concat($('accountEnforceSkillCopies').checked?skills.map(x=>'tech:'+x.name):[]);next.push({...b,skills:deep(skills),resources:res})}}beam=scoreAll(next)}
 if($('accountUseCharm').checked){const cls=st.build.className,load=ownedSkillPoolForClassV7('Charm',cls,st).slice(0,7),sets=load.length>=4?combinations(load,4,18):[];let next=[];for(const b of beam){next.push(b);for(const charms of sets){const res=b.resources.filter(x=>!x.startsWith('charm:')).concat($('accountEnforceSkillCopies').checked?charms.map(x=>'charm:'+x.name):[]);next.push({...b,charms:deep(charms),resources:res})}}beam=scoreAll(next)}
 if($('accountUseFant').checked){let next=[];const pool=ownedFantInventoryPoolV7(st,false);if(pool.length){for(const b of beam)for(const fant of pool){const res=b.resources.filter(x=>!x.startsWith('fant:')).concat('fant:'+fant.name);next.push({...b,fant,resources:res})}beam=scoreAll(next)}}
 if($('accountUseGear').checked&&extras.inventory.length){const by={};for(const it of extras.inventory.filter(x=>ELIGIBILITY_V7.gear(x).ok))(by[it.slot]??=[]).push(it);const bundles=[[]];for(let rank=0;rank<3;rank++){const bun=[];for(const slot of Object.keys(by)){const its=by[slot].slice().sort((a,b)=>itemMarginalV3(b,st.build,obj)-itemMarginalV3(a,st.build,obj));if(its[rank])bun.push(its[rank])}if(bun.length)bundles.push(bun)}let next=[];for(const b of beam)for(const gear of bundles){const sh=deep(b.sheet);for(const it of gear)applyStats(sh,it.stats,1);const res=b.resources.filter(x=>!x.startsWith('gear:')).concat(gear.map(x=>'gear:'+x.id));next.push({...b,sheet:sh,gear,resources:res})}beam=scoreAll(next)}return scoreAll(beam).slice(0,cap)}
function itemMarginalV3(it,b,obj){let z=0;for(const [k,v] of it.stats||[]){const w=obj==='Survivability'?({hp:1,def:2,spd:.2,dmgres:10000,critres:10000}[k]||.05):obj==='Support'?({spd:2,hp:.2,atk:.5,mast:.4}[k]||.1):({atk:2,spd:1.4,mast:1.2,kfm:1.2,cr:5000,cd:2500,boost:4000,hp:.05,def:.05}[k]||.1);z+=(+v||0)*w}return z}
function resourcesConflictV3(used,res){return res.some(x=>used.has(x))}
function teamQuickScoreV3(chars,obj){return chars.reduce((z,c)=>z+c.score,0)}
function accountTeamPvpScoreV3(chars,runs,seed){const backupA=deep(extras.v3.team.A),backupPos=deep(extras.v3.team.pos.A),tempProfiles=[];for(let i=0;i<4;i++){const st={...deep(collect()),build:chars[i].sheet,skills:chars[i].skills,charms:chars[i].charms,fantomon:chars[i].fant,_v3Gear:chars[i].gear};tempProfiles.push({id:'tmp',name:'Optimized '+(i+1),state:st});extras.profiles.push(tempProfiles[i]);extras.v3.team.A[i]=`profile:${extras.profiles.length-1}`}let win=0,draw=0;for(let i=0;i<runs;i++){const r=simulateTeamOnceV3(seed+'|acc|'+i,false);if(r.winner==='A')win++;else if(r.winner==='Draw')draw++}extras.profiles.splice(extras.profiles.length-4,4);extras.v3.team.A=backupA;extras.v3.team.pos.A=backupPos;return(win+.5*draw)/runs}
function runAccountOptimizerV3(){ensureV3();const obj=$('accountObjective').value,beamW=clamp(+$('accountBeam').value||30,5,100),cap=clamp(+$('accountCandidateCap').value||12,3,40),status=$('accountSearchStatus'),sources=extras.v3.account.sources.map(sourceStateV3),cands=sources.map(x=>charCandidatesV3(x.state,obj==='Team PvP win rate'?'Team PvE damage':obj,cap));status.textContent=`Candidate pools: ${cands.map(x=>x.length).join(' × ')}. Applying one-copy constraints…`;let beam=[{chars:[],used:new Set(),score:0}];for(let i=0;i<4;i++){const next=[];for(const b of beam)for(const c of cands[i]){if(resourcesConflictV3(b.used,c.resources||[]))continue;const used=new Set(b.used);(c.resources||[]).forEach(x=>used.add(x));const chars=b.chars.concat(c),score=teamQuickScoreV3(chars,obj);next.push({chars,used,score})}next.sort((a,b)=>b.score-a.score);beam=next.slice(0,beamW);if(!beam.length)break}if(!beam.length){$('accountResult').innerHTML='<div class="v2-warn">No legal assignment survived the one-copy constraints. Add duplicate inventory rows for extra copies or disable one-copy Technique/Charm enforcement.</div>';return}if(obj==='Team PvP win rate'){const runs=clamp(+$('accountPvpRuns').value||120,20,1000),seed=$('teamSeed')?.value||'account-v3';for(const b of beam.slice(0,Math.min(5,beam.length)))b.pvp=accountTeamPvpScoreV3(b.chars,runs,seed+'|'+b.chars.map(c=>c.fant?.name||'').join('|'));beam.slice(0,5).sort((a,b)=>(b.pvp||0)-(a.pvp||0));beam=beam.slice(0,5).sort((a,b)=>(b.pvp||0)-(a.pvp||0))}lastAccountResultsV3=beam.slice(0,3);status.textContent=`Beam search retained ${beam.length} legal team assignments. ${obj==='Team PvP win rate'?'Top finalists were re-run through the 4v4 grid simulator.':'Scores use the shared combat model.'}`;$('accountResult').innerHTML=lastAccountResultsV3.map((b,bi)=>`<div class="v2-result ${bi===0?'best':''}"><h4>${bi===0?'Recommended account team':'Alternative '+(bi+1)} · ${obj==='Team PvP win rate'?((b.pvp||0)*100).toFixed(1)+'%':fmt(b.score)}</h4><div class="table-wrap"><table class="allocation-table"><thead><tr><th>Character</th><th>Techniques</th><th>Charms</th><th>Fantomon</th><th>Allocated gear</th></tr></thead><tbody>${b.chars.map((c,i)=>`<tr><td><b>${esc(sources[i].name)}</b><br><small>ATK ${fmt(c.sheet.atk)} · SPD ${fmt(c.sheet.spd)}</small></td><td>${c.skills.filter(x=>x.on).map(x=>esc(x.name)).join('<br>')}</td><td>${c.charms.filter(x=>x.name).map(x=>esc(x.name)).join('<br>')||'—'}</td><td>${esc(c.fant?.name||'None')}</td><td>${c.gear.map(x=>esc(x.name)).join('<br>')||'baseline'}</td></tr>`).join('')}</tbody></table></div><p class="hint">Shared resources used: ${b.used.size}. Gear item IDs and Fantomon names cannot be assigned twice. Gear-added sheets are DERIVED unless your saved profile is gear-stripped.</p></div>`).join('')}

