const UPGRADE_ANCHORS_V4=[[0,0],[1,.05],[5,.30],[10,.60],[20,.96],[30,1.32],[50,1.92],[100,3.12],[150,4.32],[200,5.52],[250,6.72]];
const SEASON_ANCHORS_V4=[[0,0],[1,.369],[5,.636],[10,.795],[20,1.161],[30,1.640],[50,2.985],[100,10.720]];
