function ensureV4(){
 extras.v4=extras.v4||{};
 const v=extras.v4;
 v.food=v.food||{mode:'Terrain Quest',battleDish:'',applyBattle:true,sheetIncludesPermanent:true,history:[]};
 v.food.catalog=Array.isArray(v.food.catalog)&&v.food.catalog.length?v.food.catalog:deep(FOOD_SEED_V4);
 v.enhance=v.enhance||{upgrade:[],season:[],source:'Bundled anchor factors; per-step resource rows not bundled'};
 v.farm=v.farm||{dropRates:{},rollWeights:{},source:'source rows required'};
 if(v.strictLegality==null)v.strictLegality=true;
 return v;
}
function classLineageV4(cls){const out=[];let c=cls,guard=0;while(c&&guard++<20){out.push(c);c=CLASS_PARENT_V4[c]||null}return out}
function strictLegalityV4(){try{return ensureV4().strictLegality!==false}catch(e){return true}}
function legalSkillClassV4(owner,current){if(!strictLegalityV4())return true;return classLineageV4(current).includes(owner)}
function skillOptions(kind,scope,index){const arr=kind==='Charm'?CHARMS:TECHNIQUES;let cls='';if(scope==='mine')cls=$('myClass')?.value||'';else if(scope==='pvpEnemy')cls=$('pvpEnemyClass')?.value||'';const filtered=strictLegalityV4()&&cls?arr.filter(s=>legalSkillClassV4(s.cls,cls)):arr;return filtered.map(s=>({label:s.name,value:s.name,sub:`${s.cls}${s.element?` · ${s.element}`:''} · #${s.id}`,score:s.cls===cls?0:classLineageV4(cls).includes(s.cls)?1:2})).sort((a,b)=>a.score-b.score||a.label.localeCompare(b.label));}
function techPoolV2(s){let names=$('techPool')?.value.split(/\n+/).map(x=>x.trim()).filter(Boolean)||[];if(!names.length)names=TECHNIQUES.filter(x=>legalSkillClassV4(x.cls,s.build.className)).slice(0,12).map(x=>x.name);const rnk=skillRankNum(s.skills.find(x=>x.on)?.skillRank||22),lvl=s.skills.find(x=>x.on)?.skillLevel||s.build.level;return names.map(n=>skillFromName(n,rnk,lvl)).filter(x=>x&&legalSkillClassV4(SKILL_BY_NAME.get(x.name.toLowerCase())?.cls||'',s.build.className));}
function charmPoolV2(s){let names=$('charmPool')?.value.split(/\n+/).map(x=>x.trim()).filter(Boolean)||[];if(!names.length)names=CHARMS.filter(x=>legalSkillClassV4(x.cls,s.build.className)).slice(0,8).map(x=>x.name);return names.map(n=>{const sk=SKILL_BY_NAME.get(n.toLowerCase());return sk&&legalSkillClassV4(sk.cls,s.build.className)?{name:sk.name,id:sk.id,skillRank:s.charms.find(c=>c.name)?.skillRank||'22',skillLevel:s.build.level}:null}).filter(Boolean);}
function topSkillsForCharV3(st,limit=8){const current=(st.skills||[]).filter(x=>x.on&&legalSkillClassV4(SKILL_BY_NAME.get(x.name.toLowerCase())?.cls||st.build.className,st.build.className)),cls=st.build.className,rnk=skillRankNum(current[0]?.skillRank||22),lvl=st.build.level,pool=TECHNIQUES.filter(x=>legalSkillClassV4(x.cls,cls)).map(x=>skillFromName(x.name,rnk,lvl)).filter(Boolean);pool.sort((a,b)=>(b.coef||0)/(1+(b.cd||0))-(a.coef||0)/(1+(a.cd||0)));return[...current,...pool.slice(0,limit)].filter((x,i,a)=>a.findIndex(y=>y.name===x.name)===i)}

function foodCatalogV4(){return ensureV4().food.catalog||[]}
function foodByNameV4(name){return foodCatalogV4().find(x=>x.name.toLowerCase()===String(name||'').trim().toLowerCase())}
function foodEfficiencyMealsV4(n){n=Math.max(0,Math.floor(+n||0));return Math.min(n,10)+Math.max(0,Math.min(n,30)-10)*.5+Math.max(0,Math.min(n,50)-30)*.2+Math.max(0,n-50)*.05}
function foodPermanentV4(dish){const m=String(dish?.permanent||'').match(/\+([\d.]+)%\s+(ATK|DEF|SPD|HP)\s+per meal/i);return m?{pct:+m[1],stat:m[2].toUpperCase()}:null}
function foodScopesV4(effect){const t=String(effect||'');return FOOD_MODES_V4.filter(x=>t.toLowerCase().includes(x.toLowerCase()))}
function foodEffectsV4(effect){const out=[],re=/(Healing Boost|Block Rate|Crit Rate|Crit DMG|DMG Boost|DMG RES|Accuracy|Block|Crit|ATK|DEF|SPD|HP)\s*\+([\d.]+)%/gi;let m;while((m=re.exec(String(effect||''))))out.push({stat:m[1],pct:+m[2]});return out}
function applyPctStatV4(b,stat,pct){const q=pct/100,s=stat.toLowerCase();if(s==='atk')b.atk*=1+q;else if(s==='def')b.def*=1+q;else if(s==='spd')b.spd*=1+q;else if(s==='hp')b.hp*=1+q;else if(s==='crit'||s==='crit rate')b.cr=(b.cr||0)+pct;else if(s==='crit dmg')b.cd=(b.cd||0)+pct;else if(s==='dmg boost')b.boost=(b.boost||0)+pct;else if(s==='dmg res')b.dmgres=(b.dmgres||0)+pct;else if(s==='block'||s==='block rate')b.blockrate=(b.blockrate||0)+pct;else if(s==='accuracy')b.acc=(b.acc||0)*(1+q);else if(s==='healing boost')b._healingBoostV4=(b._healingBoostV4||0)+pct;}
function foodAdjustedBuildV4(build,mode){const v=ensureV4().food,b=deep(build);if(!v.sheetIncludesPermanent){for(const h of v.history||[]){const d=foodByNameV4(h.name),p=foodPermanentV4(d);if(p)applyPctStatV4(b,p.stat,p.pct*foodEfficiencyMealsV4(h.meals))}}if(v.applyBattle&&v.battleDish){const d=foodByNameV4(v.battleDish),sc=foodScopesV4(d?.effect);if(d&&sc.includes(mode))for(const fx of foodEffectsV4(d.effect))applyPctStatV4(b,fx.stat,fx.pct)}b.atk=Math.max(1,b.atk);b.def=Math.max(0,b.def);b.spd=Math.max(1,b.spd);b.hp=Math.max(1,b.hp);return applyRelicSheetV5(b)}
function pveRotation(sheet,s,skills=s.skills,fantomon=effectivePveFantomon(),items=[]){const mode=ensureV4().food.mode||'Terrain Quest';return pveRotationRawV4(foodAdjustedBuildV4(sheet,mode),s,skills,fantomon,items)}
function quickWinRate(A,B,LA,LB,CA,CB,FA,FB,runs=120){let w=0;A=foodAdjustedBuildV4(A,'Arena');for(let i=0;i<runs;i++){const x=oneDuelV1(A,B,LA.filter(x=>x.on),LB.filter(x=>x.on),CA,CB,FA,FB,80);if(x.result>0)w++;else if(x.result===0)w+=.5}return w/runs}
function fullPvpRateV2(c,s,runs,seed){let w=0,d=0,A=foodAdjustedBuildV4(c.sheet,'Arena');withSeedV2(seed,()=>{for(let i=0;i<runs;i++){const x=oneDuelLoadoutV2(A,s.pvp.enemy,c.skills,s.pvp.skills,c.charms,s.pvp.charms,c.fant,s.pvp.enemyFantomon,c.gear,[],s.pvp.actionCap);if(x.result>0)w++;else if(x.result===0)d++}});return(w+.5*d)/runs}
function parseCookbookV4(text){const doc=new DOMParser().parseFromString(text,'text/html'),out=[];doc.querySelectorAll('article.dish').forEach(a=>{const id=+(a.id||'').replace(/\D/g,''),h=a.querySelector('h3');if(!h)return;const clone=h.cloneNode(true);clone.querySelectorAll('span').forEach(x=>x.remove());const name=clone.textContent.trim();const dts=[...a.querySelectorAll('dt')],get=k=>{const x=dts.find(dt=>dt.textContent.trim()===k);return x?.nextElementSibling?.textContent.trim()||''};out.push({id,name,effect:get('Effect'),permanent:get('Permanent'),how:get('How'),source:'cookbook.html'})});return out.filter(x=>x.name)}
