function anchorFactorV4(level,anchors){level=Math.max(0,+level||0);const exact=anchors.find(x=>x[0]===level);if(exact)return{factor:exact[1],coverage:'EXACT',source:'published factor row'};let lo=anchors[0],hi=anchors[anchors.length-1];for(let i=1;i<anchors.length;i++)if(level<anchors[i][0]){lo=anchors[i-1];hi=anchors[i];break}if(level>=anchors[anchors.length-1][0])lo=hi=anchors[anchors.length-1];const factor=lo[0]===hi[0]?lo[1]:lo[1]+(hi[1]-lo[1])*(level-lo[0])/(hi[0]-lo[0]);return{factor,coverage:'DERIVED',source:`linear interpolation ${lo[0]}–${hi[0]}`}}
function factorForV4(type,level){const rows=(ensureV4().enhance[type]||[]).filter(x=>Number.isFinite(+x.level)&&Number.isFinite(+x.factor));const exact=rows.find(x=>+x.level===+level);if(exact)return{factor:+exact.factor,coverage:'EXACT',source:exact.source||'imported per-step table'};return anchorFactorV4(level,type==='upgrade'?UPGRADE_ANCHORS_V4:SEASON_ANCHORS_V4)}
function parsePlannerRowsV4(text,name='import'){text=String(text||'').trim();if(!text)return{upgrade:[],season:[]};if(text[0]==='{'){const j=JSON.parse(text),norm=(arr,type)=>(arr||[]).map(x=>({type,level:+x.level,factor:x.factor==null?NaN:+x.factor,cost:x.cost||{},material:x.material,amount:+x.amount||0,source:name}));return{upgrade:norm(j.upgrade,'upgrade'),season:norm(j.season,'season')}}const lines=text.split(/\r?\n/).filter(x=>x.trim()),start=/type/i.test(lines[0])?1:0,out={upgrade:[],season:[]};for(const ln of lines.slice(start)){const [type0,level0,factor0,material='',amount0='']=ln.split(',').map(x=>x.trim()),type=type0.toLowerCase().startsWith('s')?'season':'upgrade';out[type].push({type,level:+level0,factor:factor0===''?NaN:+factor0,material,amount:+amount0||0,source:name})}return out}
function installPlannerRowsV4(parsed){const e=ensureV4().enhance;for(const type of ['upgrade','season'])for(const row of parsed[type]||[]){const i=e[type].findIndex(x=>+x.level===+row.level&&((x.material||'')===(row.material||'')));if(i>=0)e[type][i]=row;else e[type].push(row)}e.source='Imported per-step factor/resource table';saveExtras();renderEnhV4()}
function costsBetweenV4(type,a,b){const e=ensureV4().enhance,rows=e[type]||[],cost={},missing=[];if(b<=a)return{cost,missing,exact:true};for(let lv=Math.floor(a)+1;lv<=Math.floor(b);lv++){const rr=rows.filter(x=>+x.level===lv&&(x.material||x.cost));if(!rr.length){missing.push(lv);continue}for(const r of rr){if(r.cost&&typeof r.cost==='object')for(const [m,v] of Object.entries(r.cost))cost[m]=(cost[m]||0)+(+v||0);if(r.material)cost[r.material]=(cost[r.material]||0)+(+r.amount||0)}}return{cost,missing,exact:missing.length===0}}
function enhancementValueV4(g,up,season,promotion=true){const q=QUALITY_FACTOR_V4[g.quality]??0,u=factorForV4('upgrade',up),b=factorForV4('season',season),catalog=+g.main?.value||0,raw=catalog/Math.max(.0001,1+q),value=raw*(1+u.factor)*(1+q)+(promotion?raw*b.factor:0),coverage=(u.coverage==='EXACT'&&(!promotion||b.coverage==='EXACT'))?'EXACT':'DERIVED';return{value:Math.round(value),raw,q,u,b,coverage}}
function selectedGearV4(id){return runtimeGear.find(x=>x.name.toLowerCase()===String($(id)?.value||'').trim().toLowerCase())}
function renderEnhV4(){const g=selectedGearV4('enhV4Gear');if(!g){$('enhV4Result').innerHTML='<p class="muted">Choose a catalog gear piece.</p>';return}const a=Math.max(0,+$('enhV4Current').value||0),z=Math.max(0,+$('enhV4Target').value||0),sa=Math.max(0,+$('enhV4SeasonCurrent').value||0),sz=Math.max(0,+$('enhV4SeasonTarget').value||0),pm=$('enhV4PromotionMatch').checked,cur=enhancementValueV4(g,a,sa,pm),tar=enhancementValueV4(g,z,sz,pm),uc=costsBetweenV4('upgrade',a,z),sc=costsBetweenV4('season',sa,sz),cost={...uc.cost};for(const [k,v] of Object.entries(sc.cost))cost[k]=(cost[k]||0)+v;const missing=[...uc.missing.map(x=>'Upgrade +'+x),...sc.missing.map(x=>'Season '+x)],exact=tar.coverage==='EXACT'&&cur.coverage==='EXACT'&&missing.length===0;lastEnhV4={g,target:tar.value,up:z,season:sz};$('enhV4Coverage').textContent=exact?'EXACT':'PARTIAL / DERIVED';$('enhV4Coverage').className='v4-badge '+(exact?'exact':missing.length?'partial':'derived');$('enhV4Result').innerHTML=`<div class="v4-prob-grid"><div><span>Current main stat</span><strong>${fmt(cur.value)}</strong><small>${cur.coverage} factors</small></div><div><span>Target main stat</span><strong>${fmt(tar.value)}</strong><small>${tar.coverage} factors</small></div><div><span>Gain</span><strong class="positive">+${fmt(tar.value-cur.value)}</strong><small>${pct(deltaPct(cur.value,tar.value))}</small></div></div><p class="hint">Quality ${esc(g.quality)} factor +${(cur.q*100).toFixed(0)}%. Target upgrade factor +${(tar.u.factor*100).toFixed(2)}% (${tar.u.coverage.toLowerCase()}); target Season factor +${(tar.b.factor*100).toFixed(2)}% (${tar.b.coverage.toLowerCase()}). Season contribution is added from the raw curve only when promotion matches.</p><h4>Resources ${missing.length?'· PARTIAL':'· EXACT IMPORT COVERAGE'}</h4>${Object.keys(cost).length?`<div class="v4-resource-list">${Object.entries(cost).map(([m,v])=>`<span><b>${esc(m)}</b> ${fmt(v)}</span>`).join('')}</div>`:'<p class="muted">No per-step resource rows loaded.</p>'}${missing.length?`<p class="hint negative">Missing resource rows: ${esc(missing.slice(0,30).join(', '))}${missing.length>30?'…':''}. Missing costs are not interpolated.</p>`:''}`}

function renderLegalityV4(){const v=ensureV4(),cls=$('myClass').value,line=classLineageV4(cls).reverse();$('classLineageV4').innerHTML=line.map((x,i)=>`${i?'<span class="arrow">→</span>':''}<span>${esc(x)} · T${CLASS_TIER_V4[x]||'?'}</span>`).join('');const s=collect(),rows=[...s.skills.filter(x=>x.on).map(x=>({kind:'Technique',name:x.name})),...s.charms.filter(x=>x.name).map(x=>({kind:'Charm',name:x.name}))].map(x=>{const sk=SKILL_BY_NAME.get(x.name.toLowerCase()),owner=sk?.cls||'Unknown',ok=!!sk&&classLineageV4(cls).includes(owner);return{...x,owner,ok}});$('legalityV4Result').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Type</th><th>Selected</th><th>Owning class</th><th>Legal</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.kind}</td><td>${esc(r.name)}</td><td>${esc(r.owner)}</td><td class="${r.ok?'legality-ok':'legality-bad'}">${r.ok?'YES':'NO'}</td></tr>`).join('')||'<tr><td colspan="4">No skills selected.</td></tr>'}</tbody></table></div>${rows.some(x=>!x.ok)?'<p class="v4-callout negative">One or more selected skills are outside this class promotion lineage. With strict legality enabled, optimizers and dropdown suggestions exclude them.</p>':''}`}

function parseFarmRowsV4(text,name='import'){text=String(text||'').trim();if(!text)return{dropRates:{},rollWeights:{}};if(text[0]==='{'){const j=JSON.parse(text);return{dropRates:j.dropRates||{},rollWeights:j.rollWeights||{},source:name}}const lines=text.split(/\r?\n/).filter(x=>x.trim()),start=/gear/i.test(lines[0])?1:0,out={dropRates:{},rollWeights:{},source:name};for(const ln of lines.slice(start)){const [gear,drop,sec,roll]=ln.split(',').map(x=>x.trim());if(gear&&drop!=='')out.dropRates[gear]=+drop;if(gear&&sec&&roll!==''){out.rollWeights[gear]=out.rollWeights[gear]||{};out.rollWeights[gear][sec]=+roll}}return out}
function installFarmRowsV4(x){const f=ensureV4().farm;Object.assign(f.dropRates,x.dropRates||{});for(const [g,w] of Object.entries(x.rollWeights||{}))f.rollWeights[g]={...(f.rollWeights[g]||{}),...w};f.source=x.source||'imported';saveExtras();renderFarmV4()}
function probabilityRunsV4(p,target){if(p<=0)return Infinity;if(p>=1)return 1;return Math.ceil(Math.log(1-target)/Math.log(1-p))}
function renderFarmV4(){const g=selectedGearV4('farmGearV4');if(!g){$('farmResultV4').innerHTML='<p class="muted">Choose a gear piece.</p>';return}const sec=$('farmSecondaryV4').value||g.secondaries?.[0]?.label||'',f=ensureV4().farm,manualDrop=$('farmDropV4').value.trim(),manualRoll=$('farmRollV4').value.trim(),importDrop=f.dropRates[g.name],importRoll=f.rollWeights[g.name]?.[sec];let drop,dropSource;if(manualDrop!==''){const entered=+manualDrop/100;drop=entered;dropSource=(importDrop!=null&&Math.abs(entered-(+importDrop))<1e-10)?'IMPORTED':'MANUAL'}else if(importDrop!=null){drop=+importDrop;dropSource='IMPORTED'}else{drop=0;dropSource='MISSING'}let roll,rollSource;if(manualRoll!==''){const entered=+manualRoll/100;roll=entered;rollSource=(importRoll!=null&&Math.abs(entered-(+importRoll))<1e-10)?'IMPORTED':'MANUAL'}else if(importRoll!=null){roll=+importRoll;rollSource='IMPORTED'}else{roll=1/Math.max(1,(g.secondaries||[]).length);rollSource='DERIVED UNIFORM'}drop=clamp(drop,0,1);roll=clamp(roll,0,1);const p=drop*roll,runs=Math.max(1,+$('farmRunsV4').value||100),expected=p>0?1/p:Infinity,n50=probabilityRunsV4(p,.5),n90=probabilityRunsV4(p,.9),n95=probabilityRunsV4(p,.95),within=1-Math.pow(1-p,runs),mins=Math.max(0,+$('farmMinutesV4').value||0),rr=Math.max(0,+$('farmRerollCostV4').value||0),rerolls=roll>0?1/roll:Infinity,rrCost=rerolls*rr,coverage=(dropSource==='IMPORTED'&&rollSource==='IMPORTED')?'EXACT IMPORT':(dropSource==='MISSING'?'PARTIAL':'DERIVED / MANUAL');$('farmCoverageV4').textContent=coverage;$('farmCoverageV4').className='v4-badge '+(coverage==='EXACT IMPORT'?'exact':coverage==='PARTIAL'?'partial':'derived');$('farmResultV4').innerHTML=`<div class="v4-prob-grid"><div><span>Chance / run</span><strong>${(p*100).toFixed(3)}%</strong><small>drop ${(drop*100).toFixed(3)}% × roll ${(roll*100).toFixed(3)}%</small></div><div><span>Expected runs</span><strong>${Number.isFinite(expected)?fmt(expected,1):'—'}</strong><small>${Number.isFinite(expected)&&mins?`${fmt(expected*mins/60,1)} expected hours`:''}</small></div><div><span>Chance within ${fmt(runs)} runs</span><strong>${(within*100).toFixed(1)}%</strong></div><div><span>50% target</span><strong>${Number.isFinite(n50)?fmt(n50):'—'} runs</strong></div><div><span>90% target</span><strong>${Number.isFinite(n90)?fmt(n90):'—'} runs</strong></div><div><span>95% target</span><strong>${Number.isFinite(n95)?fmt(n95):'—'} runs</strong></div></div><p class="hint">Drop rate: ${dropSource}. Secondary roll: ${rollSource}. ${rollSource==='DERIVED UNIFORM'?`${(g.secondaries||[]).length} legal secondaries → equal-weight assumption only; import real roll weights when available.`:''}</p><div class="v4-callout"><b>Reroll expectation:</b> ${Number.isFinite(rerolls)?fmt(rerolls,2):'—'} attempts for the desired roll · ${Number.isFinite(rrCost)?fmt(rrCost,2):'—'} ${esc($('farmResourceV4').value||'resource')} expected at the entered cost.</div>`}

function refreshV4Combos(){attachCombo($('foodMode'),FOOD_MODES_V4,()=>{ensureV4().food.mode=$('foodMode').value;saveExtras();renderFoodSheetV4();recalc()});attachCombo($('foodBattleDish'),()=>foodCatalogV4().map(x=>({label:x.name,sub:[foodScopesV4(x.effect).join(' / '),x.effect].filter(Boolean).join(' · '),dish:x})),o=>{ensureV4().food.battleDish=o.label;saveExtras();renderFoodV4();recalc()});attachCombo($('foodHistoryDish'),()=>foodCatalogV4().filter(x=>foodPermanentV4(x)).map(x=>({label:x.name,sub:x.permanent,dish:x})));attachCombo($('enhV4Gear'),gearOptions,o=>{const g=o.gear||GEAR_BY_NAME.get(o.label.toLowerCase());if(g){$('enhV4Gear').value=g.name;renderEnhV4()}});attachCombo($('farmGearV4'),gearOptions,o=>{const g=o.gear||GEAR_BY_NAME.get(o.label.toLowerCase());if(g){$('farmGearV4').value=g.name;$('farmSecondaryV4').value=g.secondaries?.[0]?.label||'';const dr=ensureV4().farm.dropRates[g.name];if(dr!=null)$('farmDropV4').value=(dr*100).toString();renderFarmV4()}});attachCombo($('farmSecondaryV4'),()=>{const g=selectedGearV4('farmGearV4');return(g?.secondaries||[]).map(x=>({label:x.label,sub:fmt(x.value)}))},()=>renderFarmV4())}
function initV4(){ensureV4();const f=extras.v4.food;$('strictSkillLegality').checked=extras.v4.strictLegality!==false;refreshV4Combos();renderFoodV4();renderLegalityV4();if(!$('enhV4Gear').value&&runtimeGear[0])$('enhV4Gear').value=runtimeGear[0].name;renderEnhV4();$('foodMode').onchange=()=>{f.mode=$('foodMode').value;saveExtras();renderFoodSheetV4();recalc()};$('foodBattleDish').onchange=()=>{f.battleDish=$('foodBattleDish').value;saveExtras();renderFoodV4();recalc()};$('foodApplyBattle').onchange=()=>{f.applyBattle=$('foodApplyBattle').checked;saveExtras();renderFoodV4();recalc()};$('foodSheetIncludesPermanent').onchange=()=>{f.sheetIncludesPermanent=$('foodSheetIncludesPermanent').checked;saveExtras();renderFoodV4();recalc()};$('clearBattleFoodBtn').onclick=()=>{$('foodBattleDish').value='';f.battleDish='';saveExtras();renderFoodV4();recalc()};$('addFoodHistoryBtn').onclick=()=>{const name=$('foodHistoryDish').value.trim(),meals=Math.max(0,Math.floor(+$('foodHistoryMeals').value||0)),d=foodByNameV4(name);if(!d||!foodPermanentV4(d)){toast('Choose a dish with a permanent bonus');return}const old=f.history.find(x=>x.name===d.name);if(old)old.meals=meals;else f.history.push({name:d.name,meals});saveExtras();renderFoodV4();recalc()};$('foodCookbookImport').onchange=async e=>{try{if(e.target.files[0])await importCookbookV4(e.target.files[0])}catch(err){toast('Could not parse cookbook.html')}};$('runEnhV4Btn').onclick=renderEnhV4;$('addEnhV4InventoryBtn').onclick=()=>{if(!lastEnhV4)return;const g=lastEnhV4.g,sec=(g.secondaries||[])[0];addInventoryItem({name:`${g.name} +${lastEnhV4.up}${lastEnhV4.season?` · S${lastEnhV4.season}`:''}`,slot:canonicalSlot(g),secondary:sec?.label||'',set:(g.sets||[])[0]||'',stats:[[g.main.key,lastEnhV4.target],...(sec?[[sec.key,sec.value]]:[])],source:`v5 enhancement planner · ${enhancementValueV4(g,lastEnhV4.up,lastEnhV4.season,$('enhV4PromotionMatch').checked).coverage}`})};$('enhV4Import').onchange=async e=>{try{const file=e.target.files[0];if(file)installPlannerRowsV4(parsePlannerRowsV4(await file.text(),file.name))}catch(err){toast('Could not parse enhancement table')}};$('enhV4LoadPaste').onclick=()=>{try{installPlannerRowsV4(parsePlannerRowsV4($('enhV4Paste').value,'pasted table'));toast('Enhancement rows loaded')}catch(e){toast('Could not parse pasted table')}};['enhV4Current','enhV4Target','enhV4SeasonCurrent','enhV4SeasonTarget','enhV4PromotionMatch'].forEach(id=>$(id).onchange=renderEnhV4);$('strictSkillLegality').onchange=()=>{extras.v4.strictLegality=$('strictSkillLegality').checked;saveExtras();renderLegalityV4();combos.forEach(c=>{try{c.filter()}catch(e){}})};$('myClass').addEventListener('change',()=>setTimeout(renderLegalityV4,0));document.body.addEventListener('input',e=>{if(e.target.closest('#tab-build'))setTimeout(()=>{renderFoodSheetV4();renderLegalityV4()},0)});setTimeout(()=>{renderFoodV4();renderLegalityV4();renderEnhV4()},80)}


