const RELIC_JSON_URL_V5='https://lootandwaifus.com/api/swordxstaff/treasures.json';
function ensureV5(){
 const v=ensureV5BaseV53();
 if(!RELIC_SETS_V51.length)rebuildRelicSetModelV53();
 const seed=relicSeedStateV51();v.relicSets=v.relicSets&&typeof v.relicSets==='object'?v.relicSets:{};
 for(const [name,d] of Object.entries(seed))if(!v.relicSets[name])v.relicSets[name]=deep(d);
 if(!v.relicSetsMigratedV51){for(const old of extras.relicInventory||[])if(RELIC_NAMES_V51.has(old.name)){const r=v.relicSets[old.name];if(old.use!==false)r.owned=true;if(old.displayed)r.equipped=true;if((old.contribution||[]).length===1&&!r.effect){const [k,val]=old.contribution[0],stat=relicStatLabelFromKeyV51(k);if(stat)r.effect={stat,value:+val||0,unit:'flat'}}}v.relicSetsMigratedV51=true}
 return v;
}
function fantomonCatalogV5(){ensureV5();const usable=extras.fantInventory.filter(x=>x.use!==false&&x.name).map(x=>FANTOMON_BY_NAME.get(x.name.toLowerCase())).filter(Boolean);return usable.length?[...new Map(usable.map(x=>[x.name,x])).values()]:FANTOMONS}
