function runBatchPvpV2(){const s=collect(),runs=clamp(num('batchPvpRuns')||300,50,5000),seed=$('pvpSeed')?.value||'SXS-v2',targets=[{name:'Current PvP opponent',build:deep(s.pvp.enemy),skills:deep(s.pvp.skills),charms:deep(s.pvp.charms),fant:deep(s.pvp.enemyFantomon)}];for(const p of runtimeNpcs.filter(x=>x.kind==='PvP'))targets.push({name:p.name,build:{...s.pvp.enemy,...p},skills:s.pvp.skills,charms:s.pvp.charms,fant:s.pvp.enemyFantomon});if($('batchIncludeProfiles').checked)for(const p of extras.profiles){const st=p.state||{};if(st.build)targets.push({name:'Profile: '+p.name,build:st.build,skills:st.skills||s.pvp.skills,charms:st.charms||[],fant:st.fantomon||baseFantomon()})}const c={sheet:relicEffectiveBuildV51(s.build),gear:equippedGearV59(),skills:s.skills,charms:s.charms,fant:s.fantomon},rows=targets.slice(0,30).map(t=>{let w=0,d=0;withSeedV2(seed+'|batch|'+t.name,()=>{for(let i=0;i<runs;i++){const x=oneDuelLoadoutV2(c.sheet,t.build,c.skills,t.skills,c.charms,t.charms,c.fant,t.fant,c.gear,[],s.pvp.actionCap);if(x.result>0)w++;else if(x.result===0)d++}});const rate=(w+.5*d)/runs,[lo,hi]=wilsonV2(w+.5*d,runs);return{name:t.name,rate,lo,hi}}).sort((a,b)=>b.rate-a.rate);$('batchPvpResult').innerHTML='<div class="table-wrap"><table><thead><tr><th>Opponent</th><th>Win chance</th><th>95% CI</th></tr></thead><tbody>'+rows.map(r=>`<tr><td>${esc(r.name)}</td><td><b>${(r.rate*100).toFixed(1)}%</b></td><td>${(r.lo*100).toFixed(1)}–${(r.hi*100).toFixed(1)}%</td></tr>`).join('')+'</tbody></table></div>'}
