  'atk':'ATK','attack':'ATK','hp':'HP','health':'HP','def':'DEF','defense':'DEF','defence':'DEF','spd':'SPD','speed':'SPD',
  'elemental mastery':'Elemental Mastery','element mastery':'Elemental Mastery','physical mastery':'Physical Mastery',
  'elemental res':'Elemental RES','elemental resistance':'Elemental RES','physical res':'Physical RES','physical resistance':'Physical RES',
  'crit rate':'Crit Rate','critical rate':'Crit Rate','crit dmg':'Crit DMG','critical damage':'Crit DMG','crit res':'Crit RES','critical resistance':'Crit RES',
  'dmg boost':'DMG Boost','damage boost':'DMG Boost','dmg res':'DMG RES','damage res':'DMG RES','damage resistance':'DMG RES',
  'pve bonus dmg':'PvE Bonus DMG','pve dmg boost':'PvE Bonus DMG','pve dmg res':'PvE DMG RES','pve damage res':'PvE DMG RES',
  'pvp bonus dmg':'PvP Bonus DMG','pvp dmg boost':'PvP Bonus DMG','pvp dmg res':'PvP DMG RES','pvp damage res':'PvP DMG RES',
  'block rate':'Block Rate','block efficiency':'Block Efficiency','accuracy':'Accuracy','effect hit rate':'Effect Hit Rate','effect hit':'Effect Hit Rate','effect res':'Effect RES','effect resistance':'Effect RES'
