 const push=(stat,val,unit)=>{stat=normalizeRelicStatV55(stat);const token=val;val=parseRelicValueV55(val);const resolvedUnit=relicUnitV55(stat,token,unit);if(stat&&val!=null&&Number.isFinite(val))out.push({stat,value:resolvedUnit==='pct'?val:val*1000,unit:resolvedUnit,source:'Source contribution',exact:true})};
