function ocrCleanNumberV58(raw){let x=String(raw||'').trim().replace(/[Oo]/g,'0').replace(/[Il|]/g,'1').replace(/,/g,'').replace(/\s+/g,'');const m=x.match(/([+-]?\d+(?:\.\d+)?)([kKmM])?/);if(!m)return null;let v=+m[1];if(/[kK]/.test(m[2]||''))v*=1000;if(/[mM]/.test(m[2]||''))v*=1000000;return v}
function regexEscapeV58(x){return String(x).replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}
function findOcrValueV58(text,aliases,pct=false){
 const lines=String(text||'').replace(/\r/g,'').split('\n').map(x=>x.replace(/[•·]/g,' ').replace(/\s+/g,' ').trim()).filter(Boolean),windows=[];for(let i=0;i<lines.length;i++){windows.push(lines[i]);if(i+1<lines.length)windows.push(lines[i]+' '+lines[i+1])}
 for(const alias of aliases){const pat=regexEscapeV58(alias).replace(/\\ /g,'\\s+'),re=new RegExp('(?:^|\\b)'+pat+'\\b[^0-9OoIl|+\\-]{0,24}([+\\-]?[0-9OoIl|][0-9OoIl|, .]*(?:[kKmM])?%?)','i');for(const line of windows){const m=line.match(re);if(!m)continue;const v=ocrCleanNumberV58(m[1]);if(v==null)continue;if(pct&&Math.abs(v)>1000)continue;if(!pct&&Math.abs(v)>2e10)continue;return v}}
 return null;
}
function normalizedWordsV58(x){return ' '+String(x||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim()+' '}
function catalogMatchesV58(text,items){const hay=normalizedWordsV58(text),out=[];for(const item of items){const n=normalizedWordsV58(item.name).trim();if(n.length<4)continue;const pos=hay.indexOf(' '+n+' ');if(pos>=0)out.push({item,pos})}return out.sort((a,b)=>a.pos-b.pos).map(x=>x.item)}
function applyDetectedSkillV58(sk,i){const id=idsForSkill('mine',i),rec=typeof inventorySkillRecordV54==='function'?inventorySkillRecordV54(sk,false):null;if(rec?.owned){$(id.rank).value=DM.rankLabels[String(rec.skillRank)]||rec.skillRank;$(id.level).value=+rec.skillLevel||num('myLevel')||100}const rk=skillRankNum($(id.rank).value),row=skillAtRank(sk,rk),est=estimateTotalCoef(sk,row);$(id.name).value=sk.name;$(id.on).checked=true;$(id.badge).textContent='Source';$(id.badge).className='source-badge exact';if(sk.element)$(id.element).value=sk.element;if(est.value!=null)$(id.coef).value=+est.value.toFixed(4);$(id.hits).value=sk.hits||1;if(row.CD!=null){$(id.cd).value=row.CD;$(id.ready).checked=+row.CD===0}$(id.meta).textContent=`${sk.cls} · #${sk.id}. Screenshot match${rec?.owned?' · rank/level from Inventory':''}.`}
function applyDetectedCharmV58(sk,i){const rec=typeof inventorySkillRecordV54==='function'?inventorySkillRecordV54(sk,false):null,id=idsForCharm('mine',i),rank=rec?.owned?String(rec.skillRank):String(skillRankNum($(id.rank).value)||16),level=rec?.owned?(+rec.skillLevel||num('myLevel')||100):(num(id.level)||num('myLevel')||100);fillCharm('mine',i,{name:sk.name,skillRank:rank,skillLevel:level})}
function parseAndApplyBuildScreenshotV58(text){
 const found=[];for(const [label,id,aliases,pct] of OCR_STAT_FIELDS_V58){const v=label==='Accuracy'?ocrAccuracyPercentV74(text,aliases,'my'):findOcrValueV58(text,aliases,pct);if(v!=null&&$(id)){ $(id).value=v;found.push([label,pct?`${v}%`:fmt(v)])}}
 for(const el of ELEMENTS){for(const [kind,suffix] of [['Affinity','Aff'],['Aegis','Aegis']]){const id='my'+suffix+el,v=findOcrValueV58(text,[`${el} ${kind}`],false);if(v!=null&&$(id)){ $(id).value=v;found.push([`${el} ${kind}`,fmt(v)])}}}
 const hay=' '+String(text||'').toLowerCase().replace(/[^a-z0-9+]+/g,' ')+' ';
 const cls=DM.classes.slice().sort((a,b)=>b.length-a.length).find(x=>hay.includes(' '+x.toLowerCase()+' '));if(cls){$('myClass').value=cls;found.push(['Class',cls])}
 const rank=RANK_NAMES.slice().sort((a,b)=>b.length-a.length).find(x=>hay.includes(' '+x.toLowerCase()+' '));if(rank){$('myRank').value=rank;found.push(['Rank',rank])}
 const lm=String(text||'').match(/(?:\bLv\.?|\bLevel)\s*[:.#-]?\s*([0-9OoIl|]{1,3})\b/i);if(lm){const lv=ocrCleanNumberV58(lm[1]);if(lv>=1&&lv<=500){$('myLevel').value=lv;found.push(['Level',lv])}}
 const tech=catalogMatchesV58(text,TECHNIQUES);if(tech.length&&tech.length<=4){tech.forEach((sk,i)=>applyDetectedSkillV58(sk,i));found.push(['Techniques',tech.map(x=>x.name).join(', ')])}else if(tech.length>4)found.push(['Techniques',`${tech.length} names detected; loadout left unchanged (ambiguous)`]);
 const charms=catalogMatchesV58(text,CHARMS);if(charms.length&&charms.length<=4){charms.forEach((sk,i)=>applyDetectedCharmV58(sk,i));found.push(['Charms',charms.map(x=>x.name).join(', ')])}else if(charms.length>4)found.push(['Charms',`${charms.length} names detected; loadout left unchanged (ambiguous)`]);
 const fant=catalogMatchesV58(text,FANTOMONS);if(fant.length===1){const f=fant[0],inv=(extras.fantInventory||[]).find(x=>x.use!==false&&String(x.name||'').toLowerCase()===f.name.toLowerCase());$('myFantomonName').value=f.name;$('myFantomonEnabled').checked=true;if(inv){$('myFantomonPhase').value=inv.adult?'Adult':'Baby';$('myFantomonRank').value=inv.skillRank||'Mythic'}else{applyFantomon('my',f)}$('myFantomonMeta').textContent=fantomonMeta(f)+(inv?' Inventory details applied.':' Screenshot match.');found.push(['Fantomon',f.name+(inv?' · Inventory details':'')])}else if(fant.length>1)found.push(['Fantomon',`${fant.length} names detected; selection left unchanged (ambiguous)`]);
 if(typeof renderSkillInventoryV54==='function'&&$('inventorySkillsPaneV54')?.classList.contains('active'))scheduleSkillInventoryV57();syncFantomonUI();recalc();return found;
}
function loadExternalScriptV58(src){return new Promise((resolve,reject)=>{const old=[...document.scripts].find(x=>x.src===src);if(old){if(window.Tesseract)resolve();else old.addEventListener('load',resolve,{once:true});return}const sc=document.createElement('script');sc.src=src;sc.async=true;sc.onload=resolve;sc.onerror=reject;document.head.appendChild(sc)})}
async function ensureTesseractV58(){if(window.Tesseract)return window.Tesseract;for(const src of ['https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js','https://unpkg.com/tesseract.js@5/dist/tesseract.min.js']){try{await loadExternalScriptV58(src);if(window.Tesseract)return window.Tesseract}catch(e){}}throw Error('OCR library could not be loaded. Check your internet connection and try again.')}
async function imageCanvasV58(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{try{const max=2200,scale=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.naturalWidth*scale));c.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(url);resolve(c)}catch(e){URL.revokeObjectURL(url);reject(e)}};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Could not read '+file.name))};img.src=url})}
function setScreenshotStatusV58(text,pct){const box=$('buildScreenshotProgressV58'),bar=$('buildScreenshotProgressBarV58'),label=$('buildScreenshotStatusV58');box?.classList.remove('hidden');if(label)label.textContent=text;if(bar)bar.style.width=Math.max(0,Math.min(100,pct||0))+'%'}
function showScreenshotPreviewsV58(files){const host=$('buildScreenshotPreviewV58');if(!host)return;host.innerHTML='';for(const f of files){const img=document.createElement('img');img.className='screenshot-preview-v58';img.alt=f.name;const url=URL.createObjectURL(f);img.src=url;img.onload=()=>setTimeout(()=>URL.revokeObjectURL(url),1000);host.appendChild(img)}}
async function importBuildScreenshotsV58(files){files=[...files].filter(f=>f.type.startsWith('image/'));if(!files.length)return;showScreenshotPreviewsV58(files);const result=$('buildScreenshotResultV58'),details=$('buildScreenshotTextDetailsV58'),textBox=$('buildScreenshotTextV58');result?.classList.add('hidden');details?.classList.add('hidden');setScreenshotStatusV58('Loading OCR…',2);try{const T=await ensureTesseractV58();setScreenshotStatusV58('Starting OCR…',5);let worker=null,all=[];try{worker=await T.createWorker('eng',1,{logger:m=>{if(m.status&&typeof m.progress==='number')setScreenshotStatusV58(`${m.status} · ${Math.round(m.progress*100)}%`,5+m.progress*80/files.length)}})}catch(e){}
 for(let i=0;i<files.length;i++){setScreenshotStatusV58(`Reading ${i+1} of ${files.length}: ${files[i].name}`,5+(i/files.length)*85);const canvas=await imageCanvasV58(files[i]);let r;if(worker)r=await worker.recognize(canvas);else r=await T.recognize(canvas,'eng',{logger:m=>{if(typeof m.progress==='number')setScreenshotStatusV58(`Reading ${i+1} of ${files.length} · ${Math.round(m.progress*100)}%`,5+((i+m.progress)/files.length)*85)}});all.push(r?.data?.text||'')}
 if(worker)await worker.terminate();const text=all.join('\n\n--- screenshot ---\n\n'),found=parseAndApplyBuildScreenshotV58(text);if(textBox)textBox.textContent=text;if(details)details.classList.toggle('hidden',!text.trim());if(result){result.classList.remove('hidden');result.innerHTML=found.length?`<b>Applied ${found.length} detected field groups.</b><div class="screenshot-result-grid-v58">${found.map(([k,v])=>`<span class="screenshot-result-chip-v58"><b>${esc(k)}</b>${esc(String(v))}</span>`).join('')}</div><p class="hint" style="margin:8px 0 0">Review the populated fields before relying on the result. OCR never clears a field it could not identify.</p>`:'No build fields were confidently recognized. Open “Review detected text” to see what OCR read.'}setScreenshotStatusV58(`Finished · ${files.length} screenshot${files.length===1?'':'s'}`,100);toast(found.length?`Screenshot import applied ${found.length} field groups`:'Screenshot OCR finished; no confident fields found')
 }catch(err){setScreenshotStatusV58('Screenshot import failed',0);if(result){result.classList.remove('hidden');result.innerHTML=`<b>Could not read screenshots.</b><br><span class="hint">${esc(err.message||String(err))}</span>`}toast('Screenshot import failed')}}
