function ensureV59(){ensureV5();extras.v5=extras.v5||{};extras.v5.equippedGearIdsV59=extras.v5.equippedGearIdsV59&&typeof extras.v5.equippedGearIdsV59==='object'?extras.v5.equippedGearIdsV59:{};if(!extras.v5.gearEquipMigratedV59){for(const it of extras.inventory||[])if(it.equipped&&it.slot&&!extras.v5.equippedGearIdsV59[it.slot])extras.v5.equippedGearIdsV59[it.slot]=it.id;for(const it of extras.inventory||[]){it.use=true;it.equipped=false}extras.v5.gearEquipMigratedV59=true;saveExtras()}return extras.v5}
