function renderInventory(){const body=$('inventoryBody');if(!body)return;ensureV59();body.innerHTML='';extras.inventory.forEach((it,idx)=>{it.use=true;it.equipped=false;const tr=document.createElement('tr');tr.dataset.id=it.id;tr.innerHTML=`<td class="wide"><input class="inv-name" value="${esc(it.name||'')}" autocomplete="off"><div class="tiny muted inv-meta">${esc(String(it.source||'custom').replace(/datamine/ig,'Source data'))}</div></td><td><input class="inv-slot" value="${esc(it.slot||'')}" autocomplete="off"></td><td><input class="inv-secondary" value="${esc(it.secondary||'')}" autocomplete="off"></td><td><input class="inv-set" value="${esc(it.set||'')}" autocomplete="off"></td><td class="stats-text"><input class="inv-stats" value="${esc(statsText(it.stats||[]))}" placeholder="spd:6418, atk:3209"></td><td><button class="icon-btn inv-remove" type="button">×</button></td>`;body.appendChild(tr);const name=tr.querySelector('.inv-name'),sec=tr.querySelector('.inv-secondary');attachCombo(name,gearOptions,o=>{const g=o.gear||GEAR_BY_NAME.get(o.label.toLowerCase());if(!g)return;name.value=g.name;it.name=g.name;it.slot=canonicalSlot(g);it.set=(g.sets||[])[0]||'';it.secondary=(g.secondaries||[])[0]?.label||'';it.stats=itemStatsFromGear(g,it.secondary);it.source='datamine';saveExtras();renderInventory();renderCurrentGearLoadoutV59()});attachCombo(tr.querySelector('.inv-slot'),GEAR_SLOTS_V59);attachCombo(sec,()=>{const g=runtimeGear.find(g=>g.name===name.value);return(g?.secondaries||[]).map(x=>({label:x.label,sub:fmt(x.value),sec:x}))},o=>{const g=runtimeGear.find(g=>g.name===name.value),sv=(g?.secondaries||[]).find(x=>x.label===o.label);if(g&&sv){it.secondary=sv.label;it.stats=itemStatsFromGear(g,sv.label);saveExtras();renderInventory();renderCurrentGearLoadoutV59()}});tr.querySelectorAll('input').forEach(inp=>inp.addEventListener('change',()=>{const oldSlot=it.slot;it.name=name.value;it.slot=tr.querySelector('.inv-slot').value;it.secondary=sec.value;it.set=tr.querySelector('.inv-set').value;it.stats=parseStatsText(tr.querySelector('.inv-stats').value);it.use=true;it.equipped=false;const map=ensureV59().equippedGearIdsV59;if(oldSlot!==it.slot&&map[oldSlot]===it.id){delete map[oldSlot];map[it.slot]=it.id}saveExtras();renderCurrentGearLoadoutV59()}));tr.querySelector('.inv-remove').onclick=()=>{const map=ensureV59().equippedGearIdsV59;for(const k of Object.keys(map))if(map[k]===it.id)delete map[k];extras.inventory.splice(idx,1);saveExtras();renderInventory();renderCurrentGearLoadoutV59();recalc()}});renderCurrentGearLoadoutV59()}
