function relicBundleForNamesV59(build,names){const scalePct={},flat={},points={},active=[],rank=rankObj(build.rank),chosen=new Set(names||[]),add=(stat,value,unit='pct',source='',exact=true)=>{value=+value||0;if(!value||!stat)return;if(stat==='Accuracy'){if(unit==='pct')flat.acc=(flat.acc||0)+value/100*Math.max(1,rank.BaseBlockAvoidPercentValue||1);else flat.acc=(flat.acc||0)+value}else if(RELIC_SCALE_KEYS_V51[stat]){const k=RELIC_SCALE_KEYS_V51[stat];if(unit==='pct')scalePct[k]=(scalePct[k]||0)+value;else flat[k]=(flat[k]||0)+value}else if(RELIC_POINT_KEYS_V51[stat]){const k=RELIC_POINT_KEYS_V51[stat];points[k]=(points[k]||0)+value}active.push({source,stat,value,unit,exact})};for(const set of RELIC_SETS_V51){const st=relicSetStatusV51(set);for(const tier of ['complete','star3','awakened'])if(st[tier]){const [stat,value,unit='pct']=set.bonuses[tier]||[];if(value!=null&&Number.isFinite(+value))add(stat,+value,unit,`${set.name} · ${relicTierLabelV51(tier)}`,true)}for(const name of set.relics)if(chosen.has(name)){const r=relicStateV51(name);if(r.owned)for(const e of resolvedRelicEffectsV55(name,r))add(e.stat,e.value,e.unit,name,e.exact)}}return{scalePct,flat,points,active}}
function relicSheetForNamesV59(build,names){const base=deep(build),b=deep(build),bundle=relicBundleForNamesV59(base,names);for(const [k,p] of Object.entries(bundle.scalePct))b[k]=(base[k]||0)*(1+p/100)+(bundle.flat[k]||0);for(const [k,v] of Object.entries(bundle.flat))if(bundle.scalePct[k]==null)b[k]=(b[k]||0)+v;for(const [k,v] of Object.entries(bundle.points))b[k]=(b[k]||0)+v;b.hp=Math.max(1,b.hp||1);b.atk=Math.max(1,b.atk||1);b.def=Math.max(0,b.def||0);b.spd=Math.max(1,b.spd||1);return{sheet:b,bundle}}
function relicScoreV59(sheet,s,obj){if(obj==='Survivability')return survivabilityMetrics(sheet,s.enemy).effectiveHp;const pve=pveRotation(sheet,s,s.skills,effectivePveFantomon(),equippedGearV59()).total;if(obj==='Balanced')return Math.sqrt(Math.max(1,pve)*Math.max(1,survivabilityMetrics(sheet,s.enemy).effectiveHp));if(obj==='PvP analytical'){const B=s.pvp.enemy,fake={enemy:{...B,pveres:B.pvpres||0,skillred:0},turns:15,skills:s.skills},d=damagePerAction(sheet,fake),rate=Math.sqrt(sheet.spd*rankObj(sheet.rank).speedScale/(Math.max(1,B.spd)*rankObj(B.rank).speedScale)),tKill=B.hp/Math.max(1,d*rate);return 1/Math.max(.01,tKill)}return pve}
