function runRelicOptimizerV59(){ensureV5();const out=$('relicLabResultV59');if(extras.v5.relicSheetIncludes!==false){out.innerHTML='<div class="v2-warn">Relic bonuses are marked as already included in the entered sheet. Turn on automatic Relic application in Current Build before optimizing, otherwise a relic swap cannot be separated from the sheet safely.</div>';return}const s=collect(),raw=collectBuild('my'),all=RELIC_SETS_V51.flatMap(x=>x.relics).filter(n=>relicStateV51(n).owned),numeric=all.filter(n=>resolvedRelicEffectsV55(n,relicStateV51(n)).length);if(!all.length){out.innerHTML='<div class="v2-warn">Mark owned Relics in Inventory first.</div>';return}if(!numeric.length){out.innerHTML='<div class="v2-warn">None of the owned Relics currently has a numeric equip effect that can be scored.</div>';return}const obj=$('relicLabObjectiveV59').value,slots=Math.min(Math.max(1,+$('relicLabSlotsV59').value||4),all.length),beamW=Math.max(10,+$('relicLabBeamV59').value||80),cap=Math.max(8,+$('relicLabCandidatesV59').value||40),one=numeric.map(n=>{const z=relicSheetForNamesV59(raw,[n]).sheet;return{name:n,score:relicScoreV59(z,s,obj)}}).sort((a,b)=>b.score-a.score),current=currentEquippedRelicNamesV59();let candidates=[...new Set(one.slice(0,cap).map(x=>x.name).concat(current.filter(n=>all.includes(n))))];if(candidates.length<slots)candidates=[...new Set(candidates.concat(all))].slice(0,Math.max(slots,cap));let beam=[{names:[],score:relicScoreV59(relicSheetForNamesV59(raw,[]).sheet,s,obj)}];for(let step=0;step<slots;step++){const next=[];for(const b of beam){for(const n of candidates){if(b.names.includes(n))continue;const names=b.names.concat(n).sort(),key=names.join('|');const z=relicSheetForNamesV59(raw,names).sheet;next.push({names,score:relicScoreV59(z,s,obj),key})}}const uniq=new Map();for(const r of next){const old=uniq.get(r.key);if(!old||r.score>old.score)uniq.set(r.key,r)}beam=[...uniq.values()].sort((a,b)=>b.score-a.score).slice(0,beamW);if(!beam.length)break}const results=beam.sort((a,b)=>b.score-a.score).slice(0,5),curSheet=relicSheetForNamesV59(raw,current).sheet,curScore=relicScoreV59(curSheet,s,obj);RELIC_LAB_BEST_V59=results[0]||null;$('applyRelicLabV59').disabled=!RELIC_LAB_BEST_V59;out.innerHTML=results.length?`<div class="relic-lab-list-v59">${results.map((r,i)=>{const delta=curScore?((r.score/curScore)-1)*100:0;return `<div class="relic-lab-combo-v59 ${i===0?'best':''}"><div><b>${i===0?'Recommended':'#'+(i+1)}</b> · score ${fmt(r.score,2)} · <span class="${delta>=0?'positive':'negative'}">${delta>=0?'+':''}${delta.toFixed(2)}% vs current</span></div><div class="relic-lab-relics-v59">${r.names.map(n=>`<span>${esc(n)}</span>`).join('')}</div></div>`}).join('')}</div><p class="hint" style="margin-top:10px">Candidate prefilter kept ${candidates.length} owned Relics; beam width ${beamW}. Relics with unknown equip magnitudes cannot improve the numeric score unless selected only to fill an otherwise empty slot.</p>`:'<div class="v2-warn">No candidate combination could be scored.</div>';renderRelicLabStatusV59()}
