function ensureRelicEquipSlotsV60(){ensureV5();const v=extras.v5;if(!v.relicEquipByAffinityV60||typeof v.relicEquipByAffinityV60!=='object')v.relicEquipByAffinityV60={};const affinities=relicAffinityListV60();for(const a of affinities){let arr=Array.isArray(v.relicEquipByAffinityV60[a])?v.relicEquipByAffinityV60[a].slice(0,4):[];while(arr.length<4)arr.push('');v.relicEquipByAffinityV60[a]=arr}
 if(!v.relicAffinityEquipMigratedV60){const old=[];for(const set of RELIC_SETS_V51)for(const n of set.relics){const r=relicStateV51(n);if(r.owned&&r.equipped)old.push(n)}for(const n of old){const a=relicAffinityV60(n),arr=v.relicEquipByAffinityV60[a]||(v.relicEquipByAffinityV60[a]=['','','','']);if(!arr.includes(n)){const i=arr.findIndex(x=>!x);if(i>=0)arr[i]=n}}v.relicAffinityEquipMigratedV60=true}
 const used=new Set();for(const a of Object.keys(v.relicEquipByAffinityV60)){const arr=v.relicEquipByAffinityV60[a];for(let i=0;i<4;i++){const n=String(arr[i]||'');const r=n?relicStateV51(n):null;if(!n||!r?.owned||relicAffinityV60(n)!==a||used.has(n))arr[i]='';else used.add(n)}}for(const set of RELIC_SETS_V51)for(const n of set.relics)relicStateV51(n).equipped=used.has(n);return v.relicEquipByAffinityV60}
