function renderCurrentRelicLoadoutV60(){const host=$('currentRelicAffinityGridV60');if(!host)return;const map=ensureRelicEquipSlotsV60(),affs=relicAffinityListV60();host.innerHTML=affs.map(a=>{const owned=RELIC_SETS_V51.flatMap(s=>s.relics).filter(n=>{const r=relicStateV51(n);return r.owned&&relicAffinityV60(n)===a}).sort((x,y)=>x.localeCompare(y));const slots=map[a]||['','','',''];return `<div class="relic-affinity-row-v60"><div class="relic-affinity-label-v60">${esc(a)}</div><div class="relic-affinity-slots-v60">${[0,1,2,3].map(i=>{const n=slots[i]||'',opts=['',...owned].map(x=>`<button type="button" class="relic-slot-option-v60 ${x===n?'selected':''}" data-affinity="${esc(a)}" data-slot="${i}" data-name="${esc(x)}"><b>${x?esc(x):'Empty slot'}</b>${x?`<small>${esc(relicSlotEffectTextV60(x))}</small>`:''}</button>`).join('');return `<div class="relic-slot-v60 ${n?'':'relic-slot-empty-v60'}"><button type="button" class="relic-slot-trigger-v60" aria-expanded="false"><span class="relic-slot-name-v60">${n?esc(n):`Relic ${i+1}`}</span><span class="relic-slot-meta-v60">${esc(relicSlotEffectTextV60(n))}</span></button><div class="relic-slot-menu-v60">${owned.length?opts:'<div class="relic-affinity-empty-v60">No owned Relics for this affinity.</div>'}</div></div>`}).join('')}</div></div>`}).join('');host.onclick=e=>{const option=e.target.closest('.relic-slot-option-v60');if(option){e.preventDefault();setRelicEquipSlotV60(option.dataset.affinity,+option.dataset.slot,option.dataset.name);return}const trigger=e.target.closest('.relic-slot-trigger-v60');if(trigger){e.preventDefault();const box=trigger.closest('.relic-slot-v60'),open=!box.classList.contains('open');host.querySelectorAll('.relic-slot-v60.open').forEach(x=>{x.classList.remove('open');x.querySelector('.relic-slot-trigger-v60')?.setAttribute('aria-expanded','false')});if(open){box.classList.add('open');trigger.setAttribute('aria-expanded','true')}}};}

