// Equip effects now come only from the four selected slots for each affinity; collection set milestones remain global.
function relicBonusBundleV51(build){const scalePct={},flat={},points={},active=[],rank=rankObj(build.rank),chosen=new Set(currentEquippedRelicNamesV59()),add=(stat,value,unit='pct',source='',exact=true)=>{stat=normalizeRelicStatV55(stat);value=+value||0;if(!value||!stat)return;if(stat==='Accuracy'){if(unit==='pct')flat.acc=(flat.acc||0)+value/100*Math.max(1,rank.BaseBlockAvoidPercentValue||1);else flat.acc=(flat.acc||0)+value}else if(stat==='Effect Hit Rate'){if(unit==='pct')flat.erate=(flat.erate||0)+value/100*Math.max(1,rank.BaseEffectRate||1);else flat.erate=(flat.erate||0)+value}else if(stat==='Effect RES'){if(unit==='pct')flat.edodge=(flat.edodge||0)+value/100*Math.max(1,rank.BaseEffectDodge||1);else flat.edodge=(flat.edodge||0)+value}else if(RELIC_SCALE_KEYS_V51[stat]){const k=RELIC_SCALE_KEYS_V51[stat];if(unit==='pct')scalePct[k]=(scalePct[k]||0)+value;else flat[k]=(flat[k]||0)+value}else if(RELIC_POINT_KEYS_V51[stat]){const k=RELIC_POINT_KEYS_V51[stat];points[k]=(points[k]||0)+value}if(source)active.push({source,stat,value,unit,exact})};for(const set of RELIC_SETS_V51){const st=relicSetStatusV51(set);for(const tier of ['complete','star3','awakened'])if(st[tier]){const [stat,value,unit='pct']=set.bonuses[tier]||[];if(value!=null&&Number.isFinite(+value))add(stat,+value,unit,`${set.name} · ${relicTierLabelV51(tier)}`,true)}for(const name of set.relics)if(chosen.has(name)){const r=relicStateV51(name);if(r.owned)for(const e of resolvedRelicEffectsV55(name,r))add(e.stat,e.value,e.unit,name,e.exact)}}return{scalePct,flat,points,active}}

