// Per-affinity Relic optimizer. The combat objective already uses the currently equipped Techniques and Charms.
let RELIC_LAB_BEST_V60=null;
function optimizeRelicAffinityV60(affinity,globalMap,s,raw,obj,beamW,cap){const all=RELIC_SETS_V51.flatMap(x=>x.relics).filter(n=>relicStateV51(n).owned&&relicAffinityV60(n)===affinity),target=Math.min(4,all.length);if(!target)return {affinity,names:[],score:relicScoreV59(relicSheetForNamesV59(raw,Object.values(globalMap).flat().filter(Boolean)).sheet,s,obj)};const baseOther=Object.entries(globalMap).filter(([a])=>a!==affinity).flatMap(([,v])=>v).filter(Boolean),one=all.map(n=>{const names=[...baseOther,n];return{name:n,score:relicScoreV59(relicSheetForNamesV59(raw,names).sheet,s,obj)}}).sort((a,b)=>b.score-a.score);let candidates=[...new Set(one.slice(0,cap).map(x=>x.name).concat((globalMap[affinity]||[]).filter(Boolean)))];if(candidates.length<target)candidates=[...new Set(candidates.concat(all))];let beam=[{names:[],score:0}];for(let step=0;step<target;step++){const next=[];for(const b of beam)for(const n of candidates){if(b.names.includes(n))continue;const local=b.names.concat(n),full=[...baseOther,...local],score=relicScoreV59(relicSheetForNamesV59(raw,full).sheet,s,obj);next.push({names:local,score})}const uniq=new Map();for(const r of next){const k=r.names.slice().sort().join('|');const o=uniq.get(k);if(!o||r.score>o.score)uniq.set(k,r)}beam=[...uniq.values()].sort((a,b)=>b.score-a.score).slice(0,beamW)}return {affinity,...(beam[0]||{names:[],score:0}),owned:all.length,candidates:candidates.length}}
