 ensureV3();activeHazardsV3=[];const units=[];for(const side of ['A','B'])for(let i=0;i<4;i++)units.push(makeTeamUnitV3(side,i,extras.v3.team[side][i],extras.v3.team.pos[side][i]));for(const u of units)u.flip=false;
