renderFantInventoryV5=function(force=false){ensureV5();const body=$('fantInventoryBody');if(!body||(!force&&!inventoryVisibleV62('fant')))return;body.innerHTML='';extras.fantInventory.forEach((it,i)=>{if(it.adult==null)it.adult=String(it.phase||'Adult').toLowerCase()==='adult';delete it.phase;delete it.use;const f=FANTOMON_BY_NAME.get(String(it.name||'').toLowerCase()),tr=document.createElement('tr');tr.innerHTML=`<td class="wide"><input class="fi-name" value="${esc(it.name||'')}" autocomplete="off"></td><td><input class="fi-level" type="number" min="1" value="${+it.level||100}"></td><td style="text-align:center"><input class="fi-adult" type="checkbox" ${it.adult?'checked':''}></td><td><input class="fi-rank" value="${esc(it.skillRank||'Mythic')}"></td><td class="tiny">${f?`${esc(f.role)}<br>${esc(f.support||'')}`:'Custom Fantomon'}</td><td><button class="icon-btn fi-remove">×</button></td>`;body.appendChild(tr);const name=tr.querySelector('.fi-name');attachCombo(name,fantomonOptions,o=>{name.value=o.label;it.name=o.label;saveExtras();renderFantInventoryV5(true)});tr.querySelectorAll('input').forEach(inp=>inp.onchange=()=>{it.name=name.value.trim();it.level=+tr.querySelector('.fi-level').value||100;it.adult=tr.querySelector('.fi-adult').checked;it.skillRank=tr.querySelector('.fi-rank').value;saveExtras();renderInventorySummaryV5();if(String($('myFantomonName')?.value||'').trim().toLowerCase()===it.name.toLowerCase())syncMyFantomonFromInventoryV54()});tr.querySelector('.fi-remove').onclick=()=>{extras.fantInventory.splice(i,1);saveExtras();renderFantInventoryV5(true);renderInventorySummaryV5()}})};
