// Lightweight build changes: expensive comparison derivatives run only on Compare.
function recalcLightV62(){try{if(activeTabV62('compare')){recalcImmediateV57();return}state=collect();saveOnly();if(activeTabV62('pvp'))updatePvpSummary()}catch(e){}}
