// Owned skill pools use the rank/level actually stored in Inventory and class-lineage legality.
function ownedSkillPoolV62(kind,s){ensureV54();const src=kind==='Charm'?CHARMS:TECHNIQUES;return Object.values(extras.skillInventory||{}).filter(r=>r.owned&&r.kind===kind).map(r=>{const sk=src.find(x=>String(x.id)===String(r.id))||SKILL_BY_NAME.get(String(r.name||'').toLowerCase());if(!sk||!legalSkillClassV4(sk.cls,s.build.className))return null;const rank=+r.skillRank||1,level=+r.skillLevel||s.build.level;if(kind==='Technique'){const row=skillAtRank(sk,rank),est=estimateTotalCoef(sk,row);return{on:true,name:sk.name,id:sk.id,skillRank:String(rank),skillLevel:level,element:sk.element||'Physical',coef:est.value??0,flat:0,hits:sk.hits||1,cd:+row.CD||0,ready:(+row.CD||0)===0,weight:1}}return{name:sk.name,id:sk.id,skillRank:String(rank),skillLevel:level}}).filter(Boolean)}
techPoolV2=function(s){return ownedSkillPoolV62('Technique',s)};charmPoolV2=function(s){return ownedSkillPoolV62('Charm',s)};gearCombosV2=function(s,cap){const pool=(extras.inventory||[]).filter(seasonEligibleV62),by={};for(const x of pool)(by[x.slot||'Custom']??=[]).push(x);const groups=Object.values(by);return groups.length?cartesian(groups,Math.min(cap||2500,2500)):[equippedGearV59()]};

async function runGearOptimizerV62(){
 if(V62.gearRunning)return; V62.gearRunning=true;
 const btn=$('runGearOptimizerBtn'); if(btn){btn.disabled=true;btn.textContent='Optimizing…'}
 try{
  const s=collect(),pool=(extras.inventory||[]).filter(seasonEligibleV62),by={};
  for(const x of pool)(by[x.slot||'Custom']??=[]).push(x);
  const groups=Object.values(by);
  if(!groups.length){$('gearOptimizerResult').innerHTML=`<p class="negative">No owned gear is eligible for Season ${currentSeasonV62()}. Set each item's season in Inventory.</p>`;return}
  const cap=clamp(num('gearSearchCap')||12000,100,100000),obj=$('gearObjective').value,idx=new Array(groups.length).fill(0),best=[];
  let tested=0,done=false;
  while(!done&&tested<cap){
   const combo=groups.map((g,i)=>g[idx[i]]),score=gearObjectiveValue(combo,s,obj),sheet=inventorySheetFor(combo,s);
   if(Number.isFinite(score)){best.push({combo,score,sheet});best.sort((a,b)=>b.score-a.score);if(best.length>12)best.length=12}
   tested++;
   for(let pos=groups.length-1;pos>=0;pos--){idx[pos]++;if(idx[pos]<groups[pos].length)break;idx[pos]=0;if(pos===0)done=true}
   if(tested%250===0){if(btn)btn.textContent=`Optimizing… ${fmt(tested)}`;await yieldUiV62()}
  }
  let scored=best.slice(0,5);
  if(obj==='PvP win estimate'){
   for(let i=0;i<scored.length;i++){scored[i].win=quickWinRate(scored[i].sheet,s.pvp.enemy,s.skills,s.pvp.skills,s.charms,s.pvp.charms,s.fantomon,s.pvp.enemyFantomon,80);await yieldUiV62()}
   scored.sort((a,b)=>b.win-a.win);
  }
  lastBestGear=scored[0]||null;$('saveBestGearBtn').disabled=!lastBestGear;
  const capNote=done?'':' (search cap reached)';
  const cards=scored.map((r,i)=>`<div class="build-result ${i===0?'best':''}"><h4>${i===0?'Best build':'#'+(i+1)} · ${obj==='PvP win estimate'?(r.win*100).toFixed(1)+'% win':fmt(r.score)}</h4><div class="build-lines">${r.combo.map(x=>`<span><b>${esc(x.slot)}</b> ${esc(x.name)}</span>`).join('')}<span><b>SPD</b> ${fmt(r.sheet.spd)}</span><span><b>ATK</b> ${fmt(r.sheet.atk)}</span></div></div>`).join('')||'<p>No legal build met the constraints.</p>';
  $('gearOptimizerResult').innerHTML=`<p class="hint">Season ${currentSeasonV62()} · ${fmt(tested)} candidate builds evaluated${capNote}.</p>`+cards;
 }finally{V62.gearRunning=false;if(btn){btn.disabled=false;btn.textContent='Optimize owned gear'}}
}
runGearOptimizer=runGearOptimizerV62;

async function runTechOptimizerV62(){if(V62.techRunning)return;V62.techRunning=true;const btn=$('runTechOptimizerBtn');btn.disabled=true;btn.textContent='Optimizing…';try{const s=collect(),raw=ownedSkillPoolV62('Technique',s);if(raw.length<4){$('techOptimizerResult').innerHTML=`<p class="negative">You need at least 4 owned, class-legal Techniques in Inventory. Found ${raw.length}.</p>`;return}let pool=raw;if(pool.length>16){const ranked=[];for(let i=0;i<pool.length;i++){ranked.push({sk:pool[i],score:pveRotation(s.build,s,[pool[i]],s.fantomon,[]).total});if(i%6===0)await yieldUiV62()}pool=ranked.sort((a,b)=>b.score-a.score).slice(0,16).map(x=>x.sk)}const sets=combinations(pool,4,3500),best=[];for(let i=0;i<sets.length;i++){const c=sets[i],score=pveRotation(s.build,{...s,skills:c},c,s.fantomon,equippedGearV59()).total;best.push({c,score});if(i%100===0){btn.textContent=`Optimizing… ${i+1}/${sets.length}`;await yieldUiV62()}}best.sort((a,b)=>b.score-a.score);$('techOptimizerResult').innerHTML=`<p class="hint">${raw.length} owned/legal Techniques considered at Inventory rank/level${raw.length>16?' · pre-ranked to 16 for responsive combination search':''}.</p>`+best.slice(0,5).map((x,i)=>`<div class="build-result ${i===0?'best':''}"><b>${i===0?'Best':'#'+(i+1)}</b> · ${fmt(x.score)} total<br><small>${x.c.map(q=>esc(q.name)).join(' · ')}</small></div>`).join('')}finally{V62.techRunning=false;btn.disabled=false;btn.textContent='Optimize owned Techniques'}}
runTechOptimizer=runTechOptimizerV62;

async function runCharmOptimizerV62(){if(V62.charmRunning)return;V62.charmRunning=true;const btn=$('runCharmOptimizerBtn');btn.disabled=true;btn.textContent='Optimizing…';try{const s=collect(),raw=ownedSkillPoolV62('Charm',s);if(raw.length<4){$('charmOptimizerResult').innerHTML=`<p class="negative">You need at least 4 owned, class-legal Charms in Inventory. Found ${raw.length}.</p>`;return}let pool=raw;if(pool.length>14){pool=pool.map(c=>{const rr=charmRow(c),mag=Object.values(rr?.row||{}).reduce((z,v)=>z+(Number.isFinite(+v)?Math.abs(+v):0),0)+(CHARM_ACTIVE_IDS.has(+c.id)?1e6:0);return{c,mag}}).sort((a,b)=>b.mag-a.mag).slice(0,14).map(x=>x.c)}const sets=combinations(pool,4,1200),best=[];for(let i=0;i<sets.length;i++){const c=sets[i],win=quickWinRate(s.build,s.pvp.enemy,s.skills,s.pvp.skills,c,s.pvp.charms,s.fantomon,s.pvp.enemyFantomon,40);best.push({c,win});if(i%40===0){btn.textContent=`Optimizing… ${i+1}/${sets.length}`;await yieldUiV62()}}best.sort((a,b)=>b.win-a.win);$('charmOptimizerResult').innerHTML=`<p class="hint">${raw.length} owned/legal Charms considered at Inventory rank/level${raw.length>14?' · effect-weighted prefilter to 14 for responsive search':''}.</p>`+best.slice(0,5).map((x,i)=>`<div class="build-result ${i===0?'best':''}"><b>${i===0?'Best':'#'+(i+1)}</b> · ${(x.win*100).toFixed(1)}% win estimate<br><small>${x.c.map(q=>esc(q.name)).join(' · ')}</small></div>`).join('')}finally{V62.charmRunning=false;btn.disabled=false;btn.textContent='Optimize owned Charms'}}
