// Accuracy is displayed as a percentage in the calculator, but screenshots may expose the underlying flat K/M rating.
function ocrAccuracyPercentV74(text,aliases,scope='my'){
 const lines=String(text||'').replace(/\r/g,'').split('\n').map(x=>x.replace(/[•·]/g,' ').replace(/\s+/g,' ').trim()).filter(Boolean),windows=[];
 for(let i=0;i<lines.length;i++){windows.push(lines[i]);if(i+1<lines.length)windows.push(lines[i]+' '+lines[i+1])}
 let token='';outer:for(const alias of aliases){const pat=regexEscapeV58(alias).replace(/\\ /g,'\\s+'),re=new RegExp('(?:^|\\b)'+pat+'\\b[^0-9OoIl|+\\-]{0,24}([+\\-]?[0-9OoIl|][0-9OoIl|, .]*(?:[kKmM])?%?)','i');for(const line of windows){const m=line.match(re);if(m){token=m[1];break outer}}}
 if(!token)return null;const v=ocrCleanNumberV58(token);if(v==null)return null;if(token.includes('%'))return v;
 const hay=' '+String(text||'').toLowerCase().replace(/[^a-z0-9+]+/g,' ')+' ',detected=RANK_NAMES.slice().sort((a,b)=>b.length-a.length).find(x=>hay.includes(' '+x.toLowerCase()+' ')),rank=detected||$(scope==='my'?'myRank':'pvpEnemyRank')?.value||'No Rank',base=rankObj(rank).BaseBlockAvoidPercentValue||1;
 return v>100?+(v/base*100).toFixed(4):v;
}
