function generalClassObjectiveV74(st,obj,s){if(obj==='Survivability')return survivabilityMetrics(st.build,s.pvp.enemy).effectiveHp;if(obj==='Support')return supportMetricsV2(st.build,{...s,skills:st.skills,charms:st.charms},st.skills,st.fantomon,equippedGearV59()).utility;if(obj==='Team PvP win rate')return quickWinRate(st.build,s.pvp.enemy,st.skills,s.pvp.skills,st.charms,s.pvp.charms,st.fantomon,s.pvp.enemyFantomon,80);const dmg=pveRotation(st.build,{...s,skills:st.skills,charms:st.charms},st.skills,st.fantomon,equippedGearV59()).total;if(obj==='Balanced')return Math.sqrt(Math.max(1,dmg)*Math.max(1,survivabilityMetrics(st.build,s.pvp.enemy).effectiveHp));return dmg}
