 let fp=ownedOnly?(extras.fantInventory||[]).filter(x=>x.use!==false&&x.name).map(x=>FANTOMON_BY_NAME.get(String(x.name).toLowerCase())).filter(Boolean):FANTOMONS;const fs=fp.map(f=>({f,...chaosFantScoreV60(f)})).sort((a,b)=>b.score-a.score).slice(0,4);if(!fs.length)fs.push(null);
